local config = {
  ui_story_5033_50330101_X1_dialog_content = "사...살려줘...",
  ui_story_5033_50330101_X2_dialog_content = "살려... 으윽...",
  ui_story_5033_50330101_1_dialog_content = "<color=#e8d9bb>철퍼덕!</color>",
  ui_story_5033_50330101_2_dialog_content = "엄마! 저기 좀 봐요! 어떤 사람이 걷다가 갑자기 쓰러졌어요!",
  ui_story_5033_50330101_3_dialog_content = "엄마가 가서 무슨 일인지 보고 올 테니까, 여기서 얌전히 기다리고 있어.",
  ui_story_5033_50330101_4_dialog_content = "어, 이, 이 사람...",
  ui_story_5033_50330101_5_dialog_content = "<size=45>꺄아아아아아악!</size>",
  ui_story_5033_50330101_6_dialog_content = "<color=#e8d9bb>움브라톤의 어느 골목</color>",
  ui_story_5033_50330101_7_dialog_content = "(또 한발 늦었나...)",
  ui_story_5033_50330101_8_dialog_content = "그때 그 사람 근처에 정말 다른 사람은 없었습니까?",
  ui_story_5033_50330101_9_dialog_content = "어, 없었어요... 제 아들도 그 사람이 쓰러지는 순간밖에 못 봤어요...",
  ui_story_5033_50330101_10_dialog_content = "걷다가 두 번 비틀거리더니, 땅바닥에 고꾸라졌었죠...",
  ui_story_5033_50330101_11_dialog_content = "제가 다가갔을 땐 이미...",
  ui_story_5033_50330101_12_dialog_content = "그렇군요. 잘 알았습니다.",
  ui_story_5033_50330101_13_dialog_content = "여긴 제가 처리하죠. 두 사람은 이제 가 봐도 좋습니다.",
  ui_story_5033_50330101_14_dialog_content = "요즘 움브라톤은 그렇게 평온하지 않으니까,\n되도록 골목으로는 안 다니는 게 좋을 겁니다.",
  ui_story_5033_50330101_15_dialog_content = "아...!",
  ui_story_5033_50330101_16_dialog_content = "그, 그럼 부탁드릴게요...",
  ui_story_5033_50330101_17_dialog_content = "가자, 얘야. 자꾸 보면 못 써.",
  ui_story_5033_50330101_18_dialog_content = "하아...",
  ui_story_5033_50330101_19_dialog_content = "(단서가 또 끊겨버렸어. 여전히 범인의 행동력을 따라잡을 수가 없잖아.)",
  ui_story_5033_50330101_20_dialog_content = "(확인할 수 있는 건 사망자의 시신이 <color=#FFB400>이전 사건들</color>처럼 수상쩍다는 것뿐.)",
  ui_story_5033_50330101_21_dialog_content = "으음?!",
  ui_story_5033_50330101_22_dialog_content = "(아주 약하긴 하지만 아직 숨을 쉬고 있어. 설마...)",
  ui_story_5033_50330101_23_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_5033_50330101_24_dialog_content = "죄송합니다, 섀도우마스터. 현장에는 피해자만 남아 있었습니다.\n목격자인 모자도 다른 사람은 못 봤다고 합니다.",
  ui_story_5033_50330101_25_dialog_content = "사망자는 누구지?",
  ui_story_5033_50330101_26_dialog_content = "경마로 큰돈을 번 외지인입니다.\n집 문 앞에 쓰러져 있던 것으로 보아, 외출을 하려던 모양입니다만...",
  ui_story_5033_50330101_27_dialog_content = "제가 일차적으로 검사해 본 결과, 이번 피해자는 아직 살릴 수 있을 것 같습니다.",
  ui_story_5033_50330101_28_dialog_content = "이 기회를 놓쳐선 안 됩니다.",
  ui_story_5033_50330101_29_dialog_content = "지금 바로 치료할 사람을 보내도록 하지. 넌 계속 조사를 진행하도록.",
  ui_story_5033_50330101_30_dialog_content = "이번엔 범인을 파악할 만한 단서가 있었나?",
  ui_story_5033_50330101_31_dialog_content = "피해자가 입은 상처는 몇 년 전 발생했던 <color=#FFB400>수녀 피살 사건</color>의 피해자와 같았습니다.",
  ui_story_5033_50330101_32_dialog_content = "지금까지의 조사에선 피해자들 사이의 중요한 공통점이 간과되었습니다.",
  ui_story_5033_50330101_33_dialog_content = "피해자들의 몸엔 세밀한 절상이 남아 있었고,\n모두 일상생활 중 알 수 없는 이유로 쓰러졌습니다.",
  ui_story_5033_50330101_34_dialog_content = "그 상처들은 육안으로는 거의 보이지 않을 정도로 작아서,\n언뜻 보면 치명적이지 않아 보입니다.",
  ui_story_5033_50330101_35_dialog_content = "그러나 방금 현장에서 상처를 조사해 본 결과,\n이는 칼로 인해 생긴 상처가 분명합니다.",
  ui_story_5033_50330101_36_dialog_content = "상처는 크지는 않지만 깊게 들어갔고, 모두 급소만 노렸습니다.\n범인은 분명 대단한 실력을 지닌 자입니다.",
  ui_story_5033_50330101_37_dialog_content = "와타리, 범인은 살아서 데려와 줬으면 좋겠군.\n이번 사건에 네가 개입하게 만든 건 바로 그 이유 때문이니까.",
  ui_story_5033_50330101_38_dialog_content = "넌 의사니까 적절하게 처리할 거라 믿는다.",
  ui_story_5033_50330101_39_dialog_content = "...조금만 더 시간을 주십시오.",
  ui_story_5033_50330101_40_dialog_content = "그럼 이제부터 어떻게 할 계획이지?",
  ui_story_5033_50330101_41_dialog_content = "기존 계획대로 감시를 진행할 생각입니다.",
  ui_story_5033_50330101_42_dialog_content = "서두르도록.",
  ui_story_5033_50330101_43_dialog_content = "예.",
  ui_story_5033_50330101_44_dialog_content = "<color=#e8d9bb>한 달 뒤, 움브라톤, 취소된 리빙페어 행사장</color>",
  ui_story_5033_50330101_45_dialog_content = "<size=45>호외요! 호외!</size>",
  ui_story_5033_50330101_46_dialog_content = "방금 나온 따끈따끈한 움브라톤 일보예요! 따끈따끈하고 향긋한 신문이랍니다!",
  ui_story_5033_50330101_47_dialog_content = "(신문을 그렇게 말하는 사람이 어디 있어?!)",
  ui_story_5033_50330101_48_dialog_content = "어라?",
  ui_story_5033_50330101_49_dialog_content = "PlayerName 너였구나! 너 혼자서 움브라톤에 다 오고 별일이네~",
  ui_story_5033_50330101_50_dialog_content = "(드, 들켰다!)",
  ui_story_5033_50330101_51_dialog_content = "신문 하나 살래? 진짜 큰 뉴스가 실려 있거든!",
  ui_story_5033_50330101_52_dialog_content = "「최근 움브라톤에 연일 <color=#FFB400>수수께끼의 연쇄 살인 사건</color>이 발생하고 있다.」",
  ui_story_5033_50330101_53_dialog_content = "「<color=#FFB400>회색 산업</color> 종사자 수 명이 자택에서 잔인하게 살해된 채 발견됐다.」",
  ui_story_5033_50330101_54_dialog_content = "「몸에는 <color=#FFB400>이상한 다툼의 흔적</color>만 남아 있었고, 범인의 행방은 아직도 묘연하다.」",
  ui_story_5033_50330101_55_dialog_content = "어때? 순식간에 흥미가 생겨서 하나 사고 싶어지지 않아?",
  ui_story_5033_50330101_56_dialog_content = "아, 안 살래! 오늘은 신문 사러 온 거 아니야.",
  ui_story_5033_50330101_57_dialog_content = "에이, PlayerName 네가 여기까지 왔는데 아무것도 안 살 리가 없잖아.",
  ui_story_5033_50330101_58_dialog_content = "그게 사실은...",
  ui_story_5033_50330101_59_dialog_content = "<color=#e8d9bb>며칠 전, 헤븐즈 가든</color>",
  ui_story_5033_50330101_60_dialog_content = "(휴~ 드디어 헤븐즈 가든도 좀 다듬어진 느낌이네.)",
  ui_story_5033_50330101_61_dialog_content = "(헤븐즈 가든에 이것저것 만든다고 꽤 바빴는데, 이젠 좀 쉬어도 될 것 같아...)",
  ui_story_5033_50330101_62_dialog_content = "하지만 이 정도 수준으론 아직 턱없이 부족한 것 같은데?",
  ui_story_5033_50330101_63_dialog_content = "어?! 바이스 네가 내 속마음을 어떻게 아는 건데...?",
  ui_story_5033_50330101_64_dialog_content = "포기하려는 표정 짓지 마, PlayerName.",
  ui_story_5033_50330101_65_dialog_content = "이제 기본적인 가구들은 다 있지만, 그래도 왠지 휑하고 단조로워 보이잖아.",
  ui_story_5033_50330101_66_dialog_content = "에잇!",
  ui_story_5033_50330101_67_dialog_content = "으앗! 이 종이 뭉텅이는 다 뭐야?",
  ui_story_5033_50330101_68_dialog_content = "지금까지 열렸던 움브라톤 리빙페어 전단지들을 모아 놓은 거야!",
  ui_story_5033_50330101_69_dialog_content = "여러 사람한테 부탁해서 간신히 다 모았어!",
  ui_story_5033_50330101_70_dialog_content = "그러니까... 넌 오래전부터 이런 계획을 세웠던 거야?!",
  ui_story_5033_50330101_71_dialog_content = "그런 사소한 건 신경 쓰지 마!",
  ui_story_5033_50330101_72_dialog_content = "아무튼 인테리어란 건 쉬운 일이 아니야. 게다가 여긴 네 집이잖아.",
  ui_story_5033_50330101_73_dialog_content = "한번 생각해 봐. 네가 밖을 여행하다가 드디어 집에 돌아와서 쉬게 됐다고 쳐.",
  ui_story_5033_50330101_74_dialog_content = "아, 소파에 푹 쓰러지고 싶을 것 같아.",
  ui_story_5033_50330101_75_dialog_content = "그럼 그 소파의 촉감은 어떨까? 부드러운 플란넬? 아니면 시원한 가죽?",
  ui_story_5033_50330101_76_dialog_content = "음, 소파라면 역시 가죽이지! 멋져 보이기도 하고.",
  ui_story_5033_50330101_77_dialog_content = "맞아! 그렇지? 가구는 행복감을 높여 줘. 그리고 그 사람의 취향을 보여 주기도 하구!",
  ui_story_5033_50330101_78_dialog_content = "그래서 집에 놓는 물건들은 다 진지하게 골라야 하는 거야!",
  ui_story_5033_50330101_79_dialog_content = "자, 잠깐만!",
  ui_story_5033_50330101_80_dialog_content = "설마 나보고 이 전단지들을 다 읽으라는 건 아니지?!",
  ui_story_5033_50330101_81_dialog_content = "어차피 요즘은 다른 할 일도 별로 없잖아.",
  ui_story_5033_50330101_82_dialog_content = "게다가 인테리어는 하나하나 다 자기가 직접 해야 하는 법이야.",
  ui_story_5033_50330101_83_dialog_content = "자, 이렇게 얘기만 하고 있을 시간 없어.",
  ui_story_5033_50330101_84_dialog_content = "얼른 만반의 준비를 해야 돼. 쇼핑은 또 하나의 전쟁이니까!",
  ui_story_5033_50330101_85_dialog_content = "재질, 색상, 스타일 같은 것도 꼼꼼히 살펴봐야 하는 거 잊지 마.",
  ui_story_5033_50330101_86_dialog_content = "전부 자세히 분석한 다음에 괜찮다고 판단될 때만 구매 목록에 넣는 거야!\n그럼 이제 곧 있을 리빙페어에 참전할 준비를 시작하자!",
  ui_story_5033_50330101_87_dialog_content = "아, 알겠습니다! 바이스 님!",
  ui_story_5033_50330101_88_dialog_content = "...그래서 꼬박 4일 동안 거의 쉬지도 못하고 전단지를 읽었다고.",
  ui_story_5033_50330101_89_dialog_content = "그, 그렇게 열심히?!",
  ui_story_5033_50330101_90_dialog_content = "응, 바이스가 가구를 고르면서 전의를 엄청 불태우더라고.\n눈빛이 얼마나 이글거리던지 전단지들이 다 타버리는 줄 알았어.",
  ui_story_5033_50330101_91_dialog_content = "원래 난 리빙페어에 와도 별생각 없이 바이스만 따라다니면 될 줄 알았거든.",
  ui_story_5033_50330101_92_dialog_content = "근데...",
  ui_story_5033_50330101_93_dialog_content = "<color=#e8d9bb>출발 전</color>",
  ui_story_5033_50330101_94_dialog_content = "PlayerName... 미, 미안해애애애애!",
  ui_story_5033_50330101_95_dialog_content = "히이로 님이 갑자기 파견 임무를 맡기셨어! 그래서...",
  ui_story_5033_50330101_96_dialog_content = "그래서 「구경해 보는 것도 나쁘진 않겠다」는 생각에 혼자\n아무 계획도 없이 무작정 여기 온 거야.",
  ui_story_5033_50330101_97_dialog_content = "그런 거라면 방문 타이밍이 영 안 좋았네, PlayerName.\n이번 시즌 리빙페어는 <color=#FFB400>잠정 취소</color>거든.",
  ui_story_5033_50330101_98_dialog_content = "뭐?!",
  ui_story_5033_50330101_99_dialog_content = "내가 아까 얘기했던 「연쇄 살인 사건」 때문에 그래.\n그 일 때문에 지금 움브라톤 분위기가 영 뒤숭숭하거든.",
  ui_story_5033_50330101_100_dialog_content = "그래서 오늘부턴 안전을 위해 리빙페어처럼 대규모 인파가 몰리는 행사는\n잠정 중단하기로 했대.",
  ui_story_5033_50330101_101_dialog_content = "그, 그게 진짜야?!",
  ui_story_5033_50330101_102_dialog_content = "오는 날이 장날이라더니...",
  ui_story_5033_50330101_103_dialog_content = "실망하지 마, PlayerName.\n움브라톤에선 다른 물건들도 많이 팔고 있잖아.",
  ui_story_5033_50330101_104_dialog_content = "대충 구경하면서 돌아다녀도 새로운 걸 발견하게 될 거야!",
  ui_story_5033_50330101_105_dialog_content = "그럼 나 먼저 가 볼게.",
  ui_story_5033_50330101_106_dialog_content = "응, 고마워, 웬디!",
  ui_story_5033_50330101_107_dialog_content = "그럼 어딜 구경하러 가야 좋을까...",
  ui_story_5033_50330101_108_dialog_content = "음... 엽서를 전문적으로 파는 노점에 가 볼까?",
  ui_story_5033_50330101_109_dialog_content = "이거 색이 진짜 예쁘네.",
  ui_story_5033_50330101_110_dialog_content = "엽서도 인테리어 소품이 될 수 있습니다.",
  ui_story_5033_50330101_111_dialog_content = "편하게 둘러보세요.\n엽서에 담긴 사진들은 모두 움브라톤 주변 도시들의 실제 풍경입니다.",
  ui_story_5033_50330101_112_dialog_content = "(엽서 한 장 정도 살 돈은 가지고 있으니까...)",
  ui_story_5033_50330101_113_dialog_content = "그럼 제가 들고 있는 이걸로 할게요.",
  ui_story_5033_50330101_114_dialog_content = "구매해 주셔서 감사합니다! 다음에 또 오세요!",
  ui_story_5033_50330101_115_dialog_content = "(엽서에 도시 이름이 나와 있네... <color=#FFB400>유포리아 타운</color>?)",
  ui_story_5033_50330101_116_dialog_content = "(뒷면에 작은 글씨로 뭔가 한 줄 적혀있어...\n「<color=#FFB400>낙원</color>에 오신 것을 환영합니다」...)",
  ui_story_5033_50330101_117_dialog_content = "(안 가 본 곳이잖아. 다음에 한 번 가 봐야지.)",
  ui_story_5033_50330101_118_dialog_content = "(역시 적절한 소비는 기분을 좋게 만들어 준다니까.)",
  ui_story_5033_50330101_119_dialog_content = "<color=#e8d9bb>투다탁──</color>",
  ui_story_5033_50330101_120_dialog_content = "<color=#e8d9bb>휘리릭──</color>",
  ui_story_5033_50330101_121_dialog_content = "내, 내 엽서!",
  ui_story_5033_50330101_122_dialog_content = "으, 정말... 대체 어디 떨어진 거야!",
  ui_story_5033_50330101_123_dialog_content = "너희 둘! 거기 서!",
  ui_story_5033_50330101_124_dialog_content = "허억, 헉...",
  ui_story_5033_50330101_125_dialog_content = "......",
  ui_story_5033_50330101_126_dialog_content = "(이상한 남자네. 요즘 움브라톤엔 저런 차림이 유행인가?)",
  ui_story_5033_50330101_127_dialog_content = "(잠깐, 계속 보니까 뭔가 낯이 익은데...)",
  ui_story_5033_50330101_128_dialog_content = "네가 왜 갑자기 우릴 막아선 건지는 모르겠지만...",
  ui_story_5033_50330101_129_dialog_content = "일단 고맙다, PlayerName.",
  ui_story_5033_50330101_130_dialog_content = "덕분에 용의자를 붙잡았으니까.",
  ui_story_5033_50330101_131_dialog_content = "이제 나머지는 내가 처리하면 돼.",
  ui_story_5033_50330101_132_dialog_content = "와타리 씨?! 왜 그런 옷을 입고 있었어?",
  ui_story_5033_50330101_133_dialog_content = "서, 선생님, 제발 그만 따라오세요! 저, 전 정말 그 사건하곤 관계가 없어요!",
  ui_story_5033_50330101_134_dialog_content = "사실대로 말하는 게 좋을 거다.",
  ui_story_5033_50330101_135_dialog_content = "말하지 않는다면 널 섀도우마스터께 데려갈 수밖에 없으니까.",
  ui_story_5033_50330101_136_dialog_content = "저, 전 아무것도 몰라요!",
  ui_story_5033_50330101_137_dialog_content = "그런가.",
  ui_story_5033_50330101_138_dialog_content = "<color=#e8d9bb>치잉──</color>",
  ui_story_5033_50330101_139_dialog_content = "이, 이러지 마세요! ...말할게요! 일단 그 칼부터 집어넣으세요!",
  ui_story_5033_50330101_140_dialog_content = "그러니까 전 그 운도 지지리 없는 사람들의 사업 파트너였을 뿐이라고요.\n근데 전 진짜 그 사람들 안 죽였어요!",
  ui_story_5033_50330101_141_dialog_content = "그 사람들은 다 떳떳하지 못한 일들로 돈을 벌었어요.\n그렇게 번 돈으로 움브라톤에서 지저분한 짓을 해서 돈을 굴리는 자들이었어요!",
  ui_story_5033_50330101_142_dialog_content = "영양가 없는 정보로군. 다른 건?",
  ui_story_5033_50330101_143_dialog_content = "그, 그리고...",
  ui_story_5033_50330101_144_dialog_content = "그 사람들이 죽기 전에 했던 행동들은 다 <color=#FFB400>유포리아 타운</color>과 관련돼 있었어요!",
  ui_story_5033_50330101_145_dialog_content = "거긴 「<color=#FFB400>사신</color>」이 출몰한다고 했습니다!",
  ui_story_5033_50330101_146_dialog_content = "「사신」?",
  ui_story_5033_50330101_147_dialog_content = "네... 만약 조금이라도 사신의 뜻을 거스르면...",
  ui_story_5033_50330101_148_dialog_content = "어느 곳이나 존재한다는 「사신」이 며칠 뒤에 그 사람의 목숨을 거둬간다고 합니다!",
  ui_story_5033_50330101_149_dialog_content = "「사신」은 알아서도 안 되고, 말해서도 안 되는 그런 존재입니다...\n그 사람들을 죽인 건 분명히 「사신」 짓입니다!",
  ui_story_5033_50330101_150_dialog_content = "음... 하지만 유포리아라면 이미...",
  ui_story_5033_50330101_151_dialog_content = "...방금 그 이야기들이 모두 사실이어야 할 거다.",
  ui_story_5033_50330101_152_dialog_content = "사실만 말씀드린 겁니다!",
  ui_story_5033_50330101_153_dialog_content = "......",
  ui_story_5033_50330101_154_option_content = "(강제 감응!)",
  ui_story_5033_50330101_155_dialog_content = "으음... 와타리 씨, 이 사람이 지금 거짓말을 하는 것 같진 않아.",
  ui_story_5033_50330101_156_dialog_content = "두려움과 긴장 빼곤 아무것도 안 느껴지거든.",
  ui_story_5033_50330101_157_dialog_content = "PlayerName, 덕분에 큰 도움이 됐어.",
  ui_story_5033_50330101_158_dialog_content = "...왜, 왜 그런 눈으로 쳐다보는 건데!",
  ui_story_5033_50330101_159_dialog_content = "부탁할 게 있다. 나와 함께 유포리아로 가 주지 않겠어?",
  ui_story_5033_50330101_160_dialog_content = "이렇게 갑자기?!",
  ui_story_5033_50330101_161_dialog_content = "난 섀도우마스터의 명령으로 움브라톤을 뒤흔들고 있는\n이번 연쇄 살인 사건을 조사하고 있다.",
  ui_story_5033_50330101_162_dialog_content = "나머지는 가면서 천천히 설명해 주지.",
  ui_story_5033_50330101_163_dialog_content = "네 그 거대한 녀석을 끌고 가면 너무 눈에 띌 수 있으니, 이번엔 비공정을 타고 가도록 하자고.",
  ui_story_5033_50330101_164_dialog_content = "내일 아침, 비공정 셔틀허브에서 기다리고 있겠다.",
  ui_story_5033_50330101_165_dialog_content = "음... 사실 나도 그 유포리아 타운에 가 보고 싶긴 했지만...",
  ui_story_5033_50330101_166_dialog_content = "좋아, 그럼 내일 보자고.",
  ui_story_5033_50330101_167_dialog_content = "잠깐만, 내 말 아직 안 끝났어!",
  ui_story_5033_50330101_168_dialog_content = "적어도 나한테 생각할 시간은 줘야 할 거 아냐...",
  ui_story_5033_50330201_1_dialog_content = "<color=#e8d9bb>비공정 셔틀허브</color>",
  ui_story_5033_50330201_2_dialog_content = "(결국 와타리 씨랑 한 약속대로 와 버렸어. 게다가 약속 시간보다 일찍 와 버렸잖아...)",
  ui_story_5033_50330201_3_dialog_content = "(평소엔 외출할 때 스카이워커호를 타고 갔으니까,\n비공정 허브엔 별로 와 본 적이 없던 것 같네.)",
  ui_story_5033_50330201_4_dialog_content = "(기념으로 헤븐즈 밸리에 엽서라도 한 장 보내고 싶은걸.\n어제 엽서를 안 잃어버렸으면 좋았을 텐데.)",
  ui_story_5033_50330201_5_dialog_content = "휴... 내 엽서...",
  ui_story_5033_50330201_6_dialog_content = "한숨 쉬는 걸 일부러 들은 건 아니에요.",
  ui_story_5033_50330201_7_dialog_content = "하지만 엽서 때문에 울적하신 거라면...",
  ui_story_5033_50330201_8_dialog_content = "제가 마침 한 장 가지고 있으니까, 이걸 드릴게요.",
  ui_story_5033_50330201_9_dialog_content = "와! 정말요? 제가 가지고 있던 거랑 똑같이 생겼어요!",
  ui_story_5033_50330201_10_dialog_content = "아, 아니지, 이러면 안 되지... 마음은 감사한데, 그냥 받을 순 없어요...",
  ui_story_5033_50330201_11_dialog_content = "이 엽서가 무척 마음에 드신 모양이네요.\n그럼 이걸 드리는 것도 일종의 선행이라 할 수 있겠죠.",
  ui_story_5033_50330201_12_dialog_content = "받으세요. 어차피 제겐 쓸모가 없거든요.",
  ui_story_5033_50330201_13_dialog_content = "쓸모가 없다니요...?",
  ui_story_5033_50330201_14_dialog_content = "네, 전 이제 곧 거기로 돌아갈 거라서요...",
  ui_story_5033_50330201_15_dialog_content = "유포리아에 가는 것도 14년 만이네요...",
  ui_story_5033_50330201_16_dialog_content = "미안해요, 제가 혼자서 말이 너무 많았죠.",
  ui_story_5033_50330201_17_dialog_content = "괜찮아요, 저도 누굴 기다리는 중이었거든요. 성함이 어떻게 되시죠?",
  ui_story_5033_50330201_18_dialog_content = "......",
  ui_story_5033_50330201_19_dialog_content = "전 애니라고 부르면 돼요.",
  ui_story_5033_50330201_20_dialog_content = "PlayerName입니다. 유포리아엔 처음 가 보는 여행객이에요.",
  ui_story_5033_50330201_21_dialog_content = "유포리아란 곳을 잘 아는 것 같은데, 혹시 뭐 좀 물어봐도 될까요?",
  ui_story_5033_50330201_22_dialog_content = "엽서를 보니까 유포리아가 「<color=#FFB400>낙원</color>」이라고 나와 있더라고요.",
  ui_story_5033_50330201_23_dialog_content = "맞아요. 외지인에겐 확실히 「낙원」이란 이름에 어울리는 곳이죠.",
  ui_story_5033_50330201_24_dialog_content = "다른 곳에선 느낄 수 없는 「즐거움」을 찾을 수 있거든요.",
  ui_story_5033_50330201_25_dialog_content = "게다가 사람들이 유포리아에 몰려드는 이유는 편안한 환경이나\n독특한 풍경 때문이 아니에요.",
  ui_story_5033_50330201_26_dialog_content = "사실은 그 독특한 건물들 아래 숨겨져 있는 <color=#FFB400>지하 산업</color>들 때문이랍니다.",
  ui_story_5033_50330201_27_dialog_content = "지하 산업이요?!",
  ui_story_5033_50330201_28_dialog_content = "근데 그런 건 움브라톤에도 있잖아요? 왜 굳이 유포리아까지 가는 거죠?",
  ui_story_5033_50330201_29_dialog_content = "처음엔 두 곳의 지하 산업 구조가 비슷했어요.\n하지만 유포리아는 개인이 관할하는 속령이거든요.",
  ui_story_5033_50330201_30_dialog_content = "사람들이 사리사욕과 욕망을 채우기 위해 규율이라는 선을 넘으리란 건\n불 보듯 뻔한 일이었죠.",
  ui_story_5033_50330201_31_dialog_content = "유포리아엔 대형 도박장, 민간 방위산업체... 상상할 수 있는 모든 게 다 있어요.",
  ui_story_5033_50330201_32_dialog_content = "얘길 들어보면 왠지 움브라톤보다도 더 「자유로운」 곳 같네요.",
  ui_story_5033_50330201_33_dialog_content = "설명해 줘서 고마워요. 벌써부터 기대되기 시작했어요.",
  ui_story_5033_50330201_34_dialog_content = "그래도 「낙원」을 기대하고 갔다간 현실에 실망하게 될 거예요.",
  ui_story_5033_50330201_35_dialog_content = "그게... 무슨 뜻이죠?",
  ui_story_5033_50330201_36_dialog_content = "제가 떠난 후로, 언제부터인진 모르겠지만 유포리아가 갑자기\n사람들 눈앞에서 「사라져」 버렸거든요.",
  ui_story_5033_50330201_37_dialog_content = "그때부터 사람들은 유포리아라는 이름을 입 밖으로 꺼내지도 않았어요.",
  ui_story_5033_50330201_38_dialog_content = "마치 유포리아라는 도시가「잊혀져」 버린 것처럼 말이에요.",
  ui_story_5033_50330201_39_dialog_content = "「잊혀진 도시」...라는 건가요?",
  ui_story_5033_50330201_40_dialog_content = "PlayerName!",
  ui_story_5033_50330201_41_dialog_content = "오래 기다리게 만들었네. 미안하게 됐어.",
  ui_story_5033_50330201_42_dialog_content = "괜찮아, 우리처럼 유포리아에 가는 수녀님이랑 이야길 나누고 있었거든.",
  ui_story_5033_50330201_43_dialog_content = "애니, 이쪽은 이번에 저랑 같이 가는 동료 와타리 씨라고 해요.",
  ui_story_5033_50330201_44_dialog_content = "비공정이 곧 출발할 겁니다. 당신도 같이 타죠.",
  ui_story_5033_50330201_45_dialog_content = "유포리아로 가는 비공정은 한동안 이것뿐이니, 놓쳤다간 곤란할 겁니다.",
  ui_story_5033_50330201_46_dialog_content = "아, 알겠어요...",
  ui_story_5033_50330201_47_dialog_content = "<color=#e8d9bb>비공정 내부</color>",
  ui_story_5033_50330201_48_dialog_content = "아무튼 난 한 달 전에 섀도우마스터께 정식으로 이번 조사 건을 인계받았다.",
  ui_story_5033_50330201_49_dialog_content = "최근 움브라톤에는 악성 범죄 사건이 여럿 발생했다.\n몇몇 불법 거래 현장이 발각됐고, 거래자들도 피해를 입었지.",
  ui_story_5033_50330201_50_dialog_content = "덕분에 움브라톤의 경제 흐름도 적잖이 영향을 받았다.",
  ui_story_5033_50330201_51_dialog_content = "이번 일은 여러 쪽으로 복잡하게 얽혀 있어 비밀리에 조사를 진행할 수밖에 없었지.",
  ui_story_5033_50330201_52_dialog_content = "마침 어제 그 남자의 진술도 있으니, 결국 유포리아엔 꼭 한 번 가 볼 필요가 있어.",
  ui_story_5033_50330201_53_dialog_content = "그랬구나. 모든 사건의 단서가 전부 유포리아를 가리키고 있었던 거네...",
  ui_story_5033_50330201_54_dialog_content = "아! 사건들의 시발점인 <color=#FFB400>수녀 피살 사건</color> 말인데,\n이 수녀님한테 도움을 받을 수 있지 않을까?",
  ui_story_5033_50330201_55_dialog_content = "......",
  ui_story_5033_50330201_56_dialog_content = "좋아요. 조사에 협력할게요.",
  ui_story_5033_50330201_57_dialog_content = "그렇게 긴장할 거 없습니다. 그냥 평범하게 질문 몇 가지만 할 테니까요.",
  ui_story_5033_50330201_58_dialog_content = "혹시 <color=#FFB400>마틸다</color>라는 수녀를 알고 있습니까?",
  ui_story_5033_50330201_59_dialog_content = "이름은 들어 봤어요.",
  ui_story_5033_50330201_60_dialog_content = "하지만 오래전에 유포리아에서 움브라톤으로 건너갔다는 것밖에 몰라요. 그럼 설마...",
  ui_story_5033_50330201_61_dialog_content = "맞아요. 이미 오래전에 움브라톤에서 변을 당했습니다.",
  ui_story_5033_50330201_62_dialog_content = "...아마 지금쯤 분명히 안식을 얻었겠지요.",
  ui_story_5033_50330201_63_dialog_content = "어쩌면 그게 우리 수녀들의 운명일지도 모르겠네요.",
  ui_story_5033_50330201_64_dialog_content = "유포리아를 떠났어도 결국엔 그런 결말을 맞게 되었으니 말이에요.",
  ui_story_5033_50330201_65_dialog_content = "하나만 묻죠. 혹시 마틸다 수녀가 그런 일을 당하게 될 거라 예상한 겁니까?",
  ui_story_5033_50330201_66_dialog_content = "유포리아엔 수녀가 의탁할 만한 곳이 사라진 지 오래예요.",
  ui_story_5033_50330201_67_dialog_content = "목숨을 구걸할 돈도 없이 혼자서 그곳의 거리를 돌아다닌다면...",
  ui_story_5033_50330201_68_dialog_content = "아마 자기가 어떻게 죽었는지도 모르게 순식간에 목숨을 잃을 거예요.",
  ui_story_5033_50330201_69_dialog_content = "인심 한 번 「대단한」 곳이네요...",
  ui_story_5033_50330201_70_dialog_content = "그런데도 당신은 우리처럼 유포리아로 향하는 비공정을 탔군요.",
  ui_story_5033_50330201_71_dialog_content = "전 한때 유포리아의 방식과 그곳의 모든 것에서 벗어나기 위해 그곳을 떠났어요.",
  ui_story_5033_50330201_72_dialog_content = "그러다 최근엔 그곳에 다시 돌아가야 할 이유가 생겼죠.",
  ui_story_5033_50330201_73_dialog_content = "...딱히 숨길 이유도 없으니 이야기할게요.\n이번에 유포리아로 돌아가는 이유는 <color=#FFB400>친구</color>를 만나기 위해서예요.",
  ui_story_5033_50330201_74_dialog_content = "그렇다면 계속 동행할 순 없을 것 같군요.",
  ui_story_5033_50330201_75_dialog_content = "음, 아래쪽 경치를 보니 거의 다 도착한 것 같네요.",
  ui_story_5033_50330201_76_dialog_content = "<color=#e8d9bb>유포리아 타운, 어느 거리</color>",
  ui_story_5033_50330201_77_dialog_content = "그럼 두 분, 여기서 이만 인사드리죠.",
  ui_story_5033_50330201_78_dialog_content = "부디 여러분의 조사가 순조롭길 바랄게요.",
  ui_story_5033_50330201_79_dialog_content = "네, 그럼 꼭 몸조심하세요.",
  ui_story_5033_50330201_80_dialog_content = "(빨리도 가잖아. 자기 안전은 전혀 걱정하지 않는 것 같은데...)",
  ui_story_5033_50330201_81_dialog_content = "<color=#e8d9bb>까악── 까악──</color>",
  ui_story_5033_50330201_82_dialog_content = "애니 말처럼 정말 황량한 곳이네.",
  ui_story_5033_50330201_83_dialog_content = "건물들은 다 무너질 것 같고, 여기저기 부서져 있어. 게다가 사람들도 안 보여...",
  ui_story_5033_50330201_84_dialog_content = "진짜로 「낙원」이 아니라 「잊혀진 도시」잖아.",
  ui_story_5033_50330201_85_dialog_content = "너도 이 도시가 그렇게 불린다는 걸 알고 있었군.",
  ui_story_5033_50330201_86_dialog_content = "그렇게 실망할 필요는 없다. 출발하기 전에 타키한테 쓸만한 정보를 알아 왔으니까.",
  ui_story_5033_50330201_87_dialog_content = "그럼 얼른 조사를 시작해 볼까...",
  ui_story_5033_50330201_88_dialog_content = "어라?",
  ui_story_5033_50330201_89_dialog_content = "뭐냐?!",
  ui_story_5033_50330201_90_dialog_content = "갑자기 이 주변에서 이상한 기운이 느껴져...",
  ui_story_5033_50330201_91_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5033_50330201_92_dialog_content = "<size=45>크오오!</size>",
  ui_story_5033_50330201_93_dialog_content = "자료의 내용대로야.\n이곳은 먹구름이 짙게 깔려 암귀들에겐 천연의 피난처 같은 곳이지...",
  ui_story_5033_50330201_94_dialog_content = "어떤 암귀든 싸우면 되는 거잖아!",
  ui_story_5033_50330201_95_dialog_content = "프로즌 메스!",
  ui_story_5033_50330202_1_dialog_content = "<size=45>프로즌 메스!</size>",
  ui_story_5033_50330202_2_dialog_content = "PlayerName, 어서 거기서 피해!",
  ui_story_5033_50330202_3_dialog_content = "<size=45>크오오──</size>",
  ui_story_5033_50330202_4_dialog_content = "(이런 광경은 지금까지 너무 많이 봐 왔어.)",
  ui_story_5033_50330202_5_dialog_content = "(내 머리 위에 암귀의 거대한 발톱이 날아드는 거.)",
  ui_story_5033_50330202_6_dialog_content = "(제때 피하지 못한다면 순식간에, 머리가 통째로 부서져 버릴 게 분명해.)",
  ui_story_5033_50330202_7_dialog_content = "꺼져! 다가오지 마!",
  ui_story_5033_50330202_8_dialog_content = "<color=#e8d9bb>스으윽!</color>",
  ui_story_5033_50330202_9_dialog_content = "......",
  ui_story_5033_50330202_10_dialog_content = "방금 그건... 도끼? 평범한 도끼로 암귀를 상대하는 거야?",
  ui_story_5033_50330202_11_dialog_content = "<color=#e8d9bb>퍼억!</color>",
  ui_story_5033_50330202_12_dialog_content = "<color=#e8d9bb>슈욱! 퍽!</color>",
  ui_story_5033_50330202_13_dialog_content = "마구잡이로 휘두르는 것 같지만, 급소를 노리고 있어.",
  ui_story_5033_50330202_14_dialog_content = "암귀와 어떻게 싸워야 하는지 확실히 알고 있잖아.",
  ui_story_5033_50330202_15_dialog_content = "PlayerName, 괜찮나? 다친 곳은 없어 보이는데.",
  ui_story_5033_50330202_16_dialog_content = "난 괜찮아. 그냥 식은땀만 좀 흘렸어.",
  ui_story_5033_50330202_17_dialog_content = "저 사람들은 유포리아에 사는 주민들일까?",
  ui_story_5033_50330202_18_dialog_content = "칼이 잘 들어갔군, 가슴팍 쪽의 모피는 통째로 잘라내야 된다.",
  ui_story_5033_50330202_19_dialog_content = "손톱은 뽑고, 뿔은 잘라 버려. 그리고 눈알은...",
  ui_story_5033_50330202_20_dialog_content = "윽!",
  ui_story_5033_50330202_21_dialog_content = "이 멍청한 자식이! 조심해야 될 거 아냐! 칼도 제대로 못 쓰는 거냐? 내놔!",
  ui_story_5033_50330202_22_dialog_content = "눈알은 별 필요가 없으니까 옆에 있는 저 쓸데없는 것들이랑 같이 태워 버려.",
  ui_story_5033_50330202_23_dialog_content = "저 사람들 지금 암귀를 해체하고 있는 거야? 가져가서 뭐 하려고 저러지?",
  ui_story_5033_50330202_24_dialog_content = "......",
  ui_story_5033_50330202_25_dialog_content = "갈 시간이다, PlayerName.",
  ui_story_5033_50330202_26_dialog_content = "지금? 그래도 우릴 구해줬는데, 고맙다고 인사라도 해야 하지 않을까?",
  ui_story_5033_50330202_27_dialog_content = "PlayerName, 잘 들어.",
  ui_story_5033_50330202_28_dialog_content = "저 녀석들이 지금 뭘 하고 있는지 똑똑히 봐라.",
  ui_story_5033_50330202_29_dialog_content = "녀석들은 널 구하려고 한 게 아니야. 너 따윈 안중에도 없었어.",
  ui_story_5033_50330202_30_dialog_content = "그리고 저 모피, 장기들은 하나에 200, 두 개에 300 나이티움이란 헐값에 팔린다.",
  ui_story_5033_50330202_31_dialog_content = "녀석들은 아마 오랫동안 여기서 암귀가 나타나길 기다리고 있었겠지.\n우린 녀석들에게 예상치 못한 손님일 뿐이야.",
  ui_story_5033_50330202_32_dialog_content = "「잊혀진 도시」 유포리아의 규칙은 바깥과는 달라.",
  ui_story_5033_50330202_33_dialog_content = "<size=33>적당히 하고 발을 빼지 않으면, 이 진흙탕에 발이 박혀 늪 바닥까지 가라앉고 말 거다.</size>",
  ui_story_5033_50330202_34_dialog_content = "알겠어, 그럼...",
  ui_story_5033_50330202_35_dialog_content = "어이, 잠깐 기다려, 「외지인」.",
  ui_story_5033_50330202_36_dialog_content = "오고 싶으면 오고, 가고 싶으면 가고. 정말 자유롭군.",
  ui_story_5033_50330202_37_dialog_content = "<size=45>누가 멋대로 가도 된다고 했냐!</size>",
  ui_story_5033_50330202_38_dialog_content = "<color=#e8d9bb>퍼억!</color>",
  ui_story_5033_50330202_39_dialog_content = "유포리아의 규칙을 모르진 않겠지?",
  ui_story_5033_50330202_40_dialog_content = "땅에 구멍이 났잖아...",
  ui_story_5033_50330202_41_dialog_content = "<size=33>어쩔 수 없나.</size>",
  ui_story_5033_50330202_42_dialog_content = "유포리아 사람들은 「손님을 좋아하는」 모양인지\n어딜 가나 「훌륭한 대접」을 해 준다니까.",
  ui_story_5033_50330202_43_dialog_content = "그럼 감사 선물을 잊지 말아야겠지.",
  ui_story_5033_50330202_44_dialog_content = "세어 봐라.",
  ui_story_5033_50330202_45_dialog_content = "거기, 이리 와 봐.",
  ui_story_5033_50330202_46_dialog_content = "네? 저요?",
  ui_story_5033_50330202_47_dialog_content = "넌 잔말 말고 <size=33>뒤로 가져가서 세기나 해.</size>",
  ui_story_5033_50330202_48_dialog_content = "너희들... 어디서 왔지? 대답해!",
  ui_story_5033_50330202_49_dialog_content = "우린...",
  ui_story_5033_50330202_50_dialog_content = "(와타리 씨, 지금 그 눈짓, 신호인가? 사실대로 말하면 안 된다는 거겠지...)",
  ui_story_5033_50330202_51_dialog_content = "(근데 이 도시는 움브라톤 관할 아닌가?\n움브라톤에서 파견 온 거라고 하면 저들을 진정시킬 수 있지 않을까?)",
  ui_story_5033_50330202_52_dialog_content = "우린 「헤븐즈 밸리 타운」에서 왔다.\n백야성 북쪽에 있는 세상과 동떨어진 작은 마을이지.",
  ui_story_5033_50330202_53_dialog_content = "어?",
  ui_story_5033_50330202_54_dialog_content = "헤븐즈 밸리 타운이라...",
  ui_story_5033_50330202_55_dialog_content = "헛소리, 어디서 장난질이냐?",
  ui_story_5033_50330202_56_dialog_content = "정말이다.",
  ui_story_5033_50330202_57_dialog_content = "(위험한 순간에도 눈 하나 깜짝 안 하고 거짓말을 하고 있잖아.)",
  ui_story_5033_50330202_58_dialog_content = "(설마 대놓고 유포리아 사람들이 무식하다고 창피 주려는 건 아니겠지...)",
  ui_story_5033_50330202_59_dialog_content = "대장, 진짜로 「헤븐즈 밸리」란 곳이 있는 모양인데요.",
  ui_story_5033_50330202_60_dialog_content = "그러냐. 그럼 다음 질문이다. 여긴 뭘 하러 온 거지? 목적이 뭐냐?",
  ui_story_5033_50330202_61_dialog_content = "사업을 하러 왔다. 낡고 쓸모없는 것들을 팔 생각이지.\n그래봤자 「쥐꼬리만큼」밖에 못 벌겠지만 말이야.",
  ui_story_5033_50330202_62_dialog_content = "사업을 하겠다면서 빈손으로 오는 경우도 있나?",
  ui_story_5033_50330202_63_dialog_content = "이번엔 일단 시장 조사부터 해 보러 나온 거다. 게다가 선물도 제대로 가져왔을 텐데.",
  ui_story_5033_50330202_64_dialog_content = "신분이라면, 이쪽은 내 운전사다.\n아침부터 밤까지 날 위해 운전을 하고 있지. 그리고 난...",
  ui_story_5033_50330202_65_dialog_content = "<size=45>다 셌어요!</size>",
  ui_story_5033_50330202_66_dialog_content = "총 1,235나이티움입니다! <size=33>대장, 아주 두둑한데요. 이 둘 다 부자인가 봐요.</size>",
  ui_story_5033_50330202_67_dialog_content = "나쁘지 않군.",
  ui_story_5033_50330202_68_dialog_content = "선물도 받았으면, 이렇게 무리 지어 「열렬히 환영」해 줄 필요는 없지 않나?",
  ui_story_5033_50330202_69_dialog_content = "이제부턴 번거롭게 만들고 싶지 않으니, 우리가 알아서 가겠다.",
  ui_story_5033_50330202_70_dialog_content = "너희가 돈을 준 건 맞아. 그런데 그게 영 부족하단 말이야.",
  ui_story_5033_50330202_71_dialog_content = "무슨 뜻이지?",
  ui_story_5033_50330202_72_dialog_content = "지나가고 싶다면, 돈을 더 내라.",
  ui_story_5033_50330202_73_dialog_content = "얼마를 원하나.",
  ui_story_5033_50330202_74_dialog_content = "2만.",
  ui_story_5033_50330202_75_dialog_content = "그거면 되겠나?",
  ui_story_5033_50330202_76_dialog_content = "될지 안 될지는 일단 받고 나서 생각해 보자고.",
  ui_story_5033_50330202_77_dialog_content = "와타리 씨! 저거 완전 빨대 꽂겠다는 거잖아!\n우리가 가진 돈을 다 털어 줘도, 절대 못 지나가게 할걸.",
  ui_story_5033_50330202_78_dialog_content = "걱정할 거 없어.",
  ui_story_5033_50330202_79_dialog_content = "2만 나이티움이라면 가지고 있다. 그 정도면 괜찮지.\n대신 너희가 와서 받아 가라.",
  ui_story_5033_50330202_80_dialog_content = "우린 둘이지만, 너흰 열 명도 넘는데 이런 걸로 무서워하진 않겠지?",
  ui_story_5033_50330202_81_dialog_content = "<color=#e8d9bb>우드득!</color>",
  ui_story_5033_50330202_82_dialog_content = "<size=45>으아아악!</size>",
  ui_story_5033_50330202_83_dialog_content = "대장!",
  ui_story_5033_50330202_84_dialog_content = "죽고 싶어서 환장을 했구나!",
  ui_story_5033_50330202_85_dialog_content = "(뭐야, 방금 분명히 팔이 부러졌었는데?)",
  ui_story_5033_50330202_86_dialog_content = "(팔에 뼈가 빈 것처럼 축 늘어진 상태로 허공에 매달려 있었다고.)",
  ui_story_5033_50330202_87_dialog_content = "(근데 금방 원래대로 회복됐잖아?)",
  ui_story_5033_50330202_88_dialog_content = "소리 지를 거 없어. 네 팔은 멀쩡하니까.",
  ui_story_5033_50330202_89_dialog_content = "잘 확인해 봐.",
  ui_story_5033_50330202_90_dialog_content = "분명히 부러졌었어! 그 통증은 진짜였다고! 크윽!",
  ui_story_5033_50330202_91_dialog_content = "이, 이 자식!",
  ui_story_5033_50330202_92_dialog_content = "돈 잘 챙겨라. 더도 덜도 말고 딱 2만 나이티움이다.\n아까 나보고 뭐 하는 사람이냐고 물었었지?",
  ui_story_5033_50330202_93_dialog_content = "난 의사다.",
  ui_story_5033_50330202_94_dialog_content = "네가 털끝 하나 다치지 않고 멀쩡하게 돌아가게 해줄 수도 있고,\n온몸의 뼈란 뼈는 모두 부러트려 줄 수도 있지.",
  ui_story_5033_50330202_95_dialog_content = "너뿐만이 아니라, 네 뒤에 있는 녀석들 전부 다.",
  ui_story_5033_50330202_96_dialog_content = "......",
  ui_story_5033_50330202_97_dialog_content = "그럼 이제 지나가도 되겠지?",
  ui_story_5033_50330202_98_dialog_content = "두, 두고 보자!",
  ui_story_5033_50330301_1_dialog_content = "(뭐, 길을 막던 녀석들도 이걸로 해결이네.)",
  ui_story_5033_50330301_2_dialog_content = "저기, 와타리 씨, 왜 저 녀석들이랑 그렇게 한참 어울려 준 거야?",
  ui_story_5033_50330301_3_dialog_content = "그냥 이스타반 씨가 보냈다고 하면 바로 지나갈 수 있었잖아.",
  ui_story_5033_50330301_4_dialog_content = "거친 녀석들처럼 보여도 그래봤자 그냥 불량배 무리였을 뿐인데.",
  ui_story_5033_50330301_5_dialog_content = "움브라톤의 섀도우마스터한테 맞설 생각은 절대 못 했을걸.",
  ui_story_5033_50330301_6_dialog_content = "그렇게 한다면 일은 확실히 편했겠지만, 그분께 불필요한 번거로움을 끼치게 될 거다.",
  ui_story_5033_50330301_7_dialog_content = "움브라톤은 큰 세력이지만, 섀도우마스터는 모든 일을 신중히 처리하신다.",
  ui_story_5033_50330301_8_dialog_content = "섣불리 그분의 이름을 꺼냈다간 오히려 그분께 「분쟁 조장」이라는\n죄를 덮어씌우게 될지도 모른다.",
  ui_story_5033_50330301_9_dialog_content = "아, 그래서 아까 나한테 조용히 있으라고 눈치 준 거야?",
  ui_story_5033_50330301_10_dialog_content = "그래. 하지만 섀도우마스터뿐만 아니라, 우리의 안전을 위해서도\n그러는 편이 나을 거라고 판단했다.",
  ui_story_5033_50330301_11_dialog_content = "...움브라톤이랑 유포리아랑 사이가 그렇게 안 좋아?",
  ui_story_5033_50330301_12_dialog_content = "많은 유포리아 주민들이 움브라톤에 뿌리 깊은 증오를 가지고 있다고 해도 과장이 아냐.",
  ui_story_5033_50330301_13_dialog_content = "서로 간의 상업적인 왕래도 몇 년 동안 거의 없다시피 한 상태지.",
  ui_story_5033_50330301_14_dialog_content = "<color=#FFB400>12년 전</color>, 어둠의 위기는 움브라톤과 주변의 모든 마을을 휩쓸었다.",
  ui_story_5033_50330301_15_dialog_content = "크고 작은 도시들이 완전히 붕괴돼 움브라톤의 질서도 재정립되기 시작했지.",
  ui_story_5033_50330301_16_dialog_content = "그땐 혼란스럽지 않은 곳이 없었지만,\n유포리아는 그중에서도 가장 큰 피해를 입은 도시 중 하나였다.",
  ui_story_5033_50330301_17_dialog_content = "움브라톤에서 패배한 암귀들은 방위 능력을 잃은 상태였던\n유포리아로 모조리 몰려가 버렸었지.",
  ui_story_5033_50330301_18_dialog_content = "그땐 섀도우마스터도 자신의 세력이 없었기에, 아무런 지원도 할 수 없었다.",
  ui_story_5033_50330301_19_dialog_content = "전쟁이 수습된 후, 「움브라톤이 어둠의 위기를 이용해 유포리아를 쓸어버렸다」는\n근거 없는 소문까지 퍼져나갔지.",
  ui_story_5033_50330301_20_dialog_content = "근데 아까 애니 씨가 유포리아는 개인이 관할하는 속령이라고 하지 않았어?",
  ui_story_5033_50330301_21_dialog_content = "유포리아의 소유주인 그 사람은 그냥 여길 포기해 버린 거야?",
  ui_story_5033_50330301_22_dialog_content = "과거엔 확실히 그랬다. 하지만 암귀들에게 침입을 당한 이후부터 여긴 주인 없는 땅이 됐지.",
  ui_story_5033_50330301_23_dialog_content = "그때 살아남은 주민들은 생존을 위해 서로 힘을 모아 <color=#FFB400>소형 상조회</color>를 여럿 세웠다.",
  ui_story_5033_50330301_24_dialog_content = "일부 기반 시설은 간단히 보수 공사를 거치니 계속 사용할 수 있었지.",
  ui_story_5033_50330301_25_dialog_content = "이 일대의 인구가 점차 늘어난 후에는 다른 몇몇 장소들도\n주민들의 생계를 위해 다시 사용되기 시작됐다.",
  ui_story_5033_50330301_26_dialog_content = "그러면서 상조회는 점차 <color=#FFB400>클랜</color>이라는 형태의 조직으로 변화하기 시작했지.",
  ui_story_5033_50330301_27_dialog_content = "유포리아가 변하게 된 이유를 들으니까 마음이 뭔가 복잡하네...",
  ui_story_5033_50330301_28_dialog_content = "눈앞에 있는 이 거리의 모습은 전쟁이 일어났던 그때부터 완전히 멈춰있는 상태잖아.",
  ui_story_5033_50330301_29_dialog_content = "지금은 텅 비어 보이겠지. 하지만 도시의 그림자 속엔 여전히 사람들이 많다.",
  ui_story_5033_50330301_30_dialog_content = "자, 그럼 이제 어서 움직이자. 되도록 주위 이목을 끌지 않게 행동하는 거다.",
  ui_story_5033_50330301_31_dialog_content = "출발하기 전, 타키가 내게 두 가지 선택지를 줬다.\n그리고 둘 중 어디에 가도 문제가 없도록 미리 연락을 취해 줬지.",
  ui_story_5033_50330301_32_dialog_content = "하나는 「유포리아 흥신소의 <color=#FFB400>구스타프</color>」.",
  ui_story_5033_50330301_33_dialog_content = "다른 하나는 「유랑 흥신소인 <color=#FFB400>네코야시키</color>」다.",
  ui_story_5033_50330301_34_dialog_content = "뭔가 「공기업」이랑 「사기업」 중에서 하나 골라야 하는 느낌이잖아.",
  ui_story_5033_50330301_35_dialog_content = "PlayerName, 네 생각은 어때?",
  ui_story_5033_50330301_36_option_content = "(「유포리아 흥신소의 구스타프」에게 의뢰한다)",
  ui_story_5033_50330301_37_dialog_content = "아무래도 타키 씨네처럼 정식으로 현지 사무실도 있는 흥신소에서\n얻는 소식이 더 믿을 만할 것 같아.",
  ui_story_5033_50330301_38_dialog_content = "게다가 정식 흥신소니까 더 많은 클랜들과 교류하고 있을 테니까\n별로 어렵지 않게 단서를 찾을 수도 있어.",
  ui_story_5033_50330301_39_dialog_content = "일리 있는 의견이야. 하지만...",
  ui_story_5033_50330301_40_dialog_content = "그런 흥신소에 방문하면 우리의 동향도 바로 노출되어 버리고 말 거다.",
  ui_story_5033_50330301_41_dialog_content = "그 흥신소와 교류가 있는 클랜이라면, 새로운 방문객의 출현에 촉각을 곤두세우겠지.",
  ui_story_5033_50330301_42_dialog_content = "그렇게 들으니까 확실히 좀 위험할 것 같네...",
  ui_story_5033_50330301_43_option_content = "(「유랑 흥신소의 네코야시키」에게 의뢰한다)",
  ui_story_5033_50330301_44_dialog_content = "왠지 비밀스러운 사람일 것 같아. 우리가 찾아가 봤자 아무도 신경 안 쓸 것 같고.",
  ui_story_5033_50330301_45_dialog_content = "게다가 명색이 방랑 정보원이니까, 다른 사람들은 모르는 독점 단서를 가지고 있을지도 몰라.",
  ui_story_5033_50330301_46_dialog_content = "맞는 말이야.",
  ui_story_5033_50330301_47_dialog_content = "정보를 별로 가지고 있을 것 같지 않은 정보원이 오히려 더 안전할 수 있어.",
  ui_story_5033_50330301_48_dialog_content = "그럼 지금 당장 네코야시키를 찾으러 가자고.",
  ui_story_5033_50330301_49_dialog_content = "그런데 진짜 믿을 만한 사람이야?",
  ui_story_5033_50330301_50_dialog_content = "흥신소를 찾을 땐 「믿을 수 있는지」를 따지는 게 아니라,\n「신뢰할 것인지」만을 따지는 거다.",
  ui_story_5033_50330301_51_dialog_content = "정보는 그쪽에서 제공하는 거지만, 그걸 믿을지 말지는 우리가 결정하는 거니까?",
  ui_story_5033_50330301_52_dialog_content = "똑똑하네.",
  ui_story_5033_50330301_53_dialog_content = "하지만 구스타프의 눈에 네코야시키는 격이 떨어지는 애송이 같은 존재다.",
  ui_story_5033_50330301_54_dialog_content = "게다가 만약 네코야시키에게 일을 맡기려면 조금 귀찮을 수도 있다.",
  ui_story_5033_50330301_55_dialog_content = "녀석은 행적이 불분명하다. 대신 가는 곳에 표식을 남겨 두곤 하지.\n보통은 금방 표식을 남긴 건물에만 모습을 드러내고 말이야...",
  ui_story_5033_50330301_56_dialog_content = "여기까지가 타키의 설명이었다. 그리고 그 표식이라는 건...",
  ui_story_5033_50330301_57_dialog_content = "혹시 <color=#FFB400>상처 모양 그라피티</color> 아니야?",
  ui_story_5033_50330301_58_dialog_content = "음? PlayerName, 네가 어떻게 그걸...",
  ui_story_5033_50330301_59_dialog_content = "고갤 드니까 바로 하나 보이길래.\n봐, 저 앞에 있는 식당 간판 쪽에 있잖아.",
  ui_story_5033_50330301_60_dialog_content = "마치 우릴 기다리고 있던 것처럼 말이야.",
  ui_story_5033_50330301_61_dialog_content = "역시 사소한 행동이라도 정보 판매상들의 눈을 피해 갈 순 없는 모양이군.",
  ui_story_5033_50330301_62_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5033_50330301_63_dialog_content = "계세요?",
  ui_story_5033_50330301_64_dialog_content = "이상해. 너무 조용해. 혹시 버려진 식당인가?",
  ui_story_5033_50330301_65_dialog_content = "...이런!",
  ui_story_5033_50330301_66_dialog_content = "와타리 씨! 엎드려!",
  ui_story_5033_50330301_67_dialog_content = "<color=#e8d9bb>타앙!</color>",
  ui_story_5033_50330301_68_dialog_content = "반응 한번 빠르군.",
  ui_story_5033_50330301_69_dialog_content = "비켜! 이번엔 내 차례야!",
  ui_story_5033_50330301_70_dialog_content = "<color=#e8d9bb>타앙!</color>",
  ui_story_5033_50330301_71_dialog_content = "또 너희들이야?! 너흴 해칠 생각은 없었다니까!",
  ui_story_5033_50330301_72_dialog_content = "아깐 우리가 좀 당황해서 대처를 못 했을 뿐이다.",
  ui_story_5033_50330301_73_dialog_content = "우리 대장 팔을 꺾어 놨으면 대가를 치러야지!",
  ui_story_5033_50330301_74_dialog_content = "<size=33>설마 우리가 잘못 찾아온 건가?</size>",
  ui_story_5033_50330301_75_dialog_content = "<size=33>그럴 리 없다. 타키가 잘못된 정보를 줬을 리는 없으니까.</size>",
  ui_story_5033_50330301_76_dialog_content = "<size=33>아무래도 상황이 우리가 생각했던 것보다 복잡한 모양이군...</size>",
  ui_story_5033_50330301_77_dialog_content = "일단 여기서 떠나자. 안전이 제일 중요하다.",
  ui_story_5033_50330301_78_dialog_content = "음...?",
  ui_story_5033_50330301_79_dialog_content = "<color=#e8d9bb>치잉──</color>",
  ui_story_5033_50330301_80_dialog_content = "또 수작을 부리시겠다?",
  ui_story_5033_50330301_81_dialog_content = "크에엑...",
  ui_story_5033_50330301_82_dialog_content = "클랜 멤버들만으로도 성가신데 암귀까지 나타났군.",
  ui_story_5033_50330301_83_dialog_content = "일단 암귀부터 처리하고 나서 떠나자!",
  ui_story_5033_50330302_1_dialog_content = "크에엑...",
  ui_story_5033_50330302_2_dialog_content = "끝이 없군. PlayerName, 지금이다! 어서 가자!",
  ui_story_5033_50330302_3_dialog_content = "어, 어디로?!",
  ui_story_5033_50330302_4_dialog_content = "일단 여기서 빠져나간 다음에 다시 이야기하자고!",
  ui_story_5033_50330302_5_dialog_content = "대장! 녀석들이 도망칩니다!",
  ui_story_5033_50330302_6_dialog_content = "어서 쫓아!",
  ui_story_5033_50330302_7_dialog_content = "<color=#e8d9bb>유포리아 타운, 어느 골목</color>",
  ui_story_5033_50330302_8_dialog_content = "후우, 후우...",
  ui_story_5033_50330302_9_dialog_content = "(정신없이 달려왔더니 여기가 어딘지도 모르겠어...)",
  ui_story_5033_50330302_10_dialog_content = "크오오!",
  ui_story_5033_50330302_11_dialog_content = "(아직도 암귀가 쫓아오고 있잖아!)",
  ui_story_5033_50330302_12_dialog_content = "<color=#e8d9bb>휘익──</color>",
  ui_story_5033_50330302_13_dialog_content = "으아아아악...",
  ui_story_5033_50330302_14_dialog_content = "망할... 후퇴해!",
  ui_story_5033_50330302_15_dialog_content = "어? 이 암귀들... 설마 저 녀석들만 쫓고 있는 건가?",
  ui_story_5033_50330302_16_dialog_content = "<size=45><color=#e8d9bb>그어어... 크오오!</color></size>",
  ui_story_5033_50330302_17_dialog_content = "누구냐?!",
  ui_story_5033_50330302_18_dialog_content = "(이상한 울음소리를 내고 있어...)",
  ui_story_5033_50330302_19_dialog_content = "그어어...",
  ui_story_5033_50330302_20_dialog_content = "(암귀들이... 물러나잖아?)",
  ui_story_5033_50330302_21_dialog_content = "잠깐 자릴 비운 사이에 불량배 놈들이 거점에 발을 들였나.",
  ui_story_5033_50330302_22_dialog_content = "나한테 고마워 하라고.\n이번 구조를 두 사람한테 받은 첫 번째 의뢰로 칠 테니까.",
  ui_story_5033_50330302_23_dialog_content = "당신이 <color=#FFB400>네코야시키</color> 씨?",
  ui_story_5033_50330302_24_dialog_content = "타키만 아니었으면 당신들처럼 격식 따지는 사람들이랑은 일 안 했어.",
  ui_story_5033_50330302_25_dialog_content = "그냥 네코야시키라고 부르고 편하게 말해.",
  ui_story_5033_50330302_26_dialog_content = "아까 대체 뭐가 어떻게 된 거야? 방금 그 이상한 소린 또 뭐고?",
  ui_story_5033_50330302_27_dialog_content = "그냥 살아남기 위한 방법이야.\n무슨 뜻인지는 나도 모르지만, 잘만 내면 놈들이 알아서 꺼져 주더라고.",
  ui_story_5033_50330302_28_dialog_content = "난 무기는 잘 다루지 못해도, 암귀 소리 흉내는 좀 낼 줄 알거든.\n그걸로 위험할 때 목숨을 건지는 거야.",
  ui_story_5033_50330302_29_dialog_content = "필요에 따라서는 아까처럼 녀석들을 살짝 이용할 수도 있고 말이야.",
  ui_story_5033_50330302_30_dialog_content = "어때? 타키가 추천해 준 두 손님들, 이제 날 신뢰할 수 있겠어?",
  ui_story_5033_50330302_31_dialog_content = "대단해! 그런 방법들도 흥신소만의 독자 정보인 거지?",
  ui_story_5033_50330302_32_dialog_content = "그렇게 치켜세울 거 없어. 됐으니까 일단 당신들이 알고 있는 것부터 말해 봐.",
  ui_story_5033_50330302_33_dialog_content = "옆에 있는 이 친구는 PlayerName, 나는 와타리다.\n움브라톤을 대표해 한 연쇄 살인 사건을 조사하러 왔다.",
  ui_story_5033_50330302_34_dialog_content = "지금은 범인에 대한 정보가 매우 적다.\n그저 범인의 살해 수법에서 실마리를 찾을 수밖에 없지.",
  ui_story_5033_50330302_35_dialog_content = "좀 더 자세히 말해볼까?",
  ui_story_5033_50330302_36_dialog_content = "사망자들의 몸에는 기묘한 칼자국이 남아 있었다.",
  ui_story_5033_50330302_37_dialog_content = "상처 자체는 매우 작아서, 즉시 목숨을 잃진 않았을 거다.\n그래서 피해자들 모두 산송장 같은 상태로 어느 정도 버티다 사망했지.",
  ui_story_5033_50330302_38_dialog_content = "(이 사람들도 그 점은 파악했어. 역시 <color=#FFB400>그 여자</color> 예상대로잖아.)",
  ui_story_5033_50330302_39_dialog_content = "쳇... 까다로운 수법이네.",
  ui_story_5033_50330302_40_dialog_content = "그런 특징을 발견해서 여기까지 온 걸 보면 당신도 보통 사람은 아니고 말이야.",
  ui_story_5033_50330302_41_dialog_content = "그런 수법에 대한 옛날이야기는 유포리아에서 <color=#FFB400>그 여자</color>가 제일 잘 알고 있을 거야.",
  ui_story_5033_50330302_42_dialog_content = "?!",
  ui_story_5033_50330302_43_dialog_content = "자세히 설명해 줬으면 좋겠는데.",
  ui_story_5033_50330302_44_dialog_content = "「<color=#FFB400>레이븐즈 블러드</color>」와 만나게 해 줄게. 그 둘이 나보다 더 잘 알 테니까.",
  ui_story_5033_50330302_45_dialog_content = "<color=#e8d9bb>까악── 까악──</color>",
  ui_story_5033_50330302_46_dialog_content = "까마귀들이 먼저 왔잖아.",
  ui_story_5033_50330302_47_dialog_content = "아무래도 저쪽도 움브라톤에서 온 손님을 만나고 싶어 하는 모양이야.",
  ui_story_5033_50330302_48_dialog_content = "<color=#e8d9bb>얼마 전, 또 다른 골목</color>",
  ui_story_5033_50330302_49_dialog_content = "(망할, 막다른 길이잖아!)",
  ui_story_5033_50330302_50_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5033_50330302_51_dialog_content = "(폴룩스랑 카스타도 따라붙은 건가?!)",
  ui_story_5033_50330302_52_dialog_content = "(여기서 죽긴 싫어!)",
  ui_story_5033_50330302_53_dialog_content = "자꾸 그렇게 성가신 일을 벌이니까, 문제가 알아서 널 찾아가는 거야.",
  ui_story_5033_50330302_54_dialog_content = "나, 난 그냥 그 외지인 둘한테 돈이나 좀 달라고 했을 뿐이야...\n그거 말곤 아무 짓도 안 했어!",
  ui_story_5033_50330302_55_dialog_content = "게다가 그 외지인들이 너희 「레이븐즈 블러드」랑 무슨 상관인데?",
  ui_story_5033_50330302_56_dialog_content = "요즘 돈 좀 만질 수 있게 됐다고 위로 치고 올라가려는 모양인데,\n꿈 깨는 게 좋을 거다!",
  ui_story_5033_50330302_57_dialog_content = "유포리아는 너희처럼 미친 녀석들한텐 절대로 무릎 꿇지 않으니까!",
  ui_story_5033_50330302_58_dialog_content = "그렇게 생각하고 있었구나?",
  ui_story_5033_50330302_59_dialog_content = "가, 가까이 오지 마! 나도 칼이 있다고!",
  ui_story_5033_50330302_60_dialog_content = "오지 말라고 했잖아!",
  ui_story_5033_50330302_61_dialog_content = "으악, 내 칼! 뭐, 뭘 하려는 거야?!",
  ui_story_5033_50330302_62_dialog_content = "몸을 지키는 데 단도는 별로야. 단도가 너희들보다 훨씬 더 위험하거든.",
  ui_story_5033_50330302_63_dialog_content = "그러니까 다음엔 꼭 너한테 더 잘 맞는 무기를 골라.",
  ui_story_5033_50330302_64_dialog_content = "대, 대체 무슨 소리야?",
  ui_story_5033_50330302_65_dialog_content = "내가 방금 그렇게나 많은 암귀들한테서 널 구해 줬잖아. 아직도 상황 파악이 안 돼?",
  ui_story_5033_50330302_66_dialog_content = "이래도... 못 알아듣겠어?",
  ui_story_5033_50330302_67_dialog_content = "은혜를 모르는 인간은 이 유포리아에서 살아남을 수 없어.",
  ui_story_5033_50330302_68_dialog_content = "으악! 칼 좀 치워! 말할게! 다 말해 준다고!",
  ui_story_5033_50330302_69_dialog_content = "흥, 칼날인지 칼등인지 구분도 못 하고 속기는.",
  ui_story_5033_50330302_70_dialog_content = "네 고용주란 사람도 제대로 된 인간은 아니구나.\n차라리 내가 무료로 칼 쓰는 법을 가르쳐 줄게.",
  ui_story_5033_50330302_71_dialog_content = "시범으로 네 목을 벨지 다른 걸 벨지는 앞으로 네가 어떻게 하느냐에 달렸어.",
  ui_story_5033_50330302_72_dialog_content = "말하면 될 거 아냐!",
  ui_story_5033_50330302_73_dialog_content = "나 말고도 많은 여기 토박이들이 모여서 이 도시 곳곳에 매복 중이야.",
  ui_story_5033_50330302_74_dialog_content = "매복?",
  ui_story_5033_50330302_75_dialog_content = "그래, 윗선에선 아직 때가 안 됐다고 하더군.",
  ui_story_5033_50330302_76_dialog_content = "일단 어떻게든 클랜에 섞여 들어가야 하니까,\n클랜에서 벌이는 술판, 도박판에 최대한 많이 참여하라고 했어.",
  ui_story_5033_50330302_77_dialog_content = "그게 다야?",
  ui_story_5033_50330302_78_dialog_content = "그자들이 너한테 뭘 시킬지는 정말로 단 한 번도 궁금했던 적 없어?",
  ui_story_5033_50330302_79_dialog_content = "카, 칼 좀 치우라고...",
  ui_story_5033_50330302_80_dialog_content = "좋아, 사실 이틀 전에 우리 클랜에서 이런 얘길 하나 들었어.",
  ui_story_5033_50330302_81_dialog_content = "우릴 고용한 보스가 이 도시에 어떤 <color=#FFB400>소문</color>을 퍼트리고 싶어 한다더라고.",
  ui_story_5033_50330302_82_dialog_content = "내, 내가 아는 건 진짜 이게 다야! 그게 무슨 소문인진 나도 아직 몰라!",
  ui_story_5033_50330302_83_dialog_content = "그래, 알겠어.",
  ui_story_5033_50330302_84_dialog_content = "아, 안 풀어 줄 거야? 알고 있는 건 다 말해 줬잖아!",
  ui_story_5033_50330302_85_dialog_content = "그럼 내가 유포리아의 생존 법칙을 무료로 하나 더 알려 줄게.",
  ui_story_5033_50330302_86_dialog_content = "이곳에선 그 누구도 믿지 말 것.",
  ui_story_5033_50330302_87_dialog_content = "으윽!",
  ui_story_5033_50330302_88_dialog_content = "매번 그렇게 기절시킨 다음에 쓰레기통에 처박아 놓기만 하고.",
  ui_story_5033_50330302_89_dialog_content = "사람들이 두려워하는 「폴룩스」가 사실은 이렇게 자비롭다는 걸 외지인들이 알기라도 해 봐.",
  ui_story_5033_50330302_90_dialog_content = "그 이름에 달린 전설을 믿겠어?",
  ui_story_5033_50330302_91_dialog_content = "그러네, 그래도 유포리아에선 아무도 믿지 않는 게 좋아. 특히 난 더더욱.",
  ui_story_5033_50330302_92_dialog_content = "<color=#e8d9bb>까악── 까악──</color>",
  ui_story_5033_50330302_93_dialog_content = "아, 네코야시키 쪽에서 벌써 움직이기 시작했어.",
  ui_story_5033_50330302_94_dialog_content = "역시 내 예상대로 네코야시키를 만나러 간 모양이네.",
  ui_story_5033_50330302_95_dialog_content = "그래도 따라붙는 속도는 오히려 내 예상보다 빨라.",
  ui_story_5033_50330302_96_dialog_content = "전에 얘기했던 것처럼 <color=#FFB400>늘 만나던 곳</color>으로 돌아가서,\n네코야시키가 움브라톤의 두 손님을 데려오길 기다리자.",
  ui_story_5033_50330302_97_dialog_content = "너답지 않아, 폴룩스.\n왜 우리 쪽에서 먼저 그 둘을 맞이하러 가야 하는데?",
  ui_story_5033_50330302_98_dialog_content = "어느 정도는 내 개인 욕심이야. 그 둘은 섀도우마스터가 보낸 사람들이거든.",
  ui_story_5033_50330302_99_dialog_content = "<color=#FFB400>아이들</color> 때문이야?",
  ui_story_5033_50330302_100_dialog_content = "응. 그리고 당연하겠지만 유포리아를 위해서이기도 해.",
  ui_story_5033_50330302_101_dialog_content = "난 도시를 말끔하게 씻어 줄 소나기를 기다리고 있거든.",
  ui_story_5033_50330302_102_dialog_content = "카스타.",
  ui_story_5033_50330302_103_dialog_content = "응?",
  ui_story_5033_50330302_104_dialog_content = "유포리아의 하늘은 대체 언제부터 이렇게 탁한 잿빛이었을까?",
  ui_story_5033_50330302_105_dialog_content = "그러게...",
  ui_story_5033_50330302_106_dialog_content = "언제부터 이랬던 걸까.",
  ui_story_5033_50330401_1_dialog_content = "네가 방금 말한 「레이븐즈 블러드」는 이 유포리아에 존재하는 여러 클랜 중 하난가?",
  ui_story_5033_50330401_2_dialog_content = "그래. 사실 너희가 나한테 도움을 청한 건 탁월한 선택이었어.",
  ui_story_5033_50330401_3_dialog_content = "다른 사람을 찾아갔더라면 빙빙 돌고 한참을 돌아야\n「레이븐즈 블러드」가 있는 곳을 찾을 수 있었을 테니까.",
  ui_story_5033_50330401_4_dialog_content = "이 클랜의 구성원은 <color=#FFB400>폴룩스</color>와 <color=#FFB400>카스타</color> 두 사람이야.\n인원수는 적어도 기세는 여느 대형 클랜 못지않아.",
  ui_story_5033_50330401_5_dialog_content = "폴룩스는 클랜들 사이의 알력 다툼에는 관심이 없어.\n그래서 그 둘의 행방을 금방 찾아낼 수 있는 사람은 많지 않아.",
  ui_story_5033_50330401_6_dialog_content = "폴룩스라는 사람이 아까 얘기했던... 「그 여자」야?",
  ui_story_5033_50330401_7_dialog_content = "맞아.",
  ui_story_5033_50330401_8_dialog_content = "폴룩스는 나보다 먼저 너희가 유포리아에 왔다는 소식을 알았어.\n그리곤 너희가 날 선택하길 기다렸지.",
  ui_story_5033_50330401_9_dialog_content = "역시 넓고 멀리 볼 수 있어야 이 도시에서 살아남을 수 있다는 건가.",
  ui_story_5033_50330401_10_dialog_content = "하하, 그렇고말고. 게다가 너흰 꽤 유명한 손님들이거든.",
  ui_story_5033_50330401_11_dialog_content = "그리고 「너흴 데리고 늘 만나던 곳으로 와 달라」는 것도 폴룩스가 나한테 요청한 거야.",
  ui_story_5033_50330401_12_dialog_content = "...그 사람이 이번 조사에 잘 협력해 줬으면 좋겠군.",
  ui_story_5033_50330401_13_dialog_content = "당신들, 설마 폴룩스 쪽도 의심하고 있는 건가?",
  ui_story_5033_50330401_14_dialog_content = "긴장할 거 없어. 멋대로 사람을 데려가진 않을 테니까.",
  ui_story_5033_50330401_15_dialog_content = "용의자를 확정했다 하더라도, 더 확실한 증거가 발견되기 전까진 기다릴 생각이다.",
  ui_story_5033_50330401_16_dialog_content = "하하하하, 뭘 기다릴 건데? 다음번 피해자가 칼 맞을 때까지?",
  ui_story_5033_50330401_17_dialog_content = "무고한 피해자가 계속 늘어나길 바란 적은 한 번도 없었다.",
  ui_story_5033_50330401_18_dialog_content = "네코야시키 씨, 이번 사건은 가볍게 대해도 될 일이 아니야.\n올바른 태도로 이번 사건을 대해 줬으면 좋겠는데.",
  ui_story_5033_50330401_19_dialog_content = "에이, 긴장 풀라고! 릴렉스! 난 그냥 너희 의심이 어이가 없어서 그런 거니까.",
  ui_story_5033_50330401_20_dialog_content = "뭐, 폴룩스의 친구인 내가 이런 말을 해 봤자 별로 설득력은 없겠네, 안 그래?",
  ui_story_5033_50330401_21_dialog_content = "아무튼 너희 둘을 우리가 늘 만나던 곳으로 데려다주면 되겠네.",
  ui_story_5033_50330401_22_dialog_content = "만나고 나면 너희들이 알아서 판단할 테니까.",
  ui_story_5033_50330401_23_dialog_content = "(엄청 자신만만하잖아...)",
  ui_story_5033_50330401_24_dialog_content = "그래서 한참 얘기한 것 같은데, 그 「늘 만나던 곳」은 대체 어디 있는 거야?",
  ui_story_5033_50330401_25_dialog_content = "아, 마침 거의 다 왔어.",
  ui_story_5033_50330401_26_dialog_content = "우리가 가려는 곳은 <color=#FFB400>옛 교회</color>야. 폐허가 되기 전엔 꽤 예쁜 곳이었지.",
  ui_story_5033_50330401_27_dialog_content = "(교회?)",
  ui_story_5033_50330401_28_dialog_content = "유포리아엔 수녀가 의탁할 만한 곳이 사라진 지 오래예요.",
  ui_story_5033_50330401_29_dialog_content = "(수녀들은 다 사라졌다고 들었는데, 교회는 아직 남아 있었네...)",
  ui_story_5033_50330401_30_dialog_content = "<color=#e8d9bb>유포리아 타운, 옛 교회</color>",
  ui_story_5033_50330401_31_dialog_content = "역시 여기도 다른 곳들처럼 황폐하구나.",
  ui_story_5033_50330401_32_dialog_content = "다른 곳들처럼 비바람 정도나 피할 수 있는 곳이긴 해.",
  ui_story_5033_50330401_33_dialog_content = "유포리아엔 구세주란 게 있었던 적이 없으니까, 빛의 신을 믿는 신앙도 없어진 지 오래거든.",
  ui_story_5033_50330401_34_dialog_content = "최근 몇 년 동안 이 도시의 수녀들은 죄다 처리당해 버렸어.\n그래서 이 교회도 굳이 따지면 진짜 교회는 아냐.",
  ui_story_5033_50330401_35_dialog_content = "수녀들이 처리당했다? 누가 그런 짓을 했다는 거지?",
  ui_story_5033_50330401_36_dialog_content = "그걸 알고 있었으면, 나도 지금까지 살아있진 못했을걸.",
  ui_story_5033_50330401_37_dialog_content = "아마 그 수녀들은 그렇게 될 운명이 아니었을까? 죽음은 항상 불시에 찾아오곤 하잖아.",
  ui_story_5033_50330401_38_dialog_content = "어느 곳이나 존재한다는 「사신」이 며칠 뒤에 그 사람의 목숨을 거둬간다고 합니다!",
  ui_story_5033_50330401_39_dialog_content = "「사신」은 알아서도 안 되고, 말해서도 안 되는 그런 존재입니다...\n그 사람들을 죽인 건 분명히 「사신」 짓입니다!",
  ui_story_5033_50330401_40_dialog_content = "(어째 그 사람이 했던 설명이랑 비슷한 것 같은데...)",
  ui_story_5033_50330401_41_dialog_content = "(연쇄 살인 사건, 참혹하게 살해당한 수녀들... 이 모든 게 다 그 「사신」이 벌인 짓인가?)",
  ui_story_5033_50330401_42_dialog_content = "그러고 보니 유포리아에 오는 길에 한 수녀를 만났어.",
  ui_story_5033_50330401_43_dialog_content = "도착하고 나선 헤어져서 각자 따로 행동했는데, 무사할지 모르겠네.",
  ui_story_5033_50330401_44_dialog_content = "음? 뭐라고? 그게 진짜야?!",
  ui_story_5033_50330401_45_dialog_content = "응, 움브라톤에서 올 때 우리랑 같이 왔거든. 옷차림이 딱 수녀였어.",
  ui_story_5033_50330401_46_dialog_content = "(움브라톤에서 온 수녀라...)",
  ui_story_5033_50330401_47_dialog_content = "이따 「레이븐즈 블러드」를 만나면 그 사실을 알려줘. 아주 기뻐할 테니까.",
  ui_story_5033_50330401_48_dialog_content = "<color=#e8d9bb>같은 시간, 어느 골목</color>",
  ui_story_5033_50330401_49_dialog_content = "......?",
  ui_story_5033_50330401_50_dialog_content = "폴룩스, 왜 그래?",
  ui_story_5033_50330401_51_dialog_content = "...설마 아까 그 녀석들, 아직도 이 근처에 있어?",
  ui_story_5033_50330401_52_dialog_content = "아니, 녀석들이 아니야.",
  ui_story_5033_50330401_53_dialog_content = "그렇지만 녀석들이 아니란 것밖에 모르겠어.\n기척이 나타났다 사라졌다 하는데, 녀석들은 그런 실력이 없어.",
  ui_story_5033_50330401_54_dialog_content = "이 유포리아 어디에도 그럴 실력 있는 녀석은 없을걸.",
  ui_story_5033_50330401_55_dialog_content = "신경 쓰지 마. 고양이 같은 거일지도 모르잖아.",
  ui_story_5033_50330401_56_dialog_content = "자, 아이들이 기다릴 테니까 빨리 가자. 네코야시키 쪽도 거의 다 도착했을 거야.",
  ui_story_5033_50330401_57_dialog_content = "...먼저 가 있어. 난 아까 그 상점가로 돌아가 봐야 할 것 같아.",
  ui_story_5033_50330401_58_dialog_content = "그 불량배 녀석들 때문에 굳이 돌아가 볼 필요는 없지 않아?",
  ui_story_5033_50330401_59_dialog_content = "그 녀석들 따위가 뭐라고 이러겠어.",
  ui_story_5033_50330401_60_dialog_content = "그냥 아이들한테 깜짝 선물을 좀 준비해 주고 싶어서 그래.",
  ui_story_5033_50330401_61_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5033_50330401_62_dialog_content = "......",
  ui_story_5033_50330401_63_dialog_content = "(방금... 들킨 건가?)",
  ui_story_5033_50330401_64_dialog_content = "<color=#e8d9bb>야옹──</color>",
  ui_story_5033_50330401_65_dialog_content = "야옹!",
  ui_story_5033_50330401_66_dialog_content = "폴룩스를 죽여라.",
  ui_story_5033_50330401_67_dialog_content = "......",
  ui_story_5033_50330401_68_dialog_content = "(...재촉이 심하네.)",
  ui_story_5033_50330401_69_dialog_content = "<color=#e8d9bb>스으윽──</color>",
  ui_story_5033_50330401_70_dialog_content = "으음?",
  ui_story_5033_50330401_71_dialog_content = "<size=45>크오오!</size>",
  ui_story_5033_50330401_72_dialog_content = "(꼭 이럴 때 나타난다니까.)",
  ui_story_5033_50330401_73_dialog_content = "(이 쓰레기 편지랑 같이 처리해 버려야겠네.)",
  ui_story_5033_50330502_1_dialog_content = "<color=#e8d9bb>움브라톤, 이스타반 클랜</color>",
  ui_story_5033_50330502_2_dialog_content = "<color=#e8d9bb>우르릉!</color>",
  ui_story_5033_50330502_3_dialog_content = "금방이라도 쏟아지겠군.",
  ui_story_5033_50330502_4_dialog_content = "먹구름에 뒤덮이면 그림자들이 나타나 빠르게 움브라톤의 곳곳으로 뻗어나간다.",
  ui_story_5033_50330502_5_dialog_content = "유포리아도 늦든 빠르든 영향을 받을 테지.",
  ui_story_5033_50330502_6_dialog_content = "와타리가 잘 조사하고 있을지 걱정되십니까?",
  ui_story_5033_50330502_7_dialog_content = "아니.",
  ui_story_5033_50330502_8_dialog_content = "그저 새로운 날씨가 기대될 뿐이다.",
  ui_story_5033_50330502_9_dialog_content = "며칠 전, 와타리가 조사 중인 사건에 관해 어떤 생각이 들었습니다.",
  ui_story_5033_50330502_10_dialog_content = "하지만 확실한 증거가 없어서 아직까진 제 개인적인 추측에 불과합니다.",
  ui_story_5033_50330502_11_dialog_content = "괜찮다. 어디 들어볼까.",
  ui_story_5033_50330502_12_dialog_content = "저도 옛날 기사들을 들여다보고 나서야 발견한 사실입니다만.",
  ui_story_5033_50330502_13_dialog_content = "14년 전, 움브라톤에 큰 충격을 준 사건이 유포리아에서 발생했습니다.",
  ui_story_5033_50330502_14_dialog_content = "당시 사람들에겐 유포리아보다 「낙원」이라는 이름이 더 널리 알려져 있었죠.",
  ui_story_5033_50330502_15_dialog_content = "아마 그 사건에 대해선 이스타반 님께서 저보다 더 잘 알고 계실 겁니다.",
  ui_story_5033_50330502_16_dialog_content = "...「<color=#FFB400>쌍둥이별 사건</color>」인가, 기억이 어렴풋이 나는군.",
  ui_story_5033_50330502_17_dialog_content = "네. 당시 유포리아에선 지하 격투장이 성행했었죠.\n많은 사람들이 그걸로 순식간에 엄청난 돈을 벌었습니다.",
  ui_story_5033_50330502_18_dialog_content = "심지어는 유포리아 용병단의 단장까지 의뢰 대신 지하 격투로\n돈을 버는 지경이었으니 말입니다.",
  ui_story_5033_50330502_19_dialog_content = "이상할 것도 없지. 당연한 이치 아닌가.\n어차피 들어오는 의뢰들도 전부 지하 격투장 선수를 해 달라는 것들이었을 테니까.",
  ui_story_5033_50330502_20_dialog_content = "참 얄궂은 일이죠.",
  ui_story_5033_50330502_21_dialog_content = "아무튼 당시의 단장은 실권자인 보스의 뜻에 따라 엔터테인먼트적인\n측면이 강한 「스타 선수」를 육성했습니다.",
  ui_story_5033_50330502_22_dialog_content = "그 스타 선수는 어린 두 소녀였고, 각각 단장에게 전혀 다른 교육을 받았습니다...",
  ui_story_5033_50330502_23_dialog_content = "한 명에겐 용병단만의 전투 기술을 철저히 익힐 수 있도록,\n용병단의 내부 훈련만 받게 했습니다.",
  ui_story_5033_50330502_24_dialog_content = "다른 한 명은 뛰어난 대처 능력을 지니도록, 어려서부터 다른 용병들처럼\n여러 실전에 투입됐습니다.",
  ui_story_5033_50330502_25_dialog_content = "유포리아에서 용병단의 「쌍둥이별」이라 불렸던 두 사람...",
  ui_story_5033_50330502_26_dialog_content = "그 둘이 맡게 된 첫 번째 정식 임무는...",
  ui_story_5033_50330502_27_dialog_content = "격투장에서 서로를 상대로 <color=#FFB400>목숨을 건 대결</color>을 펼치는 것이었습니다.",
  ui_story_5033_50330502_28_dialog_content = "서로와 싸우게 된 자매의 눈물겨운 드라마는커녕,\n자매 중 하나가 곧바로 다른 하나의 숨통을 끊어 놓았겠군. 아닌가?",
  ui_story_5033_50330502_29_dialog_content = "맞습니다.",
  ui_story_5033_50330502_30_dialog_content = "어떻게 싸웠는지는 기록이 남아있지 않습니다만,\n가십거리가 잔뜩 실리는 타블로이드지의 기사에 따르면...",
  ui_story_5033_50330502_31_dialog_content = "살아남은 아이도 중상을 입었다고 합니다.\n온몸이 자잘한 상처들로 가득해서 거의 죽을 뻔했다더군요.",
  ui_story_5033_50330502_32_dialog_content = "그 후론 사라져서 다시는 모습을 보이지 않았다고 합니다.",
  ui_story_5033_50330502_33_dialog_content = "그러나 그리고 몇 년 후, 움브라톤에 대혼란이 발생한 뒤로,\n점차 아무도 그 아이의 행방에 대해 궁금해하지 않게 되었습니다.",
  ui_story_5033_50330502_34_dialog_content = "그때 자매간의 대결에서 목숨을 잃었다던 그 소녀가,\n사실은 아직 <color=#FFB400>살아있다</color>고 의심하는 건가?",
  ui_story_5033_50330502_35_dialog_content = "그렇습니다.",
  ui_story_5033_50330502_36_dialog_content = "그러나 그건 짐작에 불과하지. 난 그 소녀의 생존을 의심하는 게 아니다.",
  ui_story_5033_50330502_37_dialog_content = "반대로 오직 그 소녀만이 그런 기술을 가지고 있다곤 단언할 수 없다는 것이다.",
  ui_story_5033_50330502_38_dialog_content = "확실히 지금의 유포리아는 예전만 못하지.",
  ui_story_5033_50330502_39_dialog_content = "하지만 어둠의 위기 전, 그 용병단에서 그런 기술을 가진 자가 얼마나 있었고,\n그들이 몇 명에게 그런 기술을 전수했는지는...",
  ui_story_5033_50330502_40_dialog_content = "완전히 미지수다.",
  ui_story_5033_50330502_41_dialog_content = "그렇습니다. 그래서 저도 추측만 하고 있을 뿐입니다.",
  ui_story_5033_50330502_42_dialog_content = "하지만 정말로 죽을 위기에서 살아 돌아오는 데 성공해서,\n이름을 숨긴 채로 지금까지 살아있다면...",
  ui_story_5033_50330502_43_dialog_content = "움브라톤도, 유포리아 입장에서도 가만히 두고 볼 순 없는 일이지.",
  ui_story_5033_50330502_44_dialog_content = "자주 격투장에 드나들었던 사람에게 있어서 가장 힘든 일이 뭔지 아나?",
  ui_story_5033_50330502_45_dialog_content = "적어도 살아남는 건 아닐 것 같군요.\n살아남는 것도, 죽는 것도 모두 생각보다 쉽게 이룰 수 있으니까요.",
  ui_story_5033_50330502_46_dialog_content = "자기 몸에 있는 괴사한 부위를 즉시 도려내는 일이다.",
  ui_story_5033_50330502_47_dialog_content = "음? 그게 전부입니까?",
  ui_story_5033_50330502_48_dialog_content = "썩어가는 부위들이 자리를 차지하면, 새 조직이 돋아나질 못하거든.",
  ui_story_5033_50330502_49_dialog_content = "그러다 보면 온몸이 상해버리는 때가 오게 되고, 투사의 자격도 잃게 되지.",
  ui_story_5033_50330502_50_dialog_content = "하지만 환부를 도려내는 건 의사가 할 일 아닙니까?",
  ui_story_5033_50330502_51_dialog_content = "그래서 내가 가장 신뢰하는 의사에게 이번 일을 맡긴 것이다.",
  ui_story_5033_50330502_52_dialog_content = "그나저나, 소문대로라면 다른 한 소녀는 대결에서 살아남지 않았나.",
  ui_story_5033_50330502_53_dialog_content = "그렇다면 적어도 그 기술에 당한다고 전부 죽는 건 아니라는 얘기군.",
  ui_story_5033_50330502_54_dialog_content = "<color=#e8d9bb>똑똑똑──</color>",
  ui_story_5033_50330502_55_dialog_content = "이스타반 삼촌, 와타리가 발견한 피해자가... 깨어났어요.",
  ui_story_5033_50330502_56_dialog_content = "봐라, 말한 대로 아닌가.",
  ui_story_5033_50330601_1_dialog_content = "들어가자.",
  ui_story_5033_50330601_2_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5033_50330601_3_dialog_content = "얘들아! 네코야시키 오빠가 돌아왔어! 빨리 와 봐!",
  ui_story_5033_50330601_4_dialog_content = "쉿! 라탄, 조용히 해. 난 카스타를 만나러 온 거야.",
  ui_story_5033_50330601_5_dialog_content = "카스타는 빵 가지러 갔어. 가서 불러와 줄까?",
  ui_story_5033_50330601_6_dialog_content = "가서 「움브라톤에서 온 손님이 도착했다」고 전해 줘.",
  ui_story_5033_50330601_7_dialog_content = "응, 그럼 애들이랑 좀 놀아주고 있어 줘~",
  ui_story_5033_50330601_8_dialog_content = "네코야시키, 사탕 가져왔어?",
  ui_story_5033_50330601_9_dialog_content = "아, 가져왔지.",
  ui_story_5033_50330601_10_dialog_content = "네코야시키! 앉아 봐! 내가 좋은 거 줄 거 있어!",
  ui_story_5033_50330601_11_dialog_content = "어휴, 나 좀 그만 괴롭혀라...",
  ui_story_5033_50330601_12_dialog_content = "왜 애들이 이렇게 많아?",
  ui_story_5033_50330601_13_dialog_content = "이 애들은 다 「레이븐즈 블러드」에 맡겨진... 으, 꼬맹이 너 지금 내 머리에 뭐 올려놨어?",
  ui_story_5033_50330601_14_dialog_content = "헤헤, 내가 엄청 힘들게 잡은 바퀴벌레야! 마음에 들어?",
  ui_story_5033_50330601_15_dialog_content = "너 이 자식, 내가 진짜 가만 안 둬!",
  ui_story_5033_50330601_16_dialog_content = "아하하! 네코야시키가 화났다! 다들 도망쳐!",
  ui_story_5033_50330601_17_dialog_content = "어떻게 된 건지 설명할 겨를이 없을 것 같네.",
  ui_story_5033_50330601_18_dialog_content = "딱히 설명할 것도 없어.",
  ui_story_5033_50330601_19_dialog_content = "대부분 떠돌아다니다가 여기까지 오게 된 아이들이니까.",
  ui_story_5033_50330601_20_dialog_content = "클랜들의 내부 항쟁 때문에 부모를 잃은 고아들이나, 불법 산업의 피해자들도 있어.",
  ui_story_5033_50330601_21_dialog_content = "더 좋은 보호소를 찾기 전까지 여기에 맡겨진 거야.\n우리 「레이븐즈 블러드」가 지켜줄 수 있으니까.",
  ui_story_5033_50330601_22_dialog_content = "당신이 네코야시키가 말한 「카스타」인가?",
  ui_story_5033_50330601_23_dialog_content = "우린...",
  ui_story_5033_50330601_24_dialog_content = "소개 안 해도 돼. 너희가 뭘 조사하고 싶어 하는지도 다 알고 있어.\n자세한 건 폴룩스가 돌아오면 그때 얘기하자.",
  ui_story_5033_50330601_25_dialog_content = "난 지금 저 애들 밥을 준비해야 되거든.",
  ui_story_5033_50330601_26_dialog_content = "알겠다. 얼마든 기다릴 수 있으니 우선 할 일부터 해.",
  ui_story_5033_50330601_27_dialog_content = "야! 꼬맹이들! 먹고 나면 낮잠도 자야 되니까, 빨리 와서 빵 먹어!",
  ui_story_5033_50330601_28_dialog_content = "네에!",
  ui_story_5033_50330601_29_dialog_content = "으아, 이제 좀 살겠네. 이 똥강아지 녀석들.",
  ui_story_5033_50330601_30_dialog_content = "볼 일은 다 끝냈나? 그럼 아까 하던 얘길 마저 해 줬으면 좋겠는데.",
  ui_story_5033_50330601_31_dialog_content = "크흠, 그럼 흥신소의 주인으로서 두 사람한테 설명을 좀 해 줄게.",
  ui_story_5033_50330601_32_dialog_content = "일단 두 사람이 타키 소개로 날 찾아온 건 알고 있어.",
  ui_story_5033_50330601_33_dialog_content = "근데 유포리아 쪽 사정에 대해선 나보다 저 「레이븐즈 블러드」가\n더 빠삭하니까 저쪽에 물어보는 게 나을 거야.",
  ui_story_5033_50330601_34_dialog_content = "그리고 카스타, 너희가 접촉하고 싶었던 외지인들이 바로 이 둘이야.\n그럼 나머지 볼일은 서로 알아서 해결하라고.",
  ui_story_5033_50330601_35_dialog_content = "난 다른 일도 있으니까 먼저 가 봐야겠어.",
  ui_story_5033_50330601_36_dialog_content = "그래. 볼일 있으면 우리가 부를 테니까. 별일 없으면 와서 귀찮게 하지 마.",
  ui_story_5033_50330601_37_dialog_content = "우와, 볼일 다 봤다고 바로 버리네. 나 상처받았어.",
  ui_story_5033_50330601_38_dialog_content = "돌아가고 싶다고 계속 쫑알거린 건 너잖아.\n갈 거면 빨리 가. 빵 나눠 줘야 하는데 자꾸 길 막지 말고.",
  ui_story_5033_50330601_39_dialog_content = "카스타 언니! 내가 도와줄게!",
  ui_story_5033_50330601_40_dialog_content = "나도! 나도 도와줄래!",
  ui_story_5033_50330601_41_dialog_content = "그래. 그럼 라탄은 더 어린 애들한테 이 빵들을 나눠 주고,\n쉐베는 버터를 나눠 줘. 많이 줘도 돼.",
  ui_story_5033_50330601_42_dialog_content = "응! 알겠어!",
  ui_story_5033_50330601_43_dialog_content = "난 가서 버터 가져올게! 나 버터 어디 있는지 알아!",
  ui_story_5033_50330601_44_dialog_content = "방해하고 싶진 않지만, 이건 꼭 물어봐야겠어. 왜 아이들 몸에 상처가 있는 거지?",
  ui_story_5033_50330601_45_dialog_content = "유포리아에서 떠돌던 고아들이 좋은 생활을 했을 것 같아?",
  ui_story_5033_50330601_46_dialog_content = "사람들 손에 상처를 입었고, 지금은 그 상처들을 싸매 논 거지... 그게 다야.",
  ui_story_5033_50330601_47_dialog_content = "나한테 아이들의 상처를 보여줄 수 있을까? 난 한때 의사였어.",
  ui_story_5033_50330601_48_dialog_content = "의사였다고?",
  ui_story_5033_50330601_49_dialog_content = "아까 보니 아이들의 몸에 있는 상처는 전부 깨끗한 붕대로 꼼꼼히 감싸 놨더군.",
  ui_story_5033_50330601_50_dialog_content = "하지만 몇몇 아이들의 정신 건강이 좋지 않아 보였다. 자세히 검사해 봐야 해.",
  ui_story_5033_50330601_51_dialog_content = "헤에, 역시 우린 오늘도 운이 좋은 모양이네.\n좋아, 대신 아이들이 밥 다 먹을 때까지 기다려 줘.",
  ui_story_5033_50330601_52_dialog_content = "(어? 누가 내 손가락을...)",
  ui_story_5033_50330601_53_dialog_content = "꼬마야? 왜 그러니?",
  ui_story_5033_50330601_54_dialog_content = "으음... 네코야시키가 오빠 주머니에 사탕을 넣어 뒀댔어..",
  ui_story_5033_50330601_55_dialog_content = "사, 사탕을 먹고 싶으면 오빠한테 가랬어.",
  ui_story_5033_50330601_56_dialog_content = "그 사람이 내 주머니에 사탕을 넣어 뒀다고? 언제? 난 왜 몰랐지...?",
  ui_story_5033_50330601_57_dialog_content = "어? 진짜 있네?",
  ui_story_5033_50330601_58_dialog_content = "그거... 나 먹어도 돼?",
  ui_story_5033_50330601_59_dialog_content = "응, 받아. 기다리게 해서 미안.",
  ui_story_5033_50330601_60_dialog_content = "고마워!",
  ui_story_5033_50330601_61_dialog_content = "밥 먹기 전에 사탕 많이 먹으면 안 돼!",
  ui_story_5033_50330601_62_dialog_content = "음... 알겠어.",
  ui_story_5033_50330601_63_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_5033_50330601_64_dialog_content = "배고픈가?",
  ui_story_5033_50330601_65_dialog_content = "미, 미안. 이게 내가 어떻게 할 수 있는 게 아니라서... 아까 좀 뛰어서 그런가 봐.",
  ui_story_5033_50330601_66_dialog_content = "아이들 빵을 빼앗아 먹을 생각은 절대 없어.",
  ui_story_5033_50330601_67_dialog_content = "하하, 너희 꽤 재미있네. 하나는 의사였던 킬러고, 하나는 다 큰 아이잖아.",
  ui_story_5033_50330601_68_dialog_content = "폴룩스가 너흴 「환영」하기로 한 것도 나쁘지 않은 결정이었던 것 같아.",
  ui_story_5033_50330601_69_dialog_content = "당연하잖아. 움브라톤과 「적대」하는 것보단 「협력」하는 게 훨씬 나으니까.",
  ui_story_5033_50330601_70_dialog_content = "이 고소한 냄새... 크루아상이다~",
  ui_story_5033_50330601_71_dialog_content = "응, 꽤 많이 가져왔으니까 오늘은 좀 많이 먹어도 돼.",
  ui_story_5033_50330601_72_dialog_content = "폴룩스, 나눠 주는 건 내가 할게. 넌 손님들이랑 인사 나눠...\n크루아상 먹고 싶은 사람은 이쪽으로 와!",
  ui_story_5033_50330601_73_dialog_content = "우와아아! 신난다~",
  ui_story_5033_50330601_74_dialog_content = "괜찮다면 두 사람도 좀 먹어.",
  ui_story_5033_50330601_75_dialog_content = "고맙군. 그럼 사양하지 않겠다.",
  ui_story_5033_50330601_76_dialog_content = "받아라, PlayerName.",
  ui_story_5033_50330601_77_dialog_content = "고, 고마워...",
  ui_story_5033_50330601_78_dialog_content = "미안, 사건 조사하러 온 건데 도움도 별로 안 되고 번거롭게 만들어서.",
  ui_story_5033_50330601_79_dialog_content = "자책할 필요는 없다.",
  ui_story_5033_50330601_80_dialog_content = "협력하고 신뢰할 수 있는 사람을 찾았다는 것만으로도,\n내 예상보단 훨씬 잘 진행되는 중이니까.",
  ui_story_5033_50330601_81_dialog_content = "응, 유포리아에 아이들을 위해 보호소를 만들었을 정도라면...",
  ui_story_5033_50330601_82_dialog_content = "실력도 실력이겠지만, 분명히 마음씨 좋은 사람들일 것 같아.",
  ui_story_5033_50330601_83_dialog_content = "과찬이야. 하지만 아이들을 돌보는 일은 확실히 쉬운 일은 아냐.",
  ui_story_5033_50330601_84_dialog_content = "아이들을 더 나은 곳으로 보낼 생각은 안 해 봤나?",
  ui_story_5033_50330601_85_dialog_content = "움브라톤에는 섀도우마스터가 세운 고아원들이 꽤 있다. 시설도 좋지.",
  ui_story_5033_50330601_86_dialog_content = "당연히 생각해 봤어. 그래서 협력 대상으로 당신들을 선택한 거야.",
  ui_story_5033_50330601_87_dialog_content = "모든 사람들이 유포리아 출신 고아들을 평범하게 대해 주는 건 아니거든.\n그래서 이 아이들을 받아줄 수 있는 곳이 필요해.",
  ui_story_5033_50330601_88_dialog_content = "그랬군.",
  ui_story_5033_50330601_89_dialog_content = "게다가 여길 떠나고 싶지 않다는 아이들도 몇 명 있어,\n그리고 최근 유포리아와 움브라톤의 관계도 긴장 상태고...",
  ui_story_5033_50330601_90_dialog_content = "뭐, 사건이 마무리되고 나면 천천히 얘기해 보자.",
  ui_story_5033_50330601_91_dialog_content = "그러지. 아이들이라면 섀도우마스터가 받아주실 거다. 그건 내가 보증하지.",
  ui_story_5033_50330601_92_dialog_content = "사건을 조사하는 동안엔 우리도 여기 일을 좀 도와줄게요.",
  ui_story_5033_50330601_93_dialog_content = "참! 수녀가 여기 오면 아이들을 돌보는 데 도움이 될 수도 있겠네요.",
  ui_story_5033_50330601_94_dialog_content = "수녀? 교회에서 수녀를 파견했어?",
  ui_story_5033_50330601_95_dialog_content = "아마 그럴걸요. 유포리아로 오는 비공정에서 여기 오려는 수녀를 만났거든요.",
  ui_story_5033_50330601_96_dialog_content = "그 수녀가 우리보다 먼저 도착할 줄 알았는데요.",
  ui_story_5033_50330601_97_dialog_content = "유포리아는 이미 오랫동안 수녀가 없었어. 어쩌면 다들 오고 싶지 않을지도 몰라.",
  ui_story_5033_50330601_98_dialog_content = "하지만 이 교회는 아직 이렇게 존재하지. 낡고 오래되긴 했어도...\n「오기 싫어질」 정도는 아니라고 생각하는데.",
  ui_story_5033_50330601_99_dialog_content = "사실 내 이름은 내가 유포리아에서 떠돌이 생활을 할 때 만난 수녀님이 지어 주신 거야.",
  ui_story_5033_50330601_100_dialog_content = "나중에 내가 교회를 떠나고 나선 수녀님과 연락이 끊겨 버렸어.",
  ui_story_5033_50330601_101_dialog_content = "8, 9년 전쯤 이 일대가 아수라장이 되었을 때, 수녀님이 더 많은 아이들을 구하려고\n움브라톤에 가셨다가 그만 돌아가셨다는 얘길 들었어.",
  ui_story_5033_50330601_102_dialog_content = "그 뒤로 이 교회는 점점 폐허로 변해가기 시작했어.\n심지어는 누군가의 사주를 받고 파괴된 적도 있었고.",
  ui_story_5033_50330601_103_dialog_content = "그래서 결국 두 사람만...",
  ui_story_5033_50330601_104_dialog_content = "응, 나랑 카스타가 「레이븐즈 블러드」를 만들고 이 교회를 고쳤어.\n그리고 여길 거점으로 삼고 떠돌이 생활을 하는 아이들을 받아들였어.",
  ui_story_5033_50330601_105_dialog_content = "교회에서 정말로 수녀를 파견해 준 거라면 다행이겠네.",
  ui_story_5033_50330601_106_dialog_content = "다행? 폴룩스, 너 진짜 그렇게 생각해?",
  ui_story_5033_50330601_107_dialog_content = "난 네가... 아무도 우리 <color=#FFB400>마틸다</color> 수녀님을\n대신할 순 없다고 할 줄 알았어.",
  ui_story_5033_50330601_108_dialog_content = "카스타, 이건 대신한다는 게 아니야.",
  ui_story_5033_50330601_109_dialog_content = "두 사람 다 그 마틸다 수녀라는 사람과 각별했던 모양이군.",
  ui_story_5033_50330601_110_dialog_content = "나도 유포리아를 떠돌던 고아였어. 그리고 날 받아 준 건 수녀님이었고.",
  ui_story_5033_50330601_111_dialog_content = "수녀님이 아니었다면 난 폭력조직의 손에 떨어졌겠지. 그리고 폴룩스는...",
  ui_story_5033_50330601_112_dialog_content = "됐어. 우리 추억 얘기는 그만하자. 이제 와타리 씨가 맡은 사건에 대해 들어봐야지.",
  ui_story_5033_50330601_113_dialog_content = "대략적인 상황은 네코야시키를 통해 들었어.",
  ui_story_5033_50330601_114_dialog_content = "움브라톤에 이상한 살인 사건들이 발생했고, 당신들은 지금 그 사건의 범인이\n유포리아와 관련된 인물이라고 의심하고 있다는 거.",
  ui_story_5033_50330601_115_dialog_content = "이 사건에 대한 설명을 듣고 나면, 아마 우릴 도와주고 싶은 마음이 더 커질 거다.",
  ui_story_5033_50330601_116_dialog_content = "왜지?",
  ui_story_5033_50330601_117_dialog_content = "이런 말을 하게 돼 유감이다만... 마틸다 수녀는 사고로 세상을 떠난 게 아니다.",
  ui_story_5033_50330601_118_dialog_content = "현지 교회를 통해 확인한 정보에 따르면, 마틸다 수녀의 몸에도 연쇄 살인 사건의\n피해자들과 같은 형태의 이상한 상처가 남아 있더군.",
  ui_story_5033_50330601_119_dialog_content = "뭐라고?!",
  ui_story_5033_50330601_120_dialog_content = "<color=#e8d9bb>쨍그랑──!</color>",
  ui_story_5033_50330601_121_dialog_content = "<size=45>지금 뭐라 그랬어?! 다시 말해 봐!</size>",
  ui_story_5033_50330601_122_dialog_content = "진정해. 두 사람 때문에 저쪽에 있는 아이들이 겁먹었다.",
  ui_story_5033_50330601_123_dialog_content = "......",
  ui_story_5033_50330601_124_dialog_content = "괘, 괜찮아. 다들 무서워하지 마... 그냥 카스타 언니가 많이 흥분해서 그런 거야.",
  ui_story_5033_50330601_125_dialog_content = "미안해, 얘들아. 좀 뜻밖의 상황이 생겨 버렸네.",
  ui_story_5033_50330601_126_dialog_content = "우린 밖에 있는 골목에서 얘기 좀 하고 올게.\n다들 밥 잘 챙겨 먹으렴. 혹시 무슨 일 생기면 부르고.",
  ui_story_5033_50330601_127_dialog_content = "...응.",
  ui_story_5033_50330601_128_dialog_content = "아이들이 좀 떨고 있으니까, 난 여기서 아이들이랑 같이 있어 줄게.",
  ui_story_5033_50330601_129_dialog_content = "그래, 그럼 부탁한다, PlayerName.",
  ui_story_5033_50330601_130_dialog_content = "가자, 이 일에 대해 <size=45>제대로</size> 이야길 나눠 봐야 할 것 같으니까.",
  ui_story_5033_50330701_1_dialog_content = "냠냠...",
  ui_story_5033_50330701_2_dialog_content = "......",
  ui_story_5033_50330701_3_dialog_content = "라탄, 왜 안 먹어?",
  ui_story_5033_50330701_4_dialog_content = "자꾸 문밖만 쳐다보고. 혹시 두 사람이 걱정돼서 그러는 거야?",
  ui_story_5033_50330701_5_dialog_content = "응... 카스타 언니가 그렇게 화난 건 거의 본 적 없었거든.",
  ui_story_5033_50330701_6_dialog_content = "그리고 폴룩스 언니도... 카스타 언니보단 괜찮아 보였지만...\n난 알 수 있어. 폴룩스 언니도 엄청 화가 많이 나 있었어.",
  ui_story_5033_50330701_7_dialog_content = "아마 엄청, 엄청 심각한 일이 일어난 게 분명해.",
  ui_story_5033_50330701_8_dialog_content = "너희도 다 느꼈구나...",
  ui_story_5033_50330701_9_dialog_content = "(정말 어른스럽고 예민한 아이들이네.)",
  ui_story_5033_50330701_10_dialog_content = "응, 난 다 알아.",
  ui_story_5033_50330701_11_dialog_content = "평소엔 무슨 일이 생기든, 네코야시키 오빠가 무슨 소식을 전해주든...",
  ui_story_5033_50330701_12_dialog_content = "카스타 언니랑 폴룩스 언니는 절대로 우리 앞에선 안 좋은 감정을 드러내지 않았어.",
  ui_story_5033_50330701_13_dialog_content = "그런 두 사람이 그렇게 화내면서 말하고 소리친 건 이번이 처음이었어.",
  ui_story_5033_50330701_14_dialog_content = "괜찮을 거야. 너무 걱정하지 마. 이번 일을 끝내고 나면 분명히 화도 가라앉을 테니까.",
  ui_story_5033_50330701_15_dialog_content = "혹시... <color=#FFB400>마틸다</color> 수녀님 일이야?",
  ui_story_5033_50330701_16_dialog_content = "그것도 들었어?",
  ui_story_5033_50330701_17_dialog_content = "응, 무슨 얘기하는지 계속 다 듣고 있었어.",
  ui_story_5033_50330701_18_dialog_content = "그 수녀님에 대한 일인 건 맞아.",
  ui_story_5033_50330701_19_dialog_content = "근데 자세한 건 우리도 아직 확실하게 조사하진 못했어.",
  ui_story_5033_50330701_20_dialog_content = "조사가 끝나고 나면 폴룩스 씨랑 카스타가 분명히 너희한테도 설명해 줄 거야.",
  ui_story_5033_50330701_21_dialog_content = "응, 알았어...",
  ui_story_5033_50330701_22_dialog_content = "어라?",
  ui_story_5033_50330701_23_dialog_content = "왜 그래?",
  ui_story_5033_50330701_24_dialog_content = "방금 밖에서 누가 지나간 것 같은데? 오빠 뒤쪽에 저기서.",
  ui_story_5033_50330701_25_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5033_50330701_26_dialog_content = "밖엔 아무도 없는데?",
  ui_story_5033_50330701_27_dialog_content = "이상하네... 내가 잘못 봤나? 분명히 검은 그림자 같은 게 지나갔는데.",
  ui_story_5033_50330701_28_dialog_content = "숨은 건가? 내가 감응해 볼게...",
  ui_story_5033_50330701_29_dialog_content = "감응이 뭔데?",
  ui_story_5033_50330701_30_dialog_content = "간단히 말하면 사람 찾을 때 쓰는 방법이야. 내 특기거든.",
  ui_story_5033_50330701_31_dialog_content = "난 루미나랑 다크매터에 아주 민감해.",
  ui_story_5033_50330701_32_dialog_content = "그거 왠지 대단한데?",
  ui_story_5033_50330701_33_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5033_50330701_34_dialog_content = "옆에 있는 골목에선 강한 루미나가 셋 느껴져.\n아마 와타리 씨랑 폴룩스 씨, 카스타일 거야.",
  ui_story_5033_50330701_35_dialog_content = "그리고 이 근처에서 어슬렁거리는 암귀들도 몇 마리 있는데,\n교회에선 좀 멀리 떨어져 있어.",
  ui_story_5033_50330701_36_dialog_content = "조금 더 먼 곳엔 대부분 평범한 사람들인 것 같아. 아마 저 사람들은 아닐 거야.",
  ui_story_5033_50330701_37_dialog_content = "그럼... 내가 잘못 본 거겠네.",
  ui_story_5033_50330701_38_dialog_content = "걱정을 너무 많이 하면 그럴 수도 있어.\n일단 교회 안으로 들어가서 다들 올 때까지 기다리자.",
  ui_story_5033_50330701_39_dialog_content = "여기 너무 오래 있으면 밖에 있는 암귀들이 우릴 발견할지도 몰라.",
  ui_story_5033_50330701_40_dialog_content = "응, 알겠어.",
  ui_story_5033_50330701_41_dialog_content = "좋아, 그럼 들어가서 밥 먹자.",
  ui_story_5033_50330701_42_dialog_content = "그나저나 와타리 씨 쪽은 어떻게 돼 가고 있으려나...",
  ui_story_5033_50330701_43_dialog_content = "내가 정식으로 이번 사건을 맡게 된 건 한 달 전쯤이다.",
  ui_story_5033_50330701_44_dialog_content = "섀도우마스터가 검시를 할 사람이 필요하다고 해서 사체를 검시했고,\n그러던 중 범인이 사체에 남긴 상흔을 발견했지.",
  ui_story_5033_50330701_45_dialog_content = "<color=#e8d9bb>한 달 전</color>",
  ui_story_5033_50330701_46_dialog_content = "그러니까 며칠 전 병으로 사망한 환자한테서도 이런 상처들을 발견했다는 건가요?",
  ui_story_5033_50330701_47_dialog_content = "그래. 정확히 말하자면 이상하게 병사해 버린 그 환자는 사실\n사망할 정도로 상태가 안 좋진 않았다.",
  ui_story_5033_50330701_48_dialog_content = "지금 생각해 보면 어쩌면 병 때문에 사망한 게 아닌 것 같다는 생각이 들어...",
  ui_story_5033_50330701_49_dialog_content = "아무래도 연쇄 살인 사건인 것 같아요.",
  ui_story_5033_50330701_50_dialog_content = "얼마 전에도 이상하게 사망해 버린 사람들이 있었나?",
  ui_story_5033_50330701_51_dialog_content = "있었어요. 근데 사체엔 전부 꽃이 피었는데... 꺼내서 보여줄까요?",
  ui_story_5033_50330701_52_dialog_content = "그래. 그 사람들의 사인을 다시 조사해야 할 필요가 있거든.",
  ui_story_5033_50330701_53_dialog_content = "그리고 자료들을 정리해서 섀도우마스터께 제출해야 돼.",
  ui_story_5033_50330701_54_dialog_content = "알겠어요. 그러는 건 별로 안 좋아하지만...",
  ui_story_5033_50330701_55_dialog_content = "그럼 이 사람은요? ...이제 묻을까요?",
  ui_story_5033_50330701_56_dialog_content = "그...그렇게 서두를 거 없잖아. 그 사람은 아직 숨이 붙어있으니까 구할 수 있어.",
  ui_story_5033_50330701_57_dialog_content = "네, 알겠어요.",
  ui_story_5033_50330701_58_dialog_content = "피해자들의 몸엔 이상한 상처가 남아 있었다.",
  ui_story_5033_50330701_59_dialog_content = "그리고 그 뒤에도 범인은 몇 차례 더 범행을 저질렀지.",
  ui_story_5033_50330701_60_dialog_content = "만약 범인의 범행 빈도가 증가하지 않았다면,\n우린 이게 연쇄 살인 사건이라는 걸 영원히 몰랐을지도 모른다.",
  ui_story_5033_50330701_61_dialog_content = "우린 범인의 범행 흔적은 파악하고 있었지만, 줄곧 유력한 단서를 못 찾고 있었다.",
  ui_story_5033_50330701_62_dialog_content = "그렇게 단서를 찾아다니다가, 우린 몇 년 전 발생한 변사 사건의 피해자들에게도\n비슷한 흉터가 있었다는 것을 알아냈다.",
  ui_story_5033_50330701_63_dialog_content = "그 발견의 시발점이 된 사건이 바로...\n현지 교회에서 제공한 마틸다 수녀 변사 사건의 검시 보고서였다.",
  ui_story_5033_50330701_64_dialog_content = "범인이 유포리아와 관계가 있는 인물이라고 어떻게 특정할 수 있지?\n그 망할 범인은 지금 어디 있어?!",
  ui_story_5033_50330701_65_dialog_content = "우리도 아직 범인에 대한 단서는 없다.\n범인에 대한 특정 방법도... 지금으로선 추측일 뿐이다.",
  ui_story_5033_50330701_66_dialog_content = "마침 유포리아에 「사신」이 출몰한다는 소문이 있더군.",
  ui_story_5033_50330701_67_dialog_content = "유포리아를 흔들려는 자나 유포리아의 규칙을 어기는 자가 있다면...\n누구든 그 「사신」을 만나게 된다고 들었다.",
  ui_story_5033_50330701_68_dialog_content = "그 「사신」은 소리 없이 나타나 흔적도 남기지 않고 사람들의 목숨을 앗아 간다더군.",
  ui_story_5033_50330701_69_dialog_content = "무슨 소릴 하는 거야? 똑바로 설명해.",
  ui_story_5033_50330701_70_dialog_content = "다시 말해서 굉장히 높은 수준의 살인 기술이라는 거다.",
  ui_story_5033_50330701_71_dialog_content = "소문으론 그런 살인 기술은 현장에 「단 한 방울의 피」도,\n「단 하나의 흔적」도 남기지 않는다던데.",
  ui_story_5033_50330701_72_dialog_content = "아니, 흔적은 남아.",
  ui_story_5033_50330701_73_dialog_content = "단지 평범한 베인 상처로 보이는 것뿐이지.",
  ui_story_5033_50330701_74_dialog_content = "폴룩스, 당신 그 기술을 알고 있는 건가?",
  ui_story_5033_50330701_75_dialog_content = "당연하지... <color=#FFB400>나도 할 줄 알거든</color>.",
  ui_story_5033_50330701_76_dialog_content = "뭐라고?!",
  ui_story_5033_50330702_1_dialog_content = "빵도 다 먹었는데 왜 카스타 언니가 낮잠 자라고 안 부르지?",
  ui_story_5033_50330702_2_dialog_content = "아까 카스타 누나가 빵 다 먹으면 의사 선생님부터 만나야 된다 그랬어.",
  ui_story_5033_50330702_3_dialog_content = "오늘 온 그 사람이 의사 선생님이야?",
  ui_story_5033_50330702_4_dialog_content = "응, 피부가 새카맣게 탄 그 사람이 의사 선생님이래.",
  ui_story_5033_50330702_5_dialog_content = "그럼 언니들이랑 의사 선생님은 언제 돌아와?",
  ui_story_5033_50330702_6_dialog_content = "아니면 우리 먼저 자자.",
  ui_story_5033_50330702_7_dialog_content = "이따가 일어나면 다들 돌아와 있을 거야.",
  ui_story_5033_50330702_8_dialog_content = "라탄 말이 맞아! 다들 먼저 자. 자고 일어나면 다 해결돼 있을 거야.",
  ui_story_5033_50330702_9_dialog_content = "에이... 대충 얼버무리려고 그러는 거 다 알아.",
  ui_story_5033_50330702_10_dialog_content = "형아, 우리가 세 살짜리 꼬맹이로 보여?",
  ui_story_5033_50330702_11_dialog_content = "아, 너, 넌 아까 네코야시키 머리 위에 바퀴벌레 놨던 걔 맞지?",
  ui_story_5033_50330702_12_dialog_content = "헤헤, 맞아.",
  ui_story_5033_50330702_13_dialog_content = "얼렁뚱땅 우릴 재우려고? 어림도 없지!",
  ui_story_5033_50330702_14_dialog_content = "말해! 두 사람 다 여긴 왜 온 거야?",
  ui_story_5033_50330702_15_dialog_content = "(아, 머리 아파... 애들 돌보는 게 이렇게 힘든 일이었어?!)",
  ui_story_5033_50330702_16_dialog_content = "우린 「레이븐즈 블러드」랑 협력하러... 음, 아니지.\n「레이븐즈 블러드」가 먼저 우리한테 협력해 달라고 했어.",
  ui_story_5033_50330702_17_dialog_content = "난 모두랑 같이 엄청난 사건을 조사하고 있어.",
  ui_story_5033_50330702_18_dialog_content = "엄청난 사건이 뭔데?",
  ui_story_5033_50330702_19_dialog_content = "그건 말이지...",
  ui_story_5033_50330702_20_dialog_content = "(다시는 이 일에 대해 못 물어보게 겁을 제대로 줘야겠어.)",
  ui_story_5033_50330702_21_dialog_content = "<anim type=Shake><size=45>완전 무시무시한 살인 사건이야!</size></anim>",
  ui_story_5033_50330702_22_dialog_content = "......",
  ui_story_5033_50330702_23_dialog_content = "너, 너네 왜 하나도 안 놀라?",
  ui_story_5033_50330702_24_dialog_content = "여긴 유포리아거든. 아무튼, 형아가 말한 그 사건이란 게 그렇게 무서워?",
  ui_story_5033_50330702_25_dialog_content = "그럼, 엄청 무섭지... 어... 미안, 나도 모르게 너흴 평범한 꼬마라고 생각했나 봐.",
  ui_story_5033_50330702_26_dialog_content = "하하, 우릴 평범한 꼬마라고 생각했대! 이 형아 진짜 이상해!",
  ui_story_5033_50330702_27_dialog_content = "그러게. 사람들은 다... 유포리아 애들을 싫어하는데.",
  ui_story_5033_50330702_28_dialog_content = "안 이상하거든! 애들을 애들로 보는 게 뭐가 이상해?",
  ui_story_5033_50330702_29_dialog_content = "너희가 어디 출신이든, 어떤 일들을 겪었든 내 눈엔 다 평범한 애들이야.",
  ui_story_5033_50330702_30_dialog_content = "애들은 원래 잘 먹고, 잘 자면 되는 거야. 위험한 일 때문에 걱정할 필요도 없어.\n애초부터 애들이 그런 걱정을 하게 만들면 안 되지!",
  ui_story_5033_50330702_31_dialog_content = "그런 위험하고 무서운 일들은 폴룩스 씨랑 카스타가 해결해 줄 거야.",
  ui_story_5033_50330702_32_dialog_content = "응, PlayerName 오빠 말이 맞아...\n그리고 폴룩스 언니랑 카스타 언니도 똑같은 얘길 했었어.",
  ui_story_5033_50330702_33_dialog_content = "음...",
  ui_story_5033_50330702_34_dialog_content = "어... 형아 사실은 착한 사람이었구나.",
  ui_story_5033_50330702_35_dialog_content = "그럼 더 안 물어볼게. 우리 같이 낮잠 자자!",
  ui_story_5033_50330702_36_dialog_content = "PlayerName, 우리랑 같이 낮잠 자자!",
  ui_story_5033_50330702_37_dialog_content = "오빠! 나 아직 사탕 먹고 싶어!",
  ui_story_5033_50330702_38_dialog_content = "어! 갑자기 몰려오면 안 돼. 넘어질 것 같아!",
  ui_story_5033_50330702_39_dialog_content = "사탕 있어? 우리도 먹을래...",
  ui_story_5033_50330702_40_dialog_content = "그럼, 있지. 네코야시키가 내 주머니에 많이 넣어 놨거든.",
  ui_story_5033_50330702_41_dialog_content = "하나씩 나눠줄 테니까 보채면 안 돼.",
  ui_story_5033_50330702_42_dialog_content = "네코야시키 녀석, 역시 뭘 좀 아는데?",
  ui_story_5033_50330702_43_dialog_content = "야, 어린애가 말을 그렇게 하면 안 돼.",
  ui_story_5033_50330702_44_dialog_content = "네코야시키가 너보다 나이도 많은데, 형이라고 불러야지.",
  ui_story_5033_50330702_45_dialog_content = "에이, 왜 갑자기 잔소리야? 앗! 내 사탕 가져가지 마!",
  ui_story_5033_50330702_46_dialog_content = "이건 네코야시키가 준 사탕이니까.\n네가 형 대접을 안 해 주는데, 내가 이걸 어떻게 주겠어?",
  ui_story_5033_50330702_47_dialog_content = "흥, 나랑 네코야시키는 사이 완전 좋거든.\n그리고 네코야시키는 나한테 형 대접해 달라는 말은 한 번도 안 했어.",
  ui_story_5033_50330702_48_dialog_content = "그거 알아? 네코야시키 말야, 처음 여기 왔을 땐 완전 딱딱한 성격이었어.",
  ui_story_5033_50330702_49_dialog_content = "그러다가 어느 날 밖에서 사람들한테 막 두들겨 맞다가 교회로 도망쳐 왔거든.",
  ui_story_5033_50330702_50_dialog_content = "마침 교회에 폴룩스 누나랑 카스타 누나가 있어서 살았어.",
  ui_story_5033_50330702_51_dialog_content = "너 꼭 네가 직접 본 것처럼 말하네? 너 그때도 여기 있었어?",
  ui_story_5033_50330702_52_dialog_content = "설마 네가 네코야시키보다 「선배」라는 거야?",
  ui_story_5033_50330702_53_dialog_content = "에이, 그럴 리가 없잖아! 난 그때 다섯 살이었어.",
  ui_story_5033_50330702_54_dialog_content = "근데 왜 그렇게 어깨에 힘이 들어간 건데?",
  ui_story_5033_50330702_55_dialog_content = "그러니까 나랑 네코야시키는 이렇게나 사이가 좋다고 설명해 주는 거잖아.",
  ui_story_5033_50330702_56_dialog_content = "우린 네 거 내 거 안 따지는 형제 같은 사이라구. 예의 그런 거 안 따진다니까?",
  ui_story_5033_50330702_57_dialog_content = "그래... 네코야시키도 그런 과거가 있었구나.\n어쩐지 「레이븐즈 블러드」랑 사이가 좋아 보이더라.",
  ui_story_5033_50330702_58_dialog_content = "어떤 의미에선 네코야시키도 「레이븐즈 블러드」의 보호를 받고 자란 아이라는 거네.",
  ui_story_5033_50330702_59_dialog_content = "헤헷, 바로 그거야. 네코야시키 오빠도 처음에 교회에 왔을 땐 완전 꼬마였대.",
  ui_story_5033_50330702_60_dialog_content = "얼굴은 피범벅이었지만 눈빛은 살아있었다고 폴룩스 언니가 그랬어.",
  ui_story_5033_50330702_61_dialog_content = "그때 네코야시키 오빠는 상처가 다 낫고 나서 여길 떠났대.",
  ui_story_5033_50330702_62_dialog_content = "그 뒤로는 여기 돌아올 때마다 먹을 거랑 생필품을 잔뜩 갖다주고 있어.",
  ui_story_5033_50330702_63_dialog_content = "후후! 네코야시키는 우리의 안정적인 사탕 공급자야!",
  ui_story_5033_50330702_64_dialog_content = "그러니까 무슨 일이 있어도 나한테 꼭 사탕을 먹게 해 준다구!",
  ui_story_5033_50330702_65_dialog_content = "그래, 알겠어. 결론은 사탕 먹고 싶다는 거지? 가져가.",
  ui_story_5033_50330702_66_dialog_content = "와아! 신난다~",
  ui_story_5033_50330702_67_dialog_content = "어, 잠깐만... 사탕 더 먹고 싶으면 더 줄 수 있는데, 폴룩스 씨랑 카스타 얘기도 좀 해 줘.",
  ui_story_5033_50330702_68_dialog_content = "이제부턴 협력 파트너니까 좀 알아두는 편이 좋을 것 같거든.",
  ui_story_5033_50330702_69_dialog_content = "그래, 좋아. 라탄이 얼마든지 말해 줄 거야.",
  ui_story_5033_50330702_70_dialog_content = "음, 그럼 폴룩스 언니에 대한 신비한 전설부터 말해줄게...",
  ui_story_5033_50330702_71_dialog_content = "<color=#e8d9bb>탕! 탕탕탕!</color>",
  ui_story_5033_50330702_72_dialog_content = "총소리? 밖에서 싸움이 났나?!",
  ui_story_5033_50330702_73_dialog_content = "당신이 결백하다는 충분한 증거를 제시하지 못한다면...\n난 당신을 제1용의자로 지목할 수밖에 없어.",
  ui_story_5033_50330702_74_dialog_content = "칼 내려놔! 총 맞고 싶어?",
  ui_story_5033_50330702_75_dialog_content = "<color=#e8d9bb>타앙!</color>",
  ui_story_5033_50330702_76_dialog_content = "자기는 벌써 총을 쏴 놓고 나한텐 칼을 내려놓으라는 거냐?!",
  ui_story_5033_50330702_77_dialog_content = "다시 한번 말하는데, 칼 내려놔. 방금 건 경고 사격이었어!",
  ui_story_5033_50330702_78_dialog_content = "너 정말 폴룩스를 범인이라고 생각하는 거야?",
  ui_story_5033_50330702_79_dialog_content = "마틸다 수녀님은 우리한테 그 누구와도 맞바꿀 수 없는 존재야.\n그런 수녀님을 우리가 죽였겠어?",
  ui_story_5033_50330702_80_dialog_content = "그럴 가능성도 있겠지... 어차피 증거 없는 말뿐 아닌가?\n난 당신들과 마틸다 수녀 사이가 실제로 어땠는지 전혀 모르니까.",
  ui_story_5033_50330702_81_dialog_content = "받아들이긴 힘들다는 건 알고 있어.\n하지만 이성적인 판단으론 당신을 용의선상에 넣을 수밖에 없어.",
  ui_story_5033_50330702_82_dialog_content = "그러니 반드시 자신이 결백하다는 증거를 제시해.",
  ui_story_5033_50330702_83_dialog_content = "무슨 일이야? 왜 서로 싸우고 있어?",
  ui_story_5033_50330702_84_dialog_content = "PlayerName, 방금 폴룩스가 자기도 연쇄 살인 사건과 같은 수법으로\n사람을 죽일 수 있다고 시인했다.",
  ui_story_5033_50330702_85_dialog_content = "뭐?!",
  ui_story_5033_50330702_86_dialog_content = "그...그럴 리 없어. 폴룩스 언니는 사람을 죽이지 않아.",
  ui_story_5033_50330702_87_dialog_content = "전부 멈춰!",
  ui_story_5033_50330702_88_dialog_content = "아이들 앞에서 싸울 생각은 아니겠지?",
  ui_story_5033_50330702_89_dialog_content = "저 사람이 폴룩스를 잡아간대?",
  ui_story_5033_50330702_90_dialog_content = "우, 우리가 잡혀가지 않게 해 줄게! 우리가 지켜줄 거야!",
  ui_story_5033_50330801_1_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_5033_50330801_2_dialog_content = "<color=#e8d9bb>유포리아, 술집</color>",
  ui_story_5033_50330801_3_dialog_content = "그거 들었어? 「레이븐즈 블러드」가 움브라톤 쪽 인간이랑 뭘 꾸미고 있다던데.",
  ui_story_5033_50330801_4_dialog_content = "대체 뭘 할 생각이지?",
  ui_story_5033_50330801_5_dialog_content = "보나 마나 떳떳하지 못한 짓이겠지.\n움브라톤이 유포리아까지 마수를 뻗으려는 것 같은데.",
  ui_story_5033_50330801_6_dialog_content = "언제는 여기가 무슨 움브라톤의 쓰레기장인 것처럼 별걸 다 여기로 갖다 버리더니.",
  ui_story_5033_50330801_7_dialog_content = "그걸로도 성에 안 차는 모양이지.",
  ui_story_5033_50330801_8_dialog_content = "이젠 유포리아에까지 눈독을 들이다니.",
  ui_story_5033_50330801_9_dialog_content = "차마 움브라톤에는 못 만드는 도박장이나 군수공장 같은 건 죄다 여기 짓고 있잖아.",
  ui_story_5033_50330801_10_dialog_content = "그럼 예전이랑 똑같은 거 아냐?",
  ui_story_5033_50330801_11_dialog_content = "이번엔 달라. 예전엔 그런 사업들은 다 유포리아 관할이었어.",
  ui_story_5033_50330801_12_dialog_content = "하지만 이젠 움브라톤이 여길 장악하려 한다고.",
  ui_story_5033_50330801_13_dialog_content = "아니지, 예전엔 그런 사업들은 유포리아가 아니라 「보스」 관할이었잖아.",
  ui_story_5033_50330801_14_dialog_content = "유포리아가 얼마나 힘들게 보스 손에서 벗어났는데,\n그렇게 누구 밑에서 휘둘리는 삶을 다시 살고 싶진 않다고...",
  ui_story_5033_50330801_15_dialog_content = "지금은 돈은 좀 적게 벌지만, 하루 종일 겁먹고 살 필요도 없으니까.",
  ui_story_5033_50330801_16_dialog_content = "그래. 이제 유포리아는 우리 거라고. 모든 클랜이 함께 나누는 게 바로 규칙이야.",
  ui_story_5033_50330801_17_dialog_content = "자, 자, 비켜! 우리 대장이 앉게 어서들 비켜!",
  ui_story_5033_50330801_18_dialog_content = "으윽, 내 허리...",
  ui_story_5033_50330801_19_dialog_content = "너희 클랜 애들이 「레이븐즈 블러드」에 당했다고 들었는데, 진짜야?",
  ui_story_5033_50330801_20_dialog_content = "저리 안 꺼져? 우리 이 꼴이 뻔히 보이면서 진짜냐고 묻는 거냐?",
  ui_story_5033_50330801_21_dialog_content = "「레이븐즈 블러드」가 움브라톤 놈들을 감싸려고 우리와의 충돌도\n마다하지 않다니, 대체 이유가 뭐지?",
  ui_story_5033_50330801_22_dialog_content = "그 움브라톤 놈들이 그 여자들이랑 무슨 관계인지 내가 어떻게 알아?",
  ui_story_5033_50330801_23_dialog_content = "그건 내가 안다. 우리 쪽 애들이 방금 소식을 입수했거든.",
  ui_story_5033_50330801_24_dialog_content = "움브라톤 쪽에 연쇄 살인 사건이 일어났는데,\n범인이 유포리아 사람이라 여기에 체포하러 왔다더군.",
  ui_story_5033_50330801_25_dialog_content = "「레이븐즈 블러드」 녀석들, 딱 봐도 좋은 기회다 싶으니까\n옆에 딱 붙어서 아부 좀 떨려는 거겠지.",
  ui_story_5033_50330801_26_dialog_content = "사건을 조사하러 왔는데 어떻게 「레이븐즈 블러드」랑 손잡을 수가 있는 거지?",
  ui_story_5033_50330801_27_dialog_content = "범인 잡으러 온 게 아니라 그걸 구실로 무슨 수작을 부릴지 누가 알겠어?",
  ui_story_5033_50330801_28_dialog_content = "구스타프, 당신도 뭐라 말 좀 해 봐. 당신은 이 유포리아의 정보통이잖아.",
  ui_story_5033_50330801_29_dialog_content = "허허, 뭘 듣고 싶나?",
  ui_story_5033_50330801_30_dialog_content = "우리가 어떻게 해야 될 것 같아?",
  ui_story_5033_50330801_31_dialog_content = "그렇게 뭉뚱그려서 물어보면 나도 딱히 뭐라고 대답해야 좋을지 모르겠군.",
  ui_story_5033_50330801_32_dialog_content = "너희 클랜에 대해서 묻는 거냐? 아니면 유포리아가 어떻게 해야 할지 묻는 거냐?",
  ui_story_5033_50330801_33_dialog_content = "당연히 둘 다지!",
  ui_story_5033_50330801_34_dialog_content = "내 입장에선 당연히 우리 클랜의 이익이 가장 중요하지.\n하지만 우린 전부 유포리아 사람이잖아.",
  ui_story_5033_50330801_35_dialog_content = "유포리아에선 클랜의 힘이 전부다.",
  ui_story_5033_50330801_36_dialog_content = "너흰 수십 명이 있었는데도 고작 두 명인 「레이븐즈 블러드」에 당했다.\n그러니 다른 사람들한테 너희 클랜은...",
  ui_story_5033_50330801_37_dialog_content = "내가 이건 제대로 얘길 해야겠어!",
  ui_story_5033_50330801_38_dialog_content = "그때 우리 애들은 다 모인 것도 아니었고, 무기도 안 가지고 있었어.\n게다가 암귀들까지 끼어드는 바람에 걔들한테 기회를 내준 것뿐이라고.",
  ui_story_5033_50330801_39_dialog_content = "그렇다면 유포리아의 규칙대로 해야겠지.",
  ui_story_5033_50330801_40_dialog_content = "너희 클랜의 명예를 되찾고 싶다면 정식으로 클랜 결투를 신청하고,\n거기서 승리를 거두면 된다.",
  ui_story_5033_50330801_41_dialog_content = "혹시 그럴 배짱이 없다면...",
  ui_story_5033_50330801_42_dialog_content = "다, 당연히 결투는 해야지... 일단 다친 게 좀 낫고 나면 애들을 끌고 가서\n레이븐즈 블러드 녀석들의 소굴을 박살 내 주마!",
  ui_story_5033_50330801_43_dialog_content = "대장, 우리가 직접 손 쓸 필요는 없습니다.",
  ui_story_5033_50330801_44_dialog_content = "「레이븐즈 블러드」가 유포리아에 움브라톤 녀석들을 끌어들였으니,\n걔들이 먼저 규칙을 어긴 거잖아요.",
  ui_story_5033_50330801_45_dialog_content = "맞아, 전부터 계속 「레이븐즈 블러드」가 눈에 거슬렸어.",
  ui_story_5033_50330801_46_dialog_content = "저번엔 우리 클랜의 사업까지 망쳐 버렸다고.",
  ui_story_5033_50330801_47_dialog_content = "온종일 교회 주변에서 수상쩍게 굴면서 아무도 그 근처에 못 오게 하고 말이지.",
  ui_story_5033_50330801_48_dialog_content = "너 바보냐? 거긴 자기 클랜 영역인데 네가 못 오게 하는 게 정상이지.",
  ui_story_5033_50330801_49_dialog_content = "아, 아무튼! 걔네 둘 다 거슬린다고!",
  ui_story_5033_50330801_50_dialog_content = "말들 한번 잘했다!",
  ui_story_5033_50330801_51_dialog_content = "구스타프, 지금 당장 나머지 클랜한테 같이 힘을 합쳐서\n「레이븐즈 블러드」를 쓸어버릴 때가 됐다고 전해.",
  ui_story_5033_50330801_52_dialog_content = "자, 자, 다들 진정 좀 해라.",
  ui_story_5033_50330801_53_dialog_content = "다들 유포리아가 발전하려면 「레이븐즈 블러드」를 없애야 한다고 생각하는 건 나도 안다.",
  ui_story_5033_50330801_54_dialog_content = "하지만 너무 성급하게 굴면 안 되지.",
  ui_story_5033_50330801_55_dialog_content = "지금 「레이븐즈 블러드」는 이미 움브라톤과 협력 중인 상태인데,\n우리가 경솔하게 습격이라도 해 봐. 그럼 움브라톤 쪽까지 움직이기 시작할 거다.",
  ui_story_5033_50330801_56_dialog_content = "누가 겁먹을 줄 알고?! 유포리아 사람들이 움브라톤에 머리 숙이는 일은 절대로 없어!",
  ui_story_5033_50330801_57_dialog_content = "겁을 먹냐 안 먹냐 문제가 아니라니까.",
  ui_story_5033_50330801_58_dialog_content = "우린 아직 움브라톤 쪽의 의도를 모르는 상태다.\n그러니까 일단 상황을 제대로 파악하고 나서 결정하자는 거다.",
  ui_story_5033_50331001_1_dialog_content = "얘들아, 걱정하지 마. 서로 오해가 조금 있었나 봐.",
  ui_story_5033_50331001_2_dialog_content = "카스타, 일단 총 내려놔. 그리고 앞으로 다시는 애들 앞에서 멋대로 총 쏘지 말고.",
  ui_story_5033_50331001_3_dialog_content = "미안해, 폴룩스. 아깐 너무 조급했어. 애들이 나올 줄은 몰랐어.",
  ui_story_5033_50331001_4_dialog_content = "와타리 씨, 난 이 아이들이 믿고 따르는 사람이 연쇄 살인범일 리는 없다고 생각해!",
  ui_story_5033_50331001_5_dialog_content = "칼은 이미 집어넣었다... 해명을 들어보도록 하지.\n방금 그건 내 의도는 아니었어. 사과하지.",
  ui_story_5033_50331001_6_dialog_content = "그, 그럼 이제 괜찮은 거야?",
  ui_story_5033_50331001_7_dialog_content = "이제 다 괜찮아. 다들 교회 안으로 들어가자. 밖에 서 있으면 감기 걸려.",
  ui_story_5033_50331001_8_dialog_content = "맞는 말이다. 곧 비가 내릴 테니 아이들은 교회 안으로 들어가는 게 좋아.",
  ui_story_5033_50331001_9_dialog_content = "라탄, 애들 데리고 안으로 들어가렴.",
  ui_story_5033_50331001_10_dialog_content = "응, 알겠어...",
  ui_story_5033_50331001_11_dialog_content = "그럼 이제 해명해 보실까.\n어째서 당신도 그런 수준급의 살인 기술을 익히게 된 거지?",
  ui_story_5033_50331001_12_dialog_content = "그 기술을 다룰 줄은 알지만, 내 실력은 수준급까진 아니야.",
  ui_story_5033_50331001_13_dialog_content = "그 기술을 쓰려면 일단 특수한 단도가 있어야 해.",
  ui_story_5033_50331001_14_dialog_content = "하지만 난 다시는 그 단도를 사용하지 않겠다고 14년 전에 맹세했어.",
  ui_story_5033_50331001_15_dialog_content = "그건 나랑 네코야시키가 보증할 수 있어.",
  ui_story_5033_50331001_16_dialog_content = "미안하군. 두 사람의 증언은 채택할 수 없다.",
  ui_story_5033_50331001_17_dialog_content = "폴룩스, 그 정도의 설명으로 내가 어떻게 당신을 믿을 수 있지?",
  ui_story_5033_50331001_18_dialog_content = "난 그저 내가 아는 걸 말해주는 수밖에 없어... 날 신뢰할지 말지는 당신 선택이야.",
  ui_story_5033_50331001_19_dialog_content = "좋아, 그럼 그 기술을 어떻게 배운 거지?",
  ui_story_5033_50331001_20_dialog_content = "유포리아의 옛 주인한테 배웠어.\n다들 그 사람을 「<color=#FFB400>보스</color>」라고 불렀지.",
  ui_story_5033_50331001_21_dialog_content = "그 사람은 한때 자신의 「<color=#FFB400>조직</color>」을 통해 모든 유포리아 사람들과\n이곳의 모든 사업을 통제했어.",
  ui_story_5033_50331001_22_dialog_content = "그땐 모두가 「조직」의 「사신」을 두려워했어.",
  ui_story_5033_50331001_23_dialog_content = "그리고 난 한때 그 「조직」의 일원이었고, 강제로 「사신」의 살인 기술을 배워야만 했어.",
  ui_story_5033_50331001_24_dialog_content = "그 보스라는 사람은 대체 누구지?",
  ui_story_5033_50331001_25_dialog_content = "그 사람은 항상 빨갛고 높은 등받이가 달린 소파에 우릴 등진 채 앉아 있었어.",
  ui_story_5033_50331001_26_dialog_content = "그 사람의 이름을 아는 사람은 아무도 없었지. 어떻게 생겼는지도 말이야.",
  ui_story_5033_50331001_27_dialog_content = "그럼 당신은 왜 그 조직에 들어가게 된 거지?",
  ui_story_5033_50331001_28_dialog_content = "사람이 살아남기 위해 몸부림칠 땐, 자기가 지금 한 선택이 나중에 어떤 결과를\n가져올지 고려할 여유가 없거든.",
  ui_story_5033_50331001_29_dialog_content = "그래서 먹을 걱정, 입을 걱정 안 해도 되고, 혼자서 쓸 수 있는 침대까지 준다는 얘길 듣곤...",
  ui_story_5033_50331001_30_dialog_content = "바로 그 사람이 원하는 대로 하기로 했어.",
  ui_story_5033_50331001_31_dialog_content = "그리고 나중에야 사람들이 다 그 사람을 「보스」라고 부른다는 걸 알았지.",
  ui_story_5033_50331001_32_dialog_content = "그러면 진짜 범인도 당신처럼 그 「조직」의 일원일 거란 말인가?",
  ui_story_5033_50331001_33_dialog_content = "하지만 「조직」은 10년 전에 완전히 몰락했어.",
  ui_story_5033_50331001_34_dialog_content = "살아남은 건 나뿐이라고 생각해 왔고.",
  ui_story_5033_50331001_35_dialog_content = "당신이 모를 뿐, 당신처럼 살아남은 사람이 더 있을지도 모르지.",
  ui_story_5033_50331001_36_dialog_content = "부검 기록을 보고 혹시 떠오르는 사람은 없나?",
  ui_story_5033_50331001_37_dialog_content = "떠오르는 사람이 확실히 하나 있긴 해...",
  ui_story_5033_50331001_38_dialog_content = "그 살인 기술을 이렇게 능숙하게 다룰 수 있는 사람은 그 애 하나뿐이야.\n하지만 그 애는 이미 죽었는걸.",
  ui_story_5033_50331001_39_dialog_content = "어떻게 확신하지?",
  ui_story_5033_50331001_40_dialog_content = "내가 죽였거든... 내 가장 친한 친구였던 아이를.",
  ui_story_5033_50331001_41_dialog_content = "<color=#e8d9bb>14년 전</color>",
  ui_story_5033_50331001_42_dialog_content = "이게... 내 침대?",
  ui_story_5033_50331001_43_dialog_content = "아...",
  ui_story_5033_50331001_44_dialog_content = "으앗! 누구야? 왜 아무 소리도 안 내고 거기 숨어 있는데?",
  ui_story_5033_50331001_45_dialog_content = "아, 오해하지 마! 일부러 소리 안 낸 거 아니고... 널 놀라게 하려던 것도 아냐.",
  ui_story_5033_50331001_46_dialog_content = "그냥 네가 방금 베개를 쓰다듬는 모습이 너무 귀여워서, 보다가 조금 정신이 팔렸던 거야.",
  ui_story_5033_50331001_47_dialog_content = "너... 지금 나 놀리는 거지?!",
  ui_story_5033_50331001_48_dialog_content = "...됐어, 놀리고 싶으면 놀려.",
  ui_story_5033_50331001_49_dialog_content = "솔직히 베개는 상점 진열장 안에 것밖에 본 적 없어.\n실제로 만져 보니까 진짜 부드럽네...",
  ui_story_5033_50331001_50_dialog_content = "그럼 네가 내 새 룸메이트구나?",
  ui_story_5033_50331001_51_dialog_content = "음, 계속 서 있었더니 좀 힘드네. 네 침대에 앉아서 너랑 얘기해도 될까?",
  ui_story_5033_50331001_52_dialog_content = "응! 당연하지! 앉아!",
  ui_story_5033_50331001_53_dialog_content = "난 안타레스라고 해. 네 이름은 뭐니?",
  ui_story_5033_50331001_54_dialog_content = "원래 난 이름이 없었어. 지금 쓰고 있는 이름은 내가 유포리아에서\n떠돌이 생활을 할 때 만난 수녀님이 지어 주신 거야.",
  ui_story_5033_50331001_55_dialog_content = "그럼 넌 왜 여기 왔어? 여기가 어떤 곳인진 알아?",
  ui_story_5033_50331001_56_dialog_content = "누가 나한테 여기다 신청하면 경쟁에 참가할 수 있다고 그랬거든.",
  ui_story_5033_50331001_57_dialog_content = "경쟁에서 선발되면 먹을 거, 입을 거 걱정 안 해도 되고, 내 침대도 준다고 했어!",
  ui_story_5033_50331001_58_dialog_content = "아무튼 참가했는데 뽑혔고, 그리고 오늘 널 만나게 된 거야!",
  ui_story_5033_50331001_59_dialog_content = "그럼 넌 여기가 뭐 하는 곳인지 모르는 거구나...",
  ui_story_5033_50331001_60_dialog_content = "응... 어라, 안타레스, 괜찮아? 손이 엄청 차갑잖아.",
  ui_story_5033_50331001_61_dialog_content = "창문 좀 닫아야겠어!",
  ui_story_5033_50331001_62_dialog_content = "나, 난 괜찮아.",
  ui_story_5033_50331001_63_dialog_content = "그래? 알겠어. 혹시 추우면 나한테 말해줘.",
  ui_story_5033_50331001_64_dialog_content = "그나저나 넌 여기서 얼마나 있었어? 그리고 여긴 뭐 하는 곳이야?",
  ui_story_5033_50331001_65_dialog_content = "음, 난 기억이 날 때부터 계속 여기 있었어. 그리고 여긴...",
  ui_story_5033_50331001_66_dialog_content = "유포리아에서 용병을 육성하는 지하 훈련 캠프야.",
  ui_story_5033_50331001_67_dialog_content = "폴룩스, 우리 진짜 진지하게 얘기 좀 해.",
  ui_story_5033_50331001_68_dialog_content = "으... 안타레스, 네가 무슨 말 하려는지는 알아. 다음부턴 조심할게! 진짜야!",
  ui_story_5033_50331001_69_dialog_content = "매번 말로만 그러고 제대로 들어 준 적은 단 한 번도 없잖아!",
  ui_story_5033_50331001_70_dialog_content = "임무만 마치고 돌아오면, 저번 상처도 안 나았는데 또 상처가 나 있고!",
  ui_story_5033_50331001_71_dialog_content = "내가 네 붕대를 갈아 줄 때마다, 그 상처들 보면서 얼마나 가슴 아픈지 알기나 해?",
  ui_story_5033_50331001_72_dialog_content = "너한테 내 감정 따윈 하나도 중요하지 않은 거지?",
  ui_story_5033_50331001_73_dialog_content = "안타레스, 정말 미안해... 근데 나 진짜 모르겠어. 대체 내가 어디가 부족한 걸까?",
  ui_story_5033_50331001_74_dialog_content = "내가 여기 온 지 얼마 안 됐을 때부터 넌 임무를 맡아서 나갔어.\n그건 이해해. 그땐 우리 실력 차이가 많이 났으니까.",
  ui_story_5033_50331001_75_dialog_content = "그래서 난 밤낮으로 연습했고, 나보다 훨씬 윗급인 용병들을 훈련시킬 수도 있게 됐어.",
  ui_story_5033_50331001_76_dialog_content = "그런데 아직 저 사람들 눈엔 내가 너보다, 심지어는 나보다 1, 2년 늦게 들어온\n신참들보다 뒤처지게 보이는 것 같아.",
  ui_story_5033_50331001_77_dialog_content = "나도 너처럼 뛰어난 용병이 되고 싶단 말이야!",
  ui_story_5033_50331001_78_dialog_content = "그런 게 아니야, 폴룩스. 내 말 좀 들어 봐.",
  ui_story_5033_50331001_79_dialog_content = "다들 네가 어떤 것들을 이뤄냈는지 다 알아.\n그래서 우리 둘을 「쌍둥이별」이라고 부르는 거잖아?",
  ui_story_5033_50331001_80_dialog_content = "넌 이미 충분히 대단해. 그러니까 이제 더는 심하게 훈련할 필요 없어, 폴룩스...",
  ui_story_5033_50331001_81_dialog_content = "그럼 왜 난 여기 이렇게 오랫동안 있었는데 왜 나한테 임무를 맡기지 않는 거야?",
  ui_story_5033_50331001_82_dialog_content = "...미안해, 안타레스. 네가 날 생각해서 그렇게 말해 주는 건 알아.\n그래도 난 자꾸 그 점이 마음에 걸려. 지금도 마찬가지고.",
  ui_story_5033_50331001_83_dialog_content = "나한테 사과 안 해도 돼. 너한테 상처받은 사람은 내가 아니라 너 자신이잖아.",
  ui_story_5033_50331001_84_dialog_content = "만약 다시 시작할 수 있다면, 난 스스로 내 인생을 선택해 보고 싶어.",
  ui_story_5033_50331001_85_dialog_content = "악몽에 놀라 깨어나지 않아도 되고, 평생 양심의 가책을 느끼지 않아도 되고...",
  ui_story_5033_50331001_86_dialog_content = "영원히... 「임무」 따윈 할 필요 없는 그런 인생 말이야.",
  ui_story_5033_50331001_87_dialog_content = "하지만 안타레스, 난 임무를 수행하고 싶어.",
  ui_story_5033_50331001_88_dialog_content = "너랑 같이 전장에 서서, 네가 안심하고 등을 맡길 수 있게 해 주고 싶어.",
  ui_story_5033_50331001_89_dialog_content = "그리고 내가 처음으로 임무를 수행할 수 있게 된 것을 안 후...",
  ui_story_5033_50331001_90_dialog_content = "뭐 하려고 이러는 거야? 괜히 궁금하게.",
  ui_story_5033_50331001_91_dialog_content = "아이, 참. 아무튼 눈부터 감아! 실눈도 뜨지 마!",
  ui_story_5033_50331001_92_dialog_content = "음, 알았어. 눈 감았어.",
  ui_story_5033_50331001_93_dialog_content = "됐어! 이제 눈 떠도 돼!",
  ui_story_5033_50331001_94_dialog_content = "이건... <color=#FFB400>브로치</color>잖아?",
  ui_story_5033_50331001_94X1_dialog_content = "응, 가게에서 그러는데, 이 꽃은 수국이래. 너한테 잘 어울릴 것 같았어.",
  ui_story_5033_50331001_95_dialog_content = "헤헤, 아직은 고정 수당밖에 못 받아서 이것밖에 못 샀어.",
  ui_story_5033_50331001_96_dialog_content = "임무를 수행하고 나서 급여를 받으면, 너한테 더 잘 어울리는 더 좋은 걸 선물해 줄게!",
  ui_story_5033_50331001_97_dialog_content = "임무를 수행한다고?",
  ui_story_5033_50331001_98_dialog_content = "응! 사실 며칠 전에 「보스」를 만났는데, 이제 곧 나한테 임무를 하나 맡길 거라고 했어!",
  ui_story_5033_50331001_99_dialog_content = "그래서 이건 내 바람이 이루어진 걸 기념하는 선물이야.\n항상 내 곁에 있어 줘서 고마워.",
  ui_story_5033_50331001_100_dialog_content = "다음 선물론 뭘 주면 좋을까?",
  ui_story_5033_50331001_101_dialog_content = "......",
  ui_story_5033_50331001_102_dialog_content = "안타레스? 왜 그래? 선물이 마음에 안 들어?",
  ui_story_5033_50331001_103_dialog_content = "아니야. 보라색 꽃잎이 정말 예뻐. 아주 마음에 들어.",
  ui_story_5033_50331001_104_dialog_content = "폴룩스...",
  ui_story_5033_50331001_105_dialog_content = "왜 그래?",
  ui_story_5033_50331001_106_dialog_content = "나랑 친구가 돼 줘서 고마워. 너랑 같이 지내면서 난 정말 너무 행복했어.",
  ui_story_5033_50331001_107_dialog_content = "후후, 역시 닭살 돋는 말을 안 하면 안타레스가 아니지.",
  ui_story_5033_50331001_108_dialog_content = "근데 나도 그래.",
  ui_story_5033_50331001_109_dialog_content = "나랑 친구가 돼 줘서 고마워, 안타레스.",
  ui_story_5033_50331001_110_dialog_content = "그러나 그 임무는",
  ui_story_5033_50331001_111_dialog_content = "링에 올라 가장 소중한 친구와 싸워야 하는 것이었다...",
  ui_story_5033_50331001_112_dialog_content = "왜... 어째서...",
  ui_story_5033_50331001_113_dialog_content = "왜 내 상대가 너인 거야....?",
  ui_story_5033_50331001_114_dialog_content = "하나는 실전을 겪으며 성장한 전투 병기.",
  ui_story_5033_50331001_115_dialog_content = "다른 하나는 훈련 캠프에서 심혈을 기울여 육성한 천재 신인.",
  ui_story_5033_50331001_116_dialog_content = "「쌍둥이별」이라고 불리는 두 사람이지만,\n오늘은 단 한 사람만 이 링에서 살아서 돌아갈 수 있습니다.",
  ui_story_5033_50331001_117_dialog_content = "유포리아의 과거, 그리고 미래에 이보다 더 흥미진진하고 멋진 대결이 또 있겠습니까?",
  ui_story_5033_50331001_118_dialog_content = "안타레스, 너...",
  ui_story_5033_50331001_119_dialog_content = "칼 들어. 그리고 내 쪽으로 겨눠.",
  ui_story_5033_50331001_120_dialog_content = "네가 계속 기대하던 임무잖아?",
  ui_story_5033_50331001_121_dialog_content = "네가 임무를 위해 오랫동안 단련해 왔다는 거 다 알아.",
  ui_story_5033_50331001_122_dialog_content = "하지만 난...",
  ui_story_5033_50331001_123_dialog_content = "뭘 망설여?",
  ui_story_5033_50331001_124_dialog_content = "이게 실제 전장이었으면 넌 벌써 열 번은 죽었어.",
  ui_story_5033_50331001_125_dialog_content = "내가 어떻게 널 해칠 수가 있냐고...",
  ui_story_5033_50331001_126_dialog_content = "그럼 네가 오늘 이 무대에 올라오게 된 게 전부 나 때문이라면?",
  ui_story_5033_50331001_127_dialog_content = "그, 그럴 리가 없잖아!",
  ui_story_5033_50331001_128_dialog_content = "대체 왜 우리가 서로 죽여야 하는 건데? 지금 상황이 이상하지도 않아?",
  ui_story_5033_50331001_129_dialog_content = "이상하다고? 유포리아에는 네가 상상도 못 할 일들이 수없이 벌어지고 있어.",
  ui_story_5033_50331001_130_dialog_content = "내가 그렇게... 몇 번이나 말리고 또 말렸는데.",
  ui_story_5033_50331001_131_dialog_content = "어쨌든 난 봐주지 않을 거야.",
  ui_story_5033_50331001_132_dialog_content = "날 공격할 거야...?",
  ui_story_5033_50331001_133_dialog_content = "그래. 난 어렸을 때부터 전장에 내던져졌어. 그런 내가 가장 처음 배운 건...",
  ui_story_5033_50331001_134_dialog_content = "누굴 상대하든 절대 봐주지 말아야 한다는 거야.",
  ui_story_5033_50331001_135_dialog_content = "이러지 마... <size=45>안타레스! 난 이러기 싫어!</size>",
  ui_story_5033_50331001_136_dialog_content = "<size=45>가만히 있으면, 넌 죽어!</size>",
  ui_story_5033_50331001_137_dialog_content = "내가 정신을 차렸을 땐",
  ui_story_5033_50331001_138_dialog_content = "돌이키기엔 이미 너무 늦어 버렸다...",
  ui_story_5033_50331001_139_dialog_content = "크윽...!",
  ui_story_5033_50331001_140_dialog_content = "내, 내가... 내가 무슨 짓을...",
  ui_story_5033_50331001_141_dialog_content = "안타레스... 왜 안 피했어?!",
  ui_story_5033_50331001_142_dialog_content = "<anim type=Shake>고...고마워... 폴룩스...</anim>",
  ui_story_5033_50331001_143_dialog_content = "안타레스! 싫어! 죽지 마... 미안해... 내가 미안해...",
  ui_story_5033_50331001_144_dialog_content = "왜... 안 피했어...? 왜?",
  ui_story_5033_50331001_145_dialog_content = "<anim type=Shake>이렇게 하면... 해방될 수 있으니까...</anim>",
  ui_story_5033_50331001_146_dialog_content = "<anim type=Shake>자유롭게...</anim>",
  ui_story_5033_50331001_147_dialog_content = "안타레스는 내가 죽였어... 이 세상에 단 하나밖에 없는 내 친구를 내 손으로 죽인 거야.",
  ui_story_5033_50331001_148_dialog_content = "내 손에 있던 단도가 조금씩 안타레스의 가슴을 파고들던 그 순간에야 난 깨달았지.",
  ui_story_5033_50331001_149_dialog_content = "내가 그토록 바라던 일이 그렇게나 끔찍한 짓이었다는 걸 말이야.",
  ui_story_5033_50331001_150_dialog_content = "두 번 다시 칼을 쓰지 않는 이유가 그래서였군요...",
  ui_story_5033_50331001_151_dialog_content = "맞아. 계속 그날의 일이 머릿속에서 맴돌아서,\n꼭 다시 그 링 위로 올라가게 된 것만 같거든.",
  ui_story_5033_50331001_152_dialog_content = "그 싸움이 끝나고 나서 난 정신을 잃고 일주일 동안 고열에 시달렸어.",
  ui_story_5033_50331001_153_dialog_content = "다시 눈을 떴을 땐, 그 방엔 나 한 사람밖에 없었지.",
  ui_story_5033_50331001_154_dialog_content = "안타레스의 옷, 노트... 그 아이가 지내며 방 곳곳에 남겼던 흔적들이 모조리 사라져 있었어.",
  ui_story_5033_50331001_155_dialog_content = "마치 그 애가 원래부터 이 세상에 존재하지 않았던 것만큼 깔끔하게 말이야.",
  ui_story_5033_50331001_156_dialog_content = "그리고 난 빠르게 그 방에서 옮겨 나왔고,\n한 달도 안 되는 사이 그 방은 두 주인을 떠나보내게 됐어.",
  ui_story_5033_50331001_157_dialog_content = "폴룩스 씨가 그 「조직」을 떠난 건가요?",
  ui_story_5033_50331001_158_dialog_content = "아니, 떠났다기보단 버려진 거야.",
  ui_story_5033_50331001_159_dialog_content = "그날 이후론 싸우는 걸 두려워하게 됐거든. 칼조차 손에 못 쥐게 되었으니까.",
  ui_story_5033_50331001_160_dialog_content = "용병이 전투 능력을 잃었다는 건, 가치를 완전히 잃었다는 뜻이나 다름없어.",
  ui_story_5033_50331001_161_dialog_content = "그래서 난 당연하다는 듯 팀에서 추방됐고, 지하실에 갇혀 있었어.",
  ui_story_5033_50331001_162_dialog_content = "암귀들이 파도처럼 몰려들어 여길 폐허로 만들어 버릴 때까지.",
  ui_story_5033_50331001_163_dialog_content = "그 외에 다른 정보는 없나?",
  ui_story_5033_50331001_164_dialog_content = "미안, 내가 알고 있는 건 이게 다야...",
  ui_story_5033_50331001_165_dialog_content = "대신 약속할게. 사건의 진상이 밝혀질 때까지, 이번 일의 조사를 끝까지 돕겠어.",
  ui_story_5033_50331001_166_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5033_50331001_167_dialog_content = "잠깐만, 여러 사람들이 이쪽으로 오고 있는 게 느껴져!",
  ui_story_5033_50331001_168_dialog_content = "어떤 사람들이지?",
  ui_story_5033_50331001_169_dialog_content = "나도 몰라. 근데 교회 주변을... 포위하고 있는데?!",
  ui_story_5033_50331101_1_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_5033_50331101_2_dialog_content = "어서들 따라 와! 빨리빨리 움직여!",
  ui_story_5033_50331101_3_dialog_content = "전투를 치러야 할 테니까 다들 무기 잘 챙겨.\n「레이븐즈 블러드」는 만만치 않은 상대라고.",
  ui_story_5033_50331101_4_dialog_content = "다 챙겼어!",
  ui_story_5033_50331101_5_dialog_content = "도착하고 나면 성급하게 굴지 말고, 내가 신호를 보낼 때까지 기다렸다가 쏴. 알겠냐?",
  ui_story_5033_50331101_6_dialog_content = "알겠어!",
  ui_story_5033_50331101_7_dialog_content = "우리 클랜 애들은 다 모였겠지?",
  ui_story_5033_50331101_8_dialog_content = "다 모였습니다. 이번에야말로 「레이븐즈 블러드」를 끝장내 버리죠!",
  ui_story_5033_50331101_9_dialog_content = "하하! 아주 좋아! 내가 이 날이 오길 얼마나 기다렸는지 모르겠군!",
  ui_story_5033_50331101_10_dialog_content = "어, 어라, 잠깐만... 구스타프가 충동적으로 움직이지 말라고 했잖아?",
  ui_story_5033_50331101_11_dialog_content = "<size=45>네가 뭘 알아?!</size>",
  ui_story_5033_50331101_12_dialog_content = "「레이븐즈 블러드」랑 움브라톤이 결탁했단 증거를 잡으려면\n지금이 딱 좋은 기회라고!",
  ui_story_5033_50331101_13_dialog_content = "녀석들이 도망치기라도 하면, 어디 가서 잡을 건데?",
  ui_story_5033_50331101_14_dialog_content = "안 되겠어. 난 구스타프한테 가서 이 사실을 알릴 거야.",
  ui_story_5033_50331101_15_dialog_content = "너 언제부터 구스타프의 개가 된 거냐?",
  ui_story_5033_50331101_16_dialog_content = "성가시게 만들지 말고 어서 썩 꺼져!",
  ui_story_5033_50331101_17_dialog_content = "확실히 교회 쪽을 향해 몰려오고 있어.",
  ui_story_5033_50331101_18_dialog_content = "우리 「레이븐즈 블러드」한테 시비라도 걸러 오는 건가?",
  ui_story_5033_50331101_19_dialog_content = "아니, 이번엔 그 정도로 단순하지 않을 거야.",
  ui_story_5033_50331101_20_dialog_content = "지금까지 이 교회 근처엔 아무도 함부로 다가오지 못했어.",
  ui_story_5033_50331101_21_dialog_content = "하지만 이렇게 한꺼번에 많이 몰려오는 걸 보면,\n이번 일을 벌이려고 여러 클랜이 힘을 합쳤을 수도 있어.",
  ui_story_5033_50331101_22_dialog_content = "그게 하필 왜 지금인데?",
  ui_story_5033_50331101_23_dialog_content = "움브라톤 쪽 사람이 유포리아에 발을 들인 게 무척 불쾌했던 모양이지.",
  ui_story_5033_50331101_24_dialog_content = "우리 때문에 녀석들이 몰려오게 된 건가?",
  ui_story_5033_50331101_25_dialog_content = "미안, 와타리 씨.",
  ui_story_5033_50331101_26_dialog_content = "아무래도 우리 움직임이 이 지역 클랜들을 자극했던 건지, 성가신 일이 생겨 버렸네.",
  ui_story_5033_50331101_27_dialog_content = "우린 일단 현지 클랜의 갈등부터 해결해야 할 것 같아.",
  ui_story_5033_50331101_28_dialog_content = "약자 앞에서나 강한 척하는 겁쟁이들 주제에, 꼴에 자기들끼리 뭉치면\n우릴 이길 수 있을 거라 생각하는 거야?",
  ui_story_5033_50331101_29_dialog_content = "몇 명이 몰려오든 다 쓰러트려 버리면 그만이야!",
  ui_story_5033_50331101_30_dialog_content = "섣불리 행동하면 안 돼. 일을 키워 봐야 우리한텐 좋을 게 없어.",
  ui_story_5033_50331101_31_dialog_content = "카스타, 와타리 씨. 두 사람은 일단 아이들을 데리고 네코야시키 쪽에 피신시켜 줘.",
  ui_story_5033_50331101_32_dialog_content = "녀석들은 「레이븐즈 블러드」와 교회를 노리고 온 거니까,\n난 남아서 녀석들을 여기 붙잡아 두고 있을게.",
  ui_story_5033_50331101_33_dialog_content = "알겠다. 아이들의 안전은 내가 확실히 보장하지.",
  ui_story_5033_50331101_34_dialog_content = "그럼 넌 어쩌려고? 아무리 너라도 혼자서 저 많은 사람을 당해낼 순 없어.",
  ui_story_5033_50331101_35_dialog_content = "최대한 시간을 끌고 있을게. 어서 가서 아이들을 데리고 나와.",
  ui_story_5033_50331101_36_dialog_content = "...알겠어. 꼭 우리가 돌아올 때까지 버텨야 해!",
  ui_story_5033_50331101_37_dialog_content = "나도 돕지. 다친 아이들도 있으니 조심해서 움직여야 할 거다.",
  ui_story_5033_50331101_38_dialog_content = "PlayerName.",
  ui_story_5033_50331101_39_dialog_content = "아? 네!",
  ui_story_5033_50331101_40_dialog_content = "너에 대해 잘 아는 건 아니지만, 너라면 모두가 안전히 피할 수 있는 길을\n찾아내 줄 거라고 믿어.",
  ui_story_5033_50331101_41_dialog_content = "길 안내 역할은 네게 맡겨도 될까?",
  ui_story_5033_50331101_42_dialog_content = "맡겨 주세요!",
  ui_story_5033_50331101_43_dialog_content = "네코야시키는 평소 머무는 그 집에 있을 거야. 기억하니?",
  ui_story_5033_50331101_44_option_content = "기억나요.",
  ui_story_5033_50331101_45_dialog_content = "네코야시키는 상처 모양 그라피티가 있는 집에 있었어요.",
  ui_story_5033_50331101_46_dialog_content = "교회 남쪽의 골목을 지나고, 두 거리를 더 가서 보이는 좁고 긴 골목에 들어가서...",
  ui_story_5033_50331101_47_dialog_content = "다섯인가, 여섯 모퉁이를 돌아가면...",
  ui_story_5033_50331101_48_dialog_content = "여섯 모퉁이가 맞아.",
  ui_story_5033_50331101_49_dialog_content = "아, 그럼 알겠어요. 어떻게 가는지 기억해요.",
  ui_story_5033_50331101_50_dialog_content = "좋아, 혹시 무슨 문제가 생기면 카스타한테 물어보면 돼.\n근데 두 사람은 전투도 맡아야 하니까 힘들 거야.",
  ui_story_5033_50331101_51_dialog_content = "그러니까 도저히 안 되겠으면 라탄한테 물어봐. 어리지만 믿음직스러운 아이거든.",
  ui_story_5033_50331101_52_option_content = "기억이 안 나요...",
  ui_story_5033_50331101_53_dialog_content = "너희가 전에 한 번 가 봤던 집이야. 상처 모양 그라피티가 그려져 있던 거기.",
  ui_story_5033_50331101_54_dialog_content = "빠르게 교회 남쪽 골목을 지나친 다음에, 두 거리를 더 지나야 해.",
  ui_story_5033_50331101_55_dialog_content = "만약 거리에 사람이 있다면 조금 멀리 돌아서,\n벽에 작은 곰돌이 스티커가 붙어 있는 골목을 찾아.",
  ui_story_5033_50331101_56_dialog_content = "그건 아이들이 붙여 놓은 건데, 다들 카스타랑 아는 사이야.",
  ui_story_5033_50331101_57_dialog_content = "카스타랑 와타리 씨는 전투를 맡아야 할 수도 있으니까,\n아이들을 데리고 움직이는 임무는 너한테 맡길게.",
  ui_story_5033_50331101_58_dialog_content = "도착해서 네코야시키한테 상황을 설명해 주면,\n모두를 안전한 곳으로 데려가 줄 거야. 알겠지?",
  ui_story_5033_50331101_59_dialog_content = "알겠어요.",
  ui_story_5033_50331101_60_dialog_content = "좋아, 착한 아이구나.",
  ui_story_5033_50331101_61_option_content = "전 아이가 아닌데요.",
  ui_story_5033_50331101_62_dialog_content = "아무튼 맡겨 주신 길 안내 임무는 반드시 잘 해낼게요.",
  ui_story_5033_50331101_63_dialog_content = "그리고 저도 카스타랑 와타리 씨가 전투하는 데 도움을 줄 수 있으니까,\n아이들한텐 아무 일도 없을 거예요. 안심하세요.",
  ui_story_5033_50331101_64_dialog_content = "정말 다행이야. 역시 내 눈은 틀리지 않았구나...",
  ui_story_5033_50331101_65_dialog_content = "넌 내 생각보다 훨씬 더 어른스럽네.\n나중에 모든 일이 해결되고 나면 네 얘기도 들려줬으면 좋겠어.",
  ui_story_5033_50331101_66_dialog_content = "네, 약속할게요.",
  ui_story_5033_50331101_67_option_content = "「착한 아이」가 될 수 있도록 힘낼게요.",
  ui_story_5033_50331101_68_dialog_content = "저 아이들도 모두 착하니까, 문제없이 피신할 수 있을 거예요.",
  ui_story_5033_50331101_69_dialog_content = "그러니까 너무 걱정하지 마세요. 아이들을 안전한 곳에 데려다주고 나면\n반드시 두 사람이랑 같이 돌아올게요.",
  ui_story_5033_50331101_70_dialog_content = "그래, 그 말을 들으니까 마음이 많이 편해졌어.",
  ui_story_5033_50331101_71_dialog_content = "폴룩스 씨, 저희가 도우러 올 때까지 꼭 버텨야 해요!",
  ui_story_5033_50331101_72_dialog_content = "응, 알겠어. 고마워.",
  ui_story_5033_50331101_73_dialog_content = "카스타랑 와타리 씨가 아이들을 데리고 나왔어. 어서 출발해.",
  ui_story_5033_50331101_74_dialog_content = "폴룩스 누나, 카스타 누나가 우리한테 안전한 곳으로 가야 된대.\n누나는? 폴룩스 누나는 우리랑 같이 안 가?",
  ui_story_5033_50331101_75_dialog_content = "폴룩스... 폴룩스 누나... 같이 가자!",
  ui_story_5033_50331101_76_dialog_content = "얘들아, 자꾸 폴룩스 언니한테 떼쓰지 마. 아까 잘 따라오기로 약속했잖아.",
  ui_story_5033_50331101_77_dialog_content = "그치만...",
  ui_story_5033_50331101_78_dialog_content = "얘들아, 내 걱정은 안 해도 돼.",
  ui_story_5033_50331101_79_dialog_content = "난 꼭 해결해야 할 일들이 있어서 여기 남는 거란다.",
  ui_story_5033_50331101_80_dialog_content = "이제부터 너흰 안전한 곳으로 가야 해. 최대한 여기서 멀리 떨어지렴.",
  ui_story_5033_50331101_81_dialog_content = "훌쩍... 근데 교회 밖에는 암귀들이 엄청 많아서... 폴룩스 언니가 같이 안 가면...",
  ui_story_5033_50331101_82_dialog_content = "무서워할 거 없어. 카스타랑 와타리 의사 선생님이 너희 모두를 지켜 줄 거야.",
  ui_story_5033_50331101_83_dialog_content = "그리고 PlayerName하고 네코야시키도 있으니 안심하렴.",
  ui_story_5033_50331101_84_dialog_content = "그럼 우린 언제 교회로 돌아올 수 있어?",
  ui_story_5033_50331101_85_dialog_content = "교회로 돌아오지 않아도 괜찮아. 앞으로 새로운 안식처를 찾을 수 있을 거야.",
  ui_story_5033_50331101_86_dialog_content = "우리가 모두 함께 안전하고 즐겁게 있을 수 있는 게 제일 중요하잖니.",
  ui_story_5033_50331101_87_dialog_content = "그, 그럼 폴룩스는? ...우리랑 같이 갈 거지?",
  ui_story_5033_50331101_88_dialog_content = "그럼, 물론이지.",
  ui_story_5033_50331101_89_dialog_content = "문제들을 해결하고 나면, 너희 곁으로 돌아갈게.",
  ui_story_5033_50331101_90_dialog_content = "어서 가렴, 얘들아.",
  ui_story_5033_50331202_1_dialog_content = "「레이븐즈 블러드」! 당장 나와라!",
  ui_story_5033_50331202_2_dialog_content = "오늘이 너희 제삿날이다!",
  ui_story_5033_50331202_3_dialog_content = "언제까지 유포리아에서 너희 마음대로 날뛸 수 있을 거라고 생각했냐! 나와!",
  ui_story_5033_50331202_4_dialog_content = "교회 안에 있는 녀석들도 잘 들어라. 특히 움브라톤에서 온 두 녀석!",
  ui_story_5033_50331202_5_dialog_content = "너희가 뭘 하러 왔든, 유포리아에 왔으면 유포리아의 규칙에 따라야 한다는 걸 명심해라!",
  ui_story_5033_50331202_6_dialog_content = "「레이븐즈 블러드」와 결탁하면 유포리아 전체를 적으로 돌리게 되는 거다.",
  ui_story_5033_50331202_7_dialog_content = "할 말이 있으면 교회 안으로 들어와서 하지 그래?",
  ui_story_5033_50331202_8_dialog_content = "칼을 들고 왔든, 총을 들고 왔든 환영해 줄게. 분명 너희들 모두 만족할 수 있을 거야.",
  ui_story_5033_50331202_9_dialog_content = "대장, 이건 폴룩스 목소린데요!",
  ui_story_5033_50331202_10_dialog_content = "안에서 뭘 꾸미고 있는 거지?",
  ui_story_5033_50331202_11_dialog_content = "저, 저도 모르죠...",
  ui_story_5033_50331202_12_dialog_content = "그럼 이제 어쩌죠?",
  ui_story_5033_50331202_13_dialog_content = "아니면... 대장이 먼저 들어가 보실래요?",
  ui_story_5033_50331202_14_dialog_content = "너 진짜 머리가 있는 거냐? 없는 거냐?!",
  ui_story_5033_50331202_15_dialog_content = "이런 상황에서 무작정 저 안으로 기어들어 가면 어떻게 되겠냐? 당할 게 뻔하잖아!",
  ui_story_5033_50331202_16_dialog_content = "대장 말이 맞아요! 들어갈 거면 다 같이 뛰어 들어가야죠!",
  ui_story_5033_50331202_17_dialog_content = "뛰어 들어가긴 뭘 뛰어 들어가? 넌 머리 쓸 줄도 몰라? 아무나 가서 폭탄 가져 와!",
  ui_story_5033_50331202_18_dialog_content = "아이고... 네.",
  ui_story_5033_50331202_19_dialog_content = "나머지 녀석들은 여기서 기다려라.\n녀석들이 빠져나가지 못하게 이 주변만 제대로 포위해 두면 되잖아.",
  ui_story_5033_50331202_20_dialog_content = "좋은 생각이십니다!",
  ui_story_5033_50331202_21_dialog_content = "구스타프 쪽은 왜 아직 아무 소식도 없지? 답답하네...",
  ui_story_5033_50331202_22_dialog_content = "야옹...",
  ui_story_5033_50331202_23_dialog_content = "신호다! 드디어 왔나...",
  ui_story_5033_50331202_24_dialog_content = "어라... 물건은 어디 있지?",
  ui_story_5033_50331202_25_dialog_content = "혹시 찾고 있는 게 이 쪽지야?",
  ui_story_5033_50331202_26_dialog_content = "누, 누구야? 언제부터 내 뒤에 서 있던 건데?!",
  ui_story_5033_50331202_27_dialog_content = "너희가 여기 도착했을 때부터.",
  ui_story_5033_50331202_28_dialog_content = "수, 수녀?! 젠장...",
  ui_story_5033_50331202_29_dialog_content = "응, 「애니」 수녀라고 불러. 아니면 「<color=#FFB400>안타레스</color>」라고 불러도 좋아.",
  ui_story_5033_50331202_30_dialog_content = "어차피... 다른 사람한테 알려 줄 기회는 없겠지만.",
  ui_story_5033_50331202_31_dialog_content = "사, 살려줘... 나, 난 잔심부름만 했어... 난 아무것도 몰라.",
  ui_story_5033_50331202_32_dialog_content = "살려 줄게. 그럼 「구스타프」가 누군지 말해줄래?",
  ui_story_5033_50331202_33_dialog_content = "보니까... 너한테 그 쪽지를 전한 사람 같은데.",
  ui_story_5033_50331202_34_dialog_content = "단서가 이렇게 쉽게 손에 들어올 줄은 몰랐네.",
  ui_story_5033_50331202_35_dialog_content = "혹시 날 꾀어내기 위한 함정이야?",
  ui_story_5033_50331202_36_dialog_content = "무, 무슨 소리야? 난 하나도 모른다고!",
  ui_story_5033_50331202_37_dialog_content = "아니지, 상황이 너무 급하게 돌아가는 바람에 흔적을 없앨 시간이 모자랐을 수도 있겠어...",
  ui_story_5033_50331202_38_dialog_content = "아까부터 무슨 소릴 하는 거야?! 너 미쳤어...?",
  ui_story_5033_50331202_39_dialog_content = "모르는 척하지 마. 날 본 그 순간부터 내가 누군지 알아봤잖아.",
  ui_story_5033_50331202_40_dialog_content = "그리고 내가 뭘 하러 온 건지... 아니면 내가 무슨 짓을 할지 이미 알고 있었겠지.",
  ui_story_5033_50331202_41_dialog_content = "사람은 죽음을 눈앞에 두고 있을 땐 진실만을 말하는 법이야.",
  ui_story_5033_50331202_42_dialog_content = "쳇...",
  ui_story_5033_50331202_43_dialog_content = "안타레스... 네겐 아무것도 말해주지 않을 거야.",
  ui_story_5033_50331202_44_dialog_content = "이제 필요 없어.",
  ui_story_5033_50331202_45_dialog_content = "<color=#e8d9bb>스으윽──</color>",
  ui_story_5033_50331202_46_dialog_content = "크억... 너...",
  ui_story_5033_50331202_47_dialog_content = "하하... 이게 바로 「사신」에게 살해당하는... 느낌이구나...",
  ui_story_5033_50331202_48_dialog_content = "네가 나한테 단서를 전해 준 게 고마워서, 최대한 고통스럽지 않게 조절한 거야.",
  ui_story_5033_50331202_49_dialog_content = "고마워.",
  ui_story_5033_50331202_50_dialog_content = "덕분에... 드디어 폴룩스를 만나러 갈 수 있게 됐어.",
  ui_story_5033_50331202_51_dialog_content = "대장, 대장! 폭탄을 가져왔습니다!",
  ui_story_5033_50331202_52_dialog_content = "양은 적지만 교회 하나쯤은 날려버릴 수 있을 겁니다!",
  ui_story_5033_50331202_53_dialog_content = "좋아, 잘했다!",
  ui_story_5033_50331202_54_dialog_content = "이 폭탄들을 교회 주변에 설치해 둬라.",
  ui_story_5033_50331202_55_dialog_content = "설치하고 있을 때 놈들이 교회 안에서 총을 쏠 수도 있으니까 조심하고.",
  ui_story_5033_50331202_56_dialog_content = "예! 알겠습니다!",
  ui_story_5033_50331202_57_dialog_content = "실례합니다, 잠깐 좀 지나갈게요. 저 앞에 볼일이 있거든요.",
  ui_story_5033_50331202_58_dialog_content = "웬 수녀야? 죽기 싫으면 얼른 저쪽으로 꺼...",
  ui_story_5033_50331202_59_dialog_content = "<color=#e8d9bb>스으윽──</color>",
  ui_story_5033_50331202_60_dialog_content = "<size=45>으아아아아! 사람을 죽였어!</size>",
  ui_story_5033_50331202_61_dialog_content = "뭐야?! 뒤에 무슨 일이 생겼나?",
  ui_story_5033_50331202_62_dialog_content = "걱정하지 마세요. 별일 없었어요...\n폭력조직에서 내분이 일어나서 사람 몇 명 죽는 것쯤은 평범한 일이잖아요.",
  ui_story_5033_50331202_63_dialog_content = "넌 또 어디서 튀어나온 거야?!",
  ui_story_5033_50331202_64_dialog_content = "<color=#e8d9bb>스으윽──</color>",
  ui_story_5033_50331202_65_dialog_content = "으아악! 내 손! 내 손이...!",
  ui_story_5033_50331202_66_dialog_content = "대장! 저 수녀, 손에 칼을 가지고 있습니다...!",
  ui_story_5033_50331202_67_dialog_content = "끄아악! 헛소리 집어 치워! 저 여자가 내 손을 잘라 버렸다고! 빨리 해치워!",
  ui_story_5033_50331202_68_dialog_content = "폭탄으로 교회를 파괴하려는 계획은 포기하는 게 좋을 거예요.\n천벌을 받을 테니까요.",
  ui_story_5033_50331202_69_dialog_content = "<color=#e8d9bb>스으윽──</color>",
  ui_story_5033_50331202_70_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5033_50331202_71_dialog_content = "폭탄이 터졌잖아?! 빠, 빨리 흩어져!",
  ui_story_5033_50331202_72_dialog_content = "저 수녀가 칼로 폭탄을 베어서 터트려 버렸어! 제정신이 아니야!",
  ui_story_5033_50331202_73_dialog_content = "봐! 저러고도 아직 살아있잖아... 대체 뭘 어떻게 한 거야?",
  ui_story_5033_50331202_74_dialog_content = "다들 좀 조용히 해 줘요. 교회엔 볼일이 있어서 온 거니까.\n일을 마치고 나면 여러분이 뭘 하든 간섭하지 않을 거예요.",
  ui_story_5033_50331202_75_dialog_content = "그러니까 그 전까진 허튼짓 말고 얌전히 있어요...",
  ui_story_5033_50331202_76_dialog_content = "「<color=#FFB400>사신</color>」을 만나고 싶은 게 아니라면.",
  ui_story_5033_50331301_1_dialog_content = "어, 어떡하지... 저 수녀가 하란 대로 할까?",
  ui_story_5033_50331301_2_dialog_content = "아까 저 수녀 때문에 몇 명이나 죽었잖아. 못 봤어?",
  ui_story_5033_50331301_3_dialog_content = "덤빌 거면 덤벼... 난 안 할래.",
  ui_story_5033_50331301_4_dialog_content = "바, 방금 저 수녀가 「사신」이라고 하던데,\n설마 그 소문들이 다 사실이었던 거야?",
  ui_story_5033_50331301_5_dialog_content = "쉿... 만약 그게 진짜면 절대 그 이름을 입 밖에 꺼내선 안 돼.",
  ui_story_5033_50331301_6_dialog_content = "다들 협조해 줘서 고마워요.",
  ui_story_5033_50331301_7_dialog_content = "<color=#e8d9bb>교회 안</color>",
  ui_story_5033_50331301_8_dialog_content = "...밖에 무슨 일이 생겼나?",
  ui_story_5033_50331301_9_dialog_content = "<color=#e8d9bb>또각, 또각...</color>",
  ui_story_5033_50331301_10_dialog_content = "안녕하세요...",
  ui_story_5033_50331301_11_dialog_content = "밖엔 놈들이 포위하고 있을 텐데, 어떻게 들어온 거지?",
  ui_story_5033_50331301_12_dialog_content = "밖에 있는 친구들이랑 얘기를 좀 나눠 봤는데, 다들 들어가 보라고 하더군요.",
  ui_story_5033_50331301_13_dialog_content = "당신이 누구든, 여기에 뭘 하러 왔든 상관없어.",
  ui_story_5033_50331301_14_dialog_content = "돌아가, 여기엔 빛의 신은 없으니까.",
  ui_story_5033_50331301_15_dialog_content = "...내가 누군지 모르겠니? 폴룩스.",
  ui_story_5033_50331301_16_dialog_content = "<size=45>너...!</size>",
  ui_story_5033_50331301_17_dialog_content = "오랜만이야.",
  ui_story_5033_50331301_18_dialog_content = "<color=#FFB400>안타레스</color>! 역시... 아니, 네가 어떻게?",
  ui_story_5033_50331301_19_dialog_content = "미안해, 폴룩스. 널 다시 만나려면 이 방법밖엔 없었거든.",
  ui_story_5033_50331301_20_dialog_content = "난 네가 벌써 오래전에 날 잊은 줄 알았어.",
  ui_story_5033_50331301_21_dialog_content = "내가 어떻게 잊었겠어...? 그때 내가 내 손으로 널...",
  ui_story_5033_50331301_22_dialog_content = "그렇게 죄책감 가득한 눈빛으로 바라보지 말아 줘, 폴룩스. 부탁이야.",
  ui_story_5033_50331301_23_dialog_content = "사실 너랑 다시 만날 때 무슨 말을 할지,\n널 어떻게 마주 봐야 할지 머릿속으로 참 많이 연습했었는데.",
  ui_story_5033_50331301_24_dialog_content = "실제로 이렇게 네 앞에 서 있으니까, 준비했던 말들이 하나도 생각이 안 나네.",
  ui_story_5033_50331301_25_dialog_content = "나한테 무슨 말을 하고 싶었어...?",
  ui_story_5033_50331301_26_dialog_content = "네 눈빛은 그때랑 똑같이 변한 게 없구나.",
  ui_story_5033_50331301_27_dialog_content = "꼭 「별빛」처럼 반짝거려.",
  ui_story_5033_50331301_28_dialog_content = "안... 이번 일들은 다 네가 꾸민 거야? 왜 그랬어?",
  ui_story_5033_50331301_29_dialog_content = "대체 어떻게 된 거야? 어떻게 살아 있었던 거고?",
  ui_story_5033_50331301_30_dialog_content = "그리고 왜... 수녀로 변장하고 있어?",
  ui_story_5033_50331301_31_dialog_content = "조급해하지 마, 폴룩스. 다 설명해 줄게.",
  ui_story_5033_50331301_32_dialog_content = "대신 짧게 말할게. 이젠 시간이 없으니까.",
  ui_story_5033_50331301_33_dialog_content = "<color=#e8d9bb>14년 전</color>",
  ui_story_5033_50331301_34_dialog_content = "이쯤이면 되겠지, 강에 던져 버려.",
  ui_story_5033_50331301_35_dialog_content = "아깝게 됐어. 쌍둥이별 중 하나였는데, 이렇게 죽어 버리다니.",
  ui_story_5033_50331301_36_dialog_content = "보스도 이렇게 될 줄은 예상 못 하셨겠지...",
  ui_story_5033_50331301_37_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_5033_50331301_38_dialog_content = "이런... 강 속에...",
  ui_story_5033_50331301_39_dialog_content = "누가 좀 도와줘... 강 속에 아이가 있어!",
  ui_story_5033_50331301_40_dialog_content = "어서 불을 피워! 아직 숨은 쉬고 있으니까 가서 빨리 의사를 불러와!",
  ui_story_5033_50331301_41_dialog_content = "윽... 아파...",
  ui_story_5033_50331301_42_dialog_content = "아직... 살아 있네?",
  ui_story_5033_50331301_43_dialog_content = "문밖에 있는 건 누구지?",
  ui_story_5033_50331301_44_dialog_content = "정말 무서운 일이군... 대체 누가 어린애한테 저런 짓을 한 거지?",
  ui_story_5033_50331301_45_dialog_content = "그래도 그런 상처를 입고도 살아남은 걸 보면, 삶에 대한 의지가 정말 강한 아이잖아.",
  ui_story_5033_50331301_46_dialog_content = "결코 평범한 사건은 아니겠지... 움브라톤의 수도원으로 보내주는 게 좋겠어.\n더 큰 문제에 휘말리게 되면 곤란하니까...",
  ui_story_5033_50331301_47_dialog_content = "<color=#e8d9bb>똑똑똑──</color>",
  ui_story_5033_50331301_48_dialog_content = "자, 애니. 여기 오늘 신문이야.",
  ui_story_5033_50331301_49_dialog_content = "여기 편지도 한 통 왔어... 근데 이 수도원에 「<color=#FFB400>안타레스</color>」란 사람은 없지 않아?",
  ui_story_5033_50331301_50_dialog_content = "뭐라고?",
  ui_story_5033_50331301_51_dialog_content = "...아, 맞아. 여기 안타레스란 사람은 없어.",
  ui_story_5033_50331301_52_dialog_content = "이름을 잘못 적었나 보네. 누구한테 보낸 건지 한 번 확인해 줄래?",
  ui_story_5033_50331301_53_dialog_content = "「안타레스에게.」",
  ui_story_5033_50331301_54_dialog_content = "「나는 빛의 신의 독실한 신도다.\n용서할 수 없는 죄를 범한 어떤 이를 위해 대신 속죄하려 한다.」",
  ui_story_5033_50331301_55_dialog_content = "「그녀는 헛된 자유를 얻기 위해 죽음이라는 거짓된 형상을 뒤집어쓰고 가족을 기만했다.」",
  ui_story_5033_50331301_56_dialog_content = "「그녀는 우정을 이용했고, 진실한 감정을 나눈 친구에게 살아남았다는 죄책감을\n짊어지게 만들어 고통에서 허우적거리게 했다.」",
  ui_story_5033_50331301_57_dialog_content = "「그녀는 다음번 고해 성사 편지가 도착할 때까지 참회할 것이다.」",
  ui_story_5033_50331301_58_dialog_content = "(대체 누가...)",
  ui_story_5033_50331301_59_dialog_content = "애니, 너 안색이 너무 안 좋아.",
  ui_story_5033_50331301_60_dialog_content = "이 편지는 일단 여기 둘게.",
  ui_story_5033_50331301_61_dialog_content = "어쩌면 「안타레스」란 사람이... 가지러 올 수도 있으니까.",
  ui_story_5033_50331301_62_dialog_content = "그래서 몇 년 동안 수녀로 살아왔다는 거야?",
  ui_story_5033_50331301_63_dialog_content = "응.",
  ui_story_5033_50331301_64_dialog_content = "난 그 편지를 보낸 사람이 대체 어떻게 내 정체를 알고 있는지 몰랐어...",
  ui_story_5033_50331301_65_dialog_content = "아무튼 「그 사람」은 그 뒤로 날 철저히 통제하기 시작했고,\n난 그 사람이 내린 지령을 감히 어길 수 없었어.",
  ui_story_5033_50331301_66_dialog_content = "죽는 것도 두려워하지 않는 널 통제할 수 있는 사람이 있다고?\n찔러도 피 한 방울 나지 않을 것 같은 사람한테도 약점이 있단 말이야?",
  ui_story_5033_50331301_67_dialog_content = "있지... 내 유일한 약점은... 바로 내 유일한 친구야.",
  ui_story_5033_50331301_68_dialog_content = "나 때문이었다고?",
  ui_story_5033_50331301_69_dialog_content = "응. 「그 사람」이 그랬거든.\n넌 그 사건 이후로 넋이 나간 상태지만, 쌍둥이별은 계속 존재해야만 한다고...",
  ui_story_5033_50331301_70_dialog_content = "「폴룩스가 더 이상 칼을 잡지 못한다면, 더 이상 아무런 이용 가치도 없다.」",
  ui_story_5033_50331301_71_dialog_content = "만약 내가 그 명령들을 따르지 않았다면, 넌...",
  ui_story_5033_50331301_72_dialog_content = "난 지금까지 「조직」이 나한테 실패의 책임을 묻지 않은 이유가\n암귀의 침입 때문에 나한테 신경 쓸 겨를이 없어서인 줄로만 알았어...",
  ui_story_5033_50331301_73_dialog_content = "「조직」은 그렇게 쉽게 우릴 놓아주지 않아.",
  ui_story_5033_50331301_74_dialog_content = "설령 유포리아가 전부 파괴되어 버린다 해도,\n「조직」의 사람들은 여전히 남아서 계속 우릴 조종하려 들 거야.",
  ui_story_5033_50331301_75_dialog_content = "안, 그래서 그 사건들은 전부 네가 한 거야?",
  ui_story_5033_50331301_76_dialog_content = "다른 선택지가 없었어, 폴룩스.",
  ui_story_5033_50331301_77_dialog_content = "넌 그날의 싸움에서 살아남았어. 그리고 성공적으로 그곳을 떠났지.",
  ui_story_5033_50331301_78_dialog_content = "난 네 자유를 지켜 주고 싶었어.",
  ui_story_5033_50331301_79_dialog_content = "비록 넌 끝내 유포리아를 떠나진 않았지만, 대신 지금은 지켜야 할 사람들도,\n기댈 수 있는 사람들도 생겼어. 그렇지?",
  ui_story_5033_50331301_80_dialog_content = "아이들 말하는 거야?",
  ui_story_5033_50331301_81_dialog_content = "총을 다루는 여자애도 있잖아. 믿고 의지할 만한 아이인 것 같았어.",
  ui_story_5033_50331301_82_dialog_content = "그런 사람들이 곁에 있다면, 어떤 위험이 닥쳐도 두려워할 필요는 없을 거야.",
  ui_story_5033_50331301_83_dialog_content = "난 그저 이미 오래전에 죽은... 더럽혀진 망령일 뿐이야.",
  ui_story_5033_50331301_84_dialog_content = "그럼... 마틸다 수녀님... 그분도 네가 죽였어?!",
  ui_story_5033_50331301_85_dialog_content = "......",
  ui_story_5033_50331301_86_dialog_content = "안, 대답해.",
  ui_story_5033_50331301_87_dialog_content = "응.",
  ui_story_5033_50331301_88_dialog_content = "왜 그랬어?",
  ui_story_5033_50331301_89_dialog_content = "「죽여」라는 수많은 지령 중 하나일 뿐이었어.\n나도 그 수녀님이 왜 조직의 눈 밖에 난 건진 몰라.",
  ui_story_5033_50331301_90_dialog_content = "미안해, 폴룩스.",
  ui_story_5033_50331301_91_dialog_content = "넌 나한테 수녀님이 얼마 중요한 사람인지 알고 있었어.",
  ui_story_5033_50331301_92_dialog_content = "그땐 정말 어쩔 수 없었어...",
  ui_story_5033_50331301_93_dialog_content = "무기, 안 가져왔구나.",
  ui_story_5033_50331301_94_dialog_content = "뭐?",
  ui_story_5033_50331301_95_dialog_content = "네 무기 말이야, 안타레스.\n지금 내 앞에 빈손으로 서서 그런 이야기를 하고 있잖아...",
  ui_story_5033_50331301_96_dialog_content = "설마 내가 널 공격할지 안 할지 시험이라도 하려던 거야?",
  ui_story_5033_50331301_97_dialog_content = "예전에도 비슷한 상황이 있었던 것 같네.\n그런데 폴룩스, 나 무기 가지고 왔어.",
  ui_story_5033_50331301_98_dialog_content = "왜냐면 내 마지막 지령은... <color=#FFB400>널 죽이는 거</color>거든.",
  ui_story_5033_50331301_99_dialog_content = "그럼 뭘 꾸물거리고 있어?",
  ui_story_5033_50331301_100_dialog_content = "내가 절대로 그렇게 안 할 거라는 거 알잖아, 폴룩스.",
  ui_story_5033_50331301_101_dialog_content = "난 너랑 옛날이야기나 하고 싶다는 이유만으로 이런 일들을 벌인 게 아니야...",
  ui_story_5033_50331301_102_dialog_content = "오랫동안 우릴 이용한 빌어먹을 녀석들은 앞으로도 네게 가장 큰 위협이 되겠지.\n그래서 그 녀석들을 전부 없애고 싶었어.",
  ui_story_5033_50331301_103_dialog_content = "그럼 내가 감동해서 눈물이라도 흘려 주길 원해?",
  ui_story_5033_50331301_104_dialog_content = "아니. 그냥 만나고 싶었어. 작별 인사도 하고 싶었고.",
  ui_story_5033_50331301_105_dialog_content = "폴룩스, 모든 게 끝난 뒤에, 네가 뭘 해야 하는지 알 수 있게 된다면 좋겠어.",
  ui_story_5033_50331301_106_dialog_content = "하...",
  ui_story_5033_50331301_107_dialog_content = "너 정말 이기적이구나.",
  ui_story_5033_50331301_108_dialog_content = "멋대로 친구가 되고, 내 칼에 달려들고, 「죽어서도」 내 운명을 조종하더니...",
  ui_story_5033_50331301_109_dialog_content = "이젠 당당하게 내 앞에 나타나서 이런 얘기들을 아무렇지도 않게 늘어놓고.",
  ui_story_5033_50331301_110_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_5033_50331301_111_dialog_content = "시간이 다 된 것 같아.",
  ui_story_5033_50331301_112_dialog_content = "뒷문으로 사람... 아니, 암귀가 들어왔어.",
  ui_story_5033_50331301_113_dialog_content = "지금은 무척 예민해졌구나, 폴룩스. 그때랑은 완전히 다른 사람 같아.",
  ui_story_5033_50331301_114_dialog_content = "긴 머리도 정말 잘 어울려. 그런데 눈은 왜 그렇게 된 거야?",
  ui_story_5033_50331301_115_dialog_content = "...너한테 할 말 없어.",
  ui_story_5033_50331301_116_dialog_content = "하지만 난 너랑 하고 싶은 얘기가 많은걸...",
  ui_story_5033_50331301_117_dialog_content = "그럼 내가 첫 번째 속죄를 끝내고 나면, 천천히 네게 들려줄게.",
  ui_story_5033_50331302_1_dialog_content = "라탄, 쉐베...",
  ui_story_5033_50331302_2_dialog_content = "좋아, 다 모였네.",
  ui_story_5033_50331302_3_dialog_content = "그럼 다들 꼼짝 말고 여기 있어. 알겠어?",
  ui_story_5033_50331302_4_dialog_content = "나도 도와줄 수 있어! 폴룩스 누나가 싸우는 법을 가르쳐 줬는걸!",
  ui_story_5033_50331302_5_dialog_content = "나, 나도!",
  ui_story_5033_50331302_6_dialog_content = "떼쓰지 마, 지금은 그럴 때가 아니...",
  ui_story_5033_50331302_7_dialog_content = "사실 여기도 지켜줄 사람이 필요하단 말이지.\n저 난폭한 주민들이 여기까지 쫓아 올지도 모르거든.",
  ui_story_5033_50331302_8_dialog_content = "그러니까 너희가 착하게 여기 있으면서 모든 출입구를 감시해 주면 정말 큰 도움이 될 거야.",
  ui_story_5033_50331302_9_dialog_content = "알겠어! 지금 바로 특별 작전팀을 꾸릴게!",
  ui_story_5033_50331302_10_dialog_content = "나무판자를 모아서 창문에 못을 박아 두면 더 좋을 것 같아.",
  ui_story_5033_50331302_11_dialog_content = "알겠어. 가자, 라탄!",
  ui_story_5033_50331302_12_dialog_content = "오케이!",
  ui_story_5033_50331302_13_dialog_content = "아이들을 여기 있게 해도 괜찮을까?",
  ui_story_5033_50331302_14_dialog_content = "지금 다른 곳으로 가는 건 너무 위험해.",
  ui_story_5033_50331302_15_dialog_content = "그런데 여기도 이렇게 많은 사람이 머문 적은 처음이거든.\n이 음식들로 얼마나 버틸 수 있을지 모르겠어.",
  ui_story_5033_50331302_16_dialog_content = "걱정 마라, 이번 일도 그리 오래가진 않을 테니까.",
  ui_story_5033_50331302_17_dialog_content = "구스타프, 왔어?",
  ui_story_5033_50331302_18_dialog_content = "빨리 어떻게 좀 해 봐. 교회 쪽에서 곧 싸움이 붙겠어.\n당신은 이 유포리아의 정보통이잖아.",
  ui_story_5033_50331302_19_dialog_content = "다 들었다. 상황이 많이 급박한 것 같더군.",
  ui_story_5033_50331302_20_dialog_content = "교회를 둘러싸고 있는 녀석들 대부분은 각 클랜 소속이다.\n내가 녀석들의 부두목들한테 연락하면 금방 해결될 거다.",
  ui_story_5033_50331302_21_dialog_content = "하지만 문제는 일반 시민들 쪽이다.",
  ui_story_5033_50331302_22_dialog_content = "지금 다들 폴룩스가 움브라톤 사람들을 교회에 숨기고 있었다는 걸 알아버렸다.\n말 몇 마디로 분위기가 수그러들긴 힘들 것 같군.",
  ui_story_5033_50331302_23_dialog_content = "............",
  ui_story_5033_50331302_24_dialog_content = "네가 바로 움브라톤에서 왔다는 그 녀석인가?",
  ui_story_5033_50331302_25_dialog_content = "타키가 우리 얘길 안 해 준 모양이지?",
  ui_story_5033_50331302_26_dialog_content = "너희가 온다는 말은 했지만, 이렇게 큰 문젯거리를 가져올 거라곤 안 했다.",
  ui_story_5033_50331302_27_dialog_content = "지금 유포리아 사람들은 전부 섀도우마스터가 유포리아를 파괴하려고\n너희 둘을 보냈다고 여긴단 말이다!",
  ui_story_5033_50331302_28_dialog_content = "우린 아무것도 안 했어.",
  ui_story_5033_50331302_29_dialog_content = "흥, 이제 와서 그런 소릴 해 봐야 늦었다.",
  ui_story_5033_50331302_30_dialog_content = "사건 조사를 하려면 그냥 조사나 할 것이지,\n왜 굳이 「레이븐즈 블러드」와 얽혀서 여기 사람들을 들볶은 거냐.",
  ui_story_5033_50331302_31_dialog_content = "「레이븐즈 블러드」가 평소에 이곳 사람들과 얼마나 문제가 많았는지 아냔 말이다.",
  ui_story_5033_50331302_32_dialog_content = "유포리아는 언제나 클랜의 실력이 곧 법인 곳이잖아.\n우린 한 번도 그 규칙을 어긴 적 없어.",
  ui_story_5033_50331302_33_dialog_content = "전부터 말했지. 너무 많은 적을 만들면 원한을 더 많이 사게 된다고.\n그래도 너흰 들은 체도 안 했었지.",
  ui_story_5033_50331302_34_dialog_content = "이제 각 클랜이 연합해서 너흴 없애려고 하는데, 내가 막을 수 있을 것 같나?",
  ui_story_5033_50331302_35_dialog_content = "그래도 폴룩스도 실력 하나는 대단하군. 너희가 몰래 도망칠 수 있게 만들다니.\n폴룩스는 어디 있지?",
  ui_story_5033_50331302_36_dialog_content = "폴룩스는 우릴 엄호하려고 교회에 남았어. 얼른 돌아가서 폴룩스를 데려와야 해.",
  ui_story_5033_50331302_37_dialog_content = "가자, 이미 싸우기 시작했을지도 몰라!",
  ui_story_5033_50331302_38_dialog_content = "성급하게 굴지 마라, 카스타.\n너희한테 반드시 알려줘야 하는 중요한 소식이 있으니 말이다...",
  ui_story_5033_50331302_39_dialog_content = "지금 이 유포리아엔 아주 위험한 인물이 하나 들어와 있다.",
  ui_story_5033_50331302_40_dialog_content = "아마 그 여자가 바로 너희 두 사람이 유포리아에서 찾으려던 사람일 거다.",
  ui_story_5033_50331302_41_dialog_content = "설마... 그 사건의 범인 말인가요?",
  ui_story_5033_50331302_42_dialog_content = "여기 올 때 어떤 수녀와 같이 오지 않았나?",
  ui_story_5033_50331302_43_dialog_content = "그렇다. 하지만 도착하자마자 헤어졌고, 지금까지 다시 마주친 적은 없다.",
  ui_story_5033_50331302_44_dialog_content = "설마...",
  ui_story_5033_50331302_45_dialog_content = "내가 교회 상황을 살피라고 근처에 보냈던 부하도 그 여자한테 살해당했다.\n그 여자는 지금 이 근처에 있을 거다.",
  ui_story_5033_50331302_46_dialog_content = "뭐?!",
  ui_story_5033_50331302_47_dialog_content = "그럼 마틸다 수녀님을 해친 녀석이 지금 교회에 있다는 거야?!",
  ui_story_5033_50331302_48_dialog_content = "그래, 움브라톤에서 일어난 사건들과 수법도 똑같으니 그 여자가 틀림없다.",
  ui_story_5033_50331302_49_dialog_content = "잠깐, 어떻게 당신이 그렇게 자세한 부분까지 알고 있는 거지?",
  ui_story_5033_50331302_50_dialog_content = "젊은이, 난 정보로 먹고사는 사람이야.",
  ui_story_5033_50331302_51_dialog_content = "내가 가진 정보들은 이게 다가 아니라고.\n그중엔 폴룩스가 분명히 흥미를 보일 만한 비밀도 하나 있지...",
  ui_story_5033_50331302_52_dialog_content = "그 수녀의 진짜 정체는 빛의 신을 섬기는 시종 같은 게 아니다.",
  ui_story_5033_50331302_53_dialog_content = "그 여자는 폴룩스와 함께 쌍둥이별로 불렸던, 조직의 전 멤버 <color=#FFB400>안타레스</color>다.",
  ui_story_5033_50331302_54_dialog_content = "뭐라고?!",
  ui_story_5033_50331302_55_dialog_content = "잠깐만요, 그 사람은 죽었다고 들었는데요?",
  ui_story_5033_50331302_56_dialog_content = "그래, 그건 불가능해. 그 사람은 폴룩스가 오래전에...",
  ui_story_5033_50331302_57_dialog_content = "나도 이 정보를 알아내고 나선 무척이나 놀랐었지. 하지만 이건 사실이다.",
  ui_story_5033_50331302_58_dialog_content = "안타레스는 살아 있었을 뿐만 아니라, 몇 년 동안 힘을 키운 다음\n유포리아로 돌아와 복수하기로 한 거다.",
  ui_story_5033_50331302_59_dialog_content = "그럼 뭘 꾸물거리고 있는 건데? 폴룩스가 위험할 수도 있잖아!",
  ui_story_5033_50331302_60_dialog_content = "그래, 그 여자는 눈 하나 깜짝하지 않고 사람을 죽이지. 무슨 일을 벌일지 아무도 모른다...",
  ui_story_5033_50331302_61_dialog_content = "계속 날뛰게 둬선 안 된다.",
  ui_story_5033_50331302_62_dialog_content = "그걸 정말 확신하나?",
  ui_story_5033_50331302_63_dialog_content = "젊은이, 찾던 사람이 어디 있는지는 알려 줬으니,\n잡고 못 잡고는 이제 자네한테 달렸다.",
  ui_story_5033_50331302_64_dialog_content = "제길...",
  ui_story_5033_50331302_65_dialog_content = "구스타프, 당신도 저들이랑 같이 가서 저쪽 상황을 좀 정리해 줘. 저들만 갔다간...",
  ui_story_5033_50331302_66_dialog_content = "하하하, 상황 정리는 걱정하지 말고 나한테 맡겨라.",
  ui_story_5033_50331302_67_dialog_content = "너흰 그 범인을 끌어내는 데만 집중해라. 모두에게 사건의 진상을 알려야 하니 말이야.",
  ui_story_5033_50331302_68_dialog_content = "너흴 향한 유포리아 사람들의 분노는 내가 잠재워 주지...",
  ui_story_5033_50331401_1_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_5033_50331401_2_dialog_content = "폭탄이야? 아니면 천둥소리야?",
  ui_story_5033_50331401_3_dialog_content = "아이테르, 좀 빨리 못 뛰나? 어떻게 이 늙은이보다도 느릴 수 있지?",
  ui_story_5033_50331401_4_dialog_content = "그거 정말 죄송하게 됐네요...",
  ui_story_5033_50331401_5_dialog_content = "카스타, 할 말이 있다.",
  ui_story_5033_50331401_6_dialog_content = "무슨 소리 하려는 지 알아.",
  ui_story_5033_50331401_7_dialog_content = "그 여잔 반드시 죽을 거야.",
  ui_story_5033_50331401_8_dialog_content = "너...",
  ui_story_5033_50331401_9_dialog_content = "너희 두 사람이 마틸다 수녀 일로 얼마나 분노했는지는 알고 있다.",
  ui_story_5033_50331401_10_dialog_content = "하지만 이번 일은 그렇게 간단한 게 아니다.\n그 여자가 어떤 이유로 그런 짓들을 벌였는지 생각해 본 적 있나?",
  ui_story_5033_50331401_11_dialog_content = "폴룩스한테 복수하고, 자신을 「죽인」 유포리아에 복수하기 위해서겠지.",
  ui_story_5033_50331401_12_dialog_content = "그럴 수도 있겠지. 하지만 왜 하필 한참 시간이 지난 오늘이지?",
  ui_story_5033_50331401_13_dialog_content = "몰라.",
  ui_story_5033_50331401_14_dialog_content = "사람들의 이목을 끌면서까지 여러 살인을 저지르다가,\n마지막에서야 폴룩스를 찾아온 이유는 뭐냔 말이다.",
  ui_story_5033_50331401_15_dialog_content = "몰라.",
  ui_story_5033_50331401_16_dialog_content = "그리고 또...",
  ui_story_5033_50331401_17_dialog_content = "<size=45>모른다고 했잖아! 알고 싶지도 않아!</size>",
  ui_story_5033_50331401_18_dialog_content = "폴룩스는 예전에 그 여자를 한 번 죽였어.\n그리고 그 여자는 폴룩스를 구해 준 마틸다 수녀님을 죽였지.",
  ui_story_5033_50331401_19_dialog_content = "그리고 폴룩스한테 혐의를 뒤집어씌웠어.\n게다가 너희가 단서를 찾으러 왔을 때 유포리아로 돌아왔고...",
  ui_story_5033_50331401_20_dialog_content = "이 모든 게 다 폴룩스한테 복수하기 위해서잖아! 이게 그렇게 이해하기 어려워?!",
  ui_story_5033_50331401_21_dialog_content = "일단 진정해. 폴룩스라면 어떻게 했을지 생각해 봐!",
  ui_story_5033_50331401_22_dialog_content = "폴룩스는 안타레스를 감싸지 않을 거야!",
  ui_story_5033_50331401_23_dialog_content = "폴룩스도 나랑 똑같아, 그 여자를 갈가리 찢어 놓을 거라고!",
  ui_story_5033_50331401_24_dialog_content = "카스타!",
  ui_story_5033_50331401_25_dialog_content = "야, 그건 먹으면 안 돼! 빨리 뱉...",
  ui_story_5033_50331401_26_dialog_content = "<color=#e8d9bb>딩동── 딩동딩동, 딩동──</color>",
  ui_story_5033_50331401_27_dialog_content = "아무튼, 이건 먹으면 안 돼. 알겠지? 다른 데 가서 놀아.",
  ui_story_5033_50331401_28_dialog_content = "휴우... 드디어 애들도 좀 조용해졌네.",
  ui_story_5033_50331401_29_dialog_content = "<color=#e8d9bb>쾅쾅쾅!</color>",
  ui_story_5033_50331401_30_dialog_content = "누구야?",
  ui_story_5033_50331401_31_dialog_content = "빨리 문 열어요! 전 쿠리어 길드 움브라톤 지부 특파원 에호라고 해요!",
  ui_story_5033_50331401_32_dialog_content = "간 떨어지는 줄 알았네. 이런 때 무슨 일이야? 나한테 줄 소포라도 있나?",
  ui_story_5033_50331401_33_dialog_content = "트, 트, 특별 긴급 우편이에요! 움브라톤에서 보낸 거예요!",
  ui_story_5033_50331401_34_dialog_content = "조용히 말해! 얼른 줘 봐.",
  ui_story_5033_50331401_35_dialog_content = "<color=#e8d9bb>휘릭──</color>",
  ui_story_5033_50331401_36_dialog_content = "「타키다. 와타리와 연락이 닿질 않더군. 어쩔 수 없이 요행을 바라고 네 쪽에 연락했다.」",
  ui_story_5033_50331401_37_dialog_content = "「연쇄 살인 사건에서 살아남은 피해자가 깨어났다.\n반드시 이 사실을 와타리에게 전해라...」",
  ui_story_5033_50331401_38_dialog_content = "「범인은 회색 머리카락, 회색 눈동자를 지닌 수녀로,\n생김새는 아래에 붙인 몽타주를 확인하면 된다...」",
  ui_story_5033_50331401_39_dialog_content = "「하지만 이 수녀는 주범이 아니다! 그녀의 뒤에서 모든 걸 조종한 인물은 바로...」",
  ui_story_5033_50331401_40_dialog_content = "뭐라고...?",
  ui_story_5033_50331401_41_dialog_content = "<size=42>「<color=#FFB400>구스타프</color>다!」</size>",
  ui_story_5033_50331401_42_dialog_content = "<size=42>「이 모든 사건의 배후에 있는 주모자는 바로 <color=#FFB400>구스타프</color>란 말이다!」</size>",
  ui_story_5033_50331401_43_dialog_content = "속죄? 들려줘? 넌 대체 뭐 때문에 여기 돌아온 거야...?",
  ui_story_5033_50331401_44_dialog_content = "난 그냥 네게 알려주고 싶었어.\n계속 뒤에 숨어 우릴 조종하던 그 사람을 드디어 찾아냈거든.",
  ui_story_5033_50331401_45_dialog_content = "그 녀석을 죽이고 나면, 이 목숨도 네게 돌려줄게.",
  ui_story_5033_50331401_46_dialog_content = "이건 너한테 빚 진 거니까.",
  ui_story_5033_50331401_47_dialog_content = "필요 없어! 난 널 움브라톤에 넘길 거야.",
  ui_story_5033_50331401_48_dialog_content = "그렇게는 안 돼... 난 너 말고 다른 사람 손에 죽고 싶진 않은걸.",
  ui_story_5033_50331401_49_dialog_content = "너 미쳤어?!",
  ui_story_5033_50331401_50_dialog_content = "응, 미친 지 오래야.",
  ui_story_5033_50331401_51_dialog_content = "난 유포리아의 아이로 태어났어. 그리고 「조직」에 들어가고 나서부턴...",
  ui_story_5033_50331401_52_dialog_content = "살인은 숨 쉬는 것처럼 평범한 일이었거든.",
  ui_story_5033_50331401_53_dialog_content = "난 그게 이상한 줄도 몰랐었어.",
  ui_story_5033_50331401_54_dialog_content = "그런데 나한테 첫 친구가 생겼고, 넌 별처럼 날 이끌어 줬어...",
  ui_story_5033_50331401_55_dialog_content = "닥쳐! 네가 마틸다 수녀님을 죽인 순간부터 우린 친구로 돌아갈 수 없게 됐으니까.",
  ui_story_5033_50331401_56_dialog_content = "아니... 내가 너한테 칼을 꺼내 든 그 순간부터 넌 날 친구로 생각하지 말았어야 했어.",
  ui_story_5033_50331401_57_dialog_content = "아니야, 폴룩스. 그건 다 「조직」의 잘못이고, 구스타프의 잘못이야...",
  ui_story_5033_50331401_58_dialog_content = "조직도 구스타프도 전부 사라져 버리면, 모든 게 끝날 거야.",
  ui_story_5033_50331401_59_dialog_content = "<size=45>구스타프?!</size>",
  ui_story_5033_50331401_60_dialog_content = "응, 방금 말했잖아. 계속 뒤에 숨어 우릴 조종하던 그 사람을 드디어 찾아냈다고.",
  ui_story_5033_50331401_61_dialog_content = "구스타프도 조직원이었어. 예전엔 보스의 오른팔이었지.",
  ui_story_5033_50331401_62_dialog_content = "구스타프도 조직원이었다고?",
  ui_story_5033_50331401_63_dialog_content = "증거는 있어?",
  ui_story_5033_50331401_64_dialog_content = "아쉽지만 증거는 없어.",
  ui_story_5033_50331401_65_dialog_content = "죽기 전에 사람들이 말해 줬던 증언들뿐이야.",
  ui_story_5033_50331401_66_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_5033_50331401_67_dialog_content = "<size=45>여기 있었구나, 안타레스!</size>",
  ui_story_5033_50331401_68_dialog_content = "으윽...",
  ui_story_5033_50331401_69_dialog_content = "폴룩스, 괜찮아?!",
  ui_story_5033_50331401_70_dialog_content = "난 괜찮아. 아이들은? 다들 괜찮아?",
  ui_story_5033_50331401_71_dialog_content = "이 여잔 수녀가 아니라 마틸다 수녀님을 죽인 범인이야!",
  ui_story_5033_50331401_72_dialog_content = "네가 못 죽이겠다면, 내가 하겠어!",
  ui_story_5033_50331401_73_dialog_content = "콜록, 콜록...",
  ui_story_5033_50331401_74_dialog_content = "<size=45>마틸다 수녀님을 죽이다니...!</size>",
  ui_story_5033_50331401_75_dialog_content = "카스타, 너...",
  ui_story_5033_50331401_76_dialog_content = "괜찮아, 폴룩스. 역시 아주 잠재력이 뛰어난 아이네...",
  ui_story_5033_50331401_77_dialog_content = "<size=45>무기는 어디 있지?! 어서 꺼내!</size>",
  ui_story_5033_50331401_78_dialog_content = "<size=45>마틸다의 목숨을 빼앗은 대가를... 반드시 치르게 해 주겠어!</size>",
  ui_story_5033_50331401_79_dialog_content = "바, 방금 그거 봤어? 날아가는 수준이던데? 얼마나 빠른지 벽도 무너졌어!",
  ui_story_5033_50331401_80_dialog_content = "저기 봐! 구스타프도 왔어!",
  ui_story_5033_50331401_81_dialog_content = "다들 미안하네! 내가 많이 늦었군.",
  ui_story_5033_50331401_82_dialog_content = "구스타프 씨! 구스타프 씨가 중재를 좀 해 줘! 폴룩스랑 움브라톤에서 온 녀석들이...",
  ui_story_5033_50331401_83_dialog_content = "다들 잠시만 조용히 해 주게. 자세한 설명은 조금 뒤에 해 줄 테니.",
  ui_story_5033_50331401_84_dialog_content = "그 전에, 우선 이 사람들이 안으로 들어갈 수 있게 해 주게.",
  ui_story_5033_50331401_85_dialog_content = "......",
  ui_story_5033_50331401_86_dialog_content = "어? 뭐야?!",
  ui_story_5033_50331401_87_dialog_content = "너희가 왜 여기 있어?! 너 이 자식, 언제 나왔어?!",
  ui_story_5033_50331401_88_dialog_content = "PlayerName, 어서 교회로 들어가! 카스타가 이미 이성을 잃었어!",
  ui_story_5033_50331401_89_dialog_content = "<color=#e8d9bb>탕, 탕!</color>",
  ui_story_5033_50331401_90_dialog_content = "카스타...라는 이름이었지?",
  ui_story_5033_50331401_91_dialog_content = "<size=45>반격해! 날 얕보는 거야?!</size>",
  ui_story_5033_50331401_92_dialog_content = "난 아직 시간이 좀 더 필요해. 그러니 여기서 죽을 순 없어.\n그래도 널 다치게 만들진 않을 거야...",
  ui_story_5033_50331401_93_dialog_content = "넌 폴룩스한테 중요한 사람이니까...",
  ui_story_5033_50331401_94_dialog_content = "......",
  ui_story_5033_50331401_95_dialog_content = "너 같은 살인자가 계속 나불거리게 둘 것 같아?!",
  ui_story_5033_50331401_96_dialog_content = "멈춰! 카스타!",
  ui_story_5033_50331401_97_dialog_content = "<size=45>저리 비켜!</size>",
  ui_story_5033_50331401_98_dialog_content = "내 임무를 망치게 둘 순 없지... 이건 섀도우마스터의 명령이라고!",
  ui_story_5033_50331401_99_dialog_content = "그 여자는 생포해서 데리고 돌아가야 해!",
  ui_story_5033_50331401_100_dialog_content = "<size=45>꺼지라고 했잖아!</size>",
  ui_story_5033_50331401_101_dialog_content = "PlayerName, 일단 날 도와서 카스타를 막아!",
  ui_story_5033_50331402_1_dialog_content = "<color=#e8d9bb>콰지직! 퍼엉!</color>",
  ui_story_5033_50331402_2_dialog_content = "이, 이 자식...",
  ui_story_5033_50331402_3_dialog_content = "미안하다. 널 막으려면 진지하게 싸울 수밖에 없었어.",
  ui_story_5033_50331402_4_dialog_content = "살인자가 저기 있는데... 이게 뭐냐고... 지금 바로 내 눈앞에 있는데!",
  ui_story_5033_50331402_5_dialog_content = "그만해, 카스타.",
  ui_story_5033_50331402_6_dialog_content = "좀 진정이 됐니?",
  ui_story_5033_50331402_7_dialog_content = "폴룩스, 저 여자가 마틸다 수녀님을 죽였어...",
  ui_story_5033_50331402_8_dialog_content = "알아.",
  ui_story_5033_50331402_9_dialog_content = "저 여자가 죽였단 말이야...",
  ui_story_5033_50331402_10_dialog_content = "수녀님을 위해서 복수는 할 거야. 하지만 지금은 아니야.",
  ui_story_5033_50331402_11_dialog_content = "응, 모든 게 다 끝나고 나면 나도 속죄할 거야.",
  ui_story_5033_50331402_12_dialog_content = "안의 목숨을 가져가게 되는 사람이 있다면, 그건 바로 내가 될 거야. 알겠니?",
  ui_story_5033_50331402_13_dialog_content = "약속했어. 그렇게 하기로.",
  ui_story_5033_50331402_14_dialog_content = "폴룩스...",
  ui_story_5033_50331402_15_dialog_content = "애니... 아니, 안타레스 씨.",
  ui_story_5033_50331402_16_dialog_content = "PlayerName 씨, 와타리 씨. 또 만났네.",
  ui_story_5033_50331402_17_dialog_content = "안타레스 씨, 그 사건들 전부 당신이 한 짓이야?",
  ui_story_5033_50331402_18_dialog_content = "마틸다 수녀님을 살해한 것도...?",
  ui_story_5033_50331402_19_dialog_content = "다들 알아버린 모양이네.",
  ui_story_5033_50331402_20_dialog_content = "맞아, 내가 바로 당신들이 찾던 범인이야.",
  ui_story_5033_50331402_21_dialog_content = "사실 수녀도 아니야. 속여서 미안해.",
  ui_story_5033_50331402_22_dialog_content = "왜...왜 사람들을 죽였어? 그리고 왜 여기 있는 거야?",
  ui_story_5033_50331402_23_dialog_content = "<size=42>뭐야?! 그게 진짜야?!</size>",
  ui_story_5033_50331402_24_dialog_content = "왜 사람들이 또 소란스러워진 거지? 구스타프가 상황을 정리하겠다고 했을 텐데?",
  ui_story_5033_50331402_25_dialog_content = "잠깐만, 구스타프를 만났어?",
  ui_story_5033_50331402_26_dialog_content = "그렇다. 여기까지 같이 왔다만.",
  ui_story_5033_50331402_27_dialog_content = "구스타프는 지금 어디 있어?",
  ui_story_5033_50331402_28_dialog_content = "우리랑 함께 들어온 게 아니라서 거기까진 모른다.",
  ui_story_5033_50331402_29_dialog_content = "구스타프는 위험한 인간이야. 배후에서 이 모든 일을 꾸민 게 바로 그자거든.",
  ui_story_5033_50331402_30_dialog_content = "뭐라고? 꾸몄다고?",
  ui_story_5033_50331402_31_dialog_content = "내가 설명할게, 폴룩스.",
  ui_story_5033_50331402_32_dialog_content = "구스타프, 그게 진짜야?",
  ui_story_5033_50331402_33_dialog_content = "그래, 저 여자가 바로 폴룩스의 절친한 친구... 안타레스다.",
  ui_story_5033_50331402_34_dialog_content = "끼리끼리라더니, 빌어먹을... 저 여자는 왜 그런 짓을 한 거지?",
  ui_story_5033_50331402_35_dialog_content = "왜 일부러 우리와 움브라톤 사이를 이간질하는 거냐고!",
  ui_story_5033_50331402_36_dialog_content = "이번 일을 발판 삼아 유포리아와 움브라톤 사이의 이권을 손에 넣으려던 게 아닐까 싶네.",
  ui_story_5033_50331402_37_dialog_content = "움브라톤에서 왔다는 그 조사원들도 그냥 조사하는 시늉만 했겠지.",
  ui_story_5033_50331402_38_dialog_content = "이미 이 유포리아의 모든 것들에 값어치를 매겨 놨을지도 모른다.",
  ui_story_5033_50331402_39_dialog_content = "그런데 왜 안에서 자기들끼리 싸움이 붙은 거지? 내분이라도 생겼나?",
  ui_story_5033_50331402_40_dialog_content = "여러분, 죄송하지만 구스타프 씨와 따로 긴히 나눌 이야기가 있어서 잠깐 실례하겠습니다.",
  ui_story_5033_50331402_41_dialog_content = "어떻게 됐나?",
  ui_story_5033_50331402_42_dialog_content = "폴룩스와 카스타 두 사람 모두 안타레스를 처치하지 못했습니다.",
  ui_story_5033_50331402_43_dialog_content = "처치하지 못한 건가, 않은 건가?",
  ui_story_5033_50331402_44_dialog_content = "죄송합니다. 거기까진 파악하지 못했습니다.",
  ui_story_5033_50331402_45_dialog_content = "불가능해... 그 정도로 증오하는데 어째서... 정보는 확실한가?",
  ui_story_5033_50331402_46_dialog_content = "어쨌든 안타레스는 아직 살아 있습니다. 게다가...",
  ui_story_5033_50331402_47_dialog_content = "계속해.",
  ui_story_5033_50331402_48_dialog_content = "모든 사실을 털어놔 버린 것 같습니다.",
  ui_story_5033_50331402_49_dialog_content = "최악의 상황이 되었군...",
  ui_story_5033_50331402_50_dialog_content = "다음 계획은 어떻게 할까요?",
  ui_story_5033_50331402_51_dialog_content = "다음 계획이라...",
  ui_story_5033_50331402_52_dialog_content = "<color=#e8d9bb>우르릉──</color>",
  ui_story_5033_50331402_53_dialog_content = "마지막 계획을 어떻게 해야 할지는 알겠군.",
  ui_story_5033_50331402_54_dialog_content = "모두가 움직이게 만들어라.",
  ui_story_5033_50331402_55_dialog_content = "여기서 「레이븐즈 블러드」를 없애지 못하면 유포리아에 평온한 나날은\n영원히 찾아오지 않을 테니까.",
  ui_story_5033_50331501_1_dialog_content = "폴룩스! 나와! 유포리아의 배신자!",
  ui_story_5033_50331501_2_dialog_content = "폴룩스! 폴룩스!",
  ui_story_5033_50331501_3_dialog_content = "폴...",
  ui_story_5033_50331501_4_dialog_content = "으악, 지, 진짜 나왔어...",
  ui_story_5033_50331501_5_dialog_content = "누가 날 찾았지?",
  ui_story_5033_50331501_6_dialog_content = "............",
  ui_story_5033_50331501_7_dialog_content = "그래, 드디어 앞에 나설 마음이 들었나?",
  ui_story_5033_50331501_8_dialog_content = "구스타프, 아직도 정정하네. 매일 진을 마신 게 건강에 도움이 되긴 했나 봐?",
  ui_story_5033_50331501_9_dialog_content = "그럴 리가, 술은 그저 날 잠시 무뎌지게 만들어 줄 뿐이다.\n너도 알잖나. 이 유포리아엔 실망스러운 일들이 얼마나 많은지 말이야.",
  ui_story_5033_50331501_10_dialog_content = "네가 도망치지 않은 건 감탄했어.",
  ui_story_5033_50331501_11_dialog_content = "내가 어째서 도망쳐야 하지? 이곳의 모든 것은 내 손길을 기다리고 있다.\n유포리아는 이끌어 줄 주관자가 필요하다.",
  ui_story_5033_50331501_12_dialog_content = "<color=#e8d9bb>또각, 또각...</color>",
  ui_story_5033_50331501_13_dialog_content = "어이, 저 사람이 그 수녀인가?!",
  ui_story_5033_50331501_14_dialog_content = "무, 물러서. 구스타프가 저 여자는 완전히 미쳤다고 했어...",
  ui_story_5033_50331501_15_dialog_content = "자, 모두에게 소개해 줄게.",
  ui_story_5033_50331501_16_dialog_content = "움브라톤 연쇄 살인 사건의 범인이자, 유포리아의 죄인,\n「조직」의 쌍둥이별 중 하나였던 안타레스야.",
  ui_story_5033_50331501_17_dialog_content = "......",
  ui_story_5033_50331501_18_dialog_content = "대, 대놓고 인정하는 거냐?!",
  ui_story_5033_50331501_19_dialog_content = "절체절명의 순간에서도 그런 태도라니, 역시 폴룩스답군.",
  ui_story_5033_50331501_20_dialog_content = "그럼 네 소개도 해 보는 건 어떤가? 뒤에 숨어 모든 일을 조종한 주모자라는 정체도,\n방금처럼 깔끔하게 인정해 버리면 피차 수고도 덜 수 있지 않겠나.",
  ui_story_5033_50331501_21_dialog_content = "판을 제대로 짜 놨구나, 구스타프.",
  ui_story_5033_50331501_22_dialog_content = "근데 유감이지만 우리 범인이 진술을 하나 더 했거든. 들어 볼래?",
  ui_story_5033_50331501_23_dialog_content = "여기 모인 유포리아의 모든 주민들한테도 물어볼게. 당신들도 진상을 알고 싶어?",
  ui_story_5033_50331501_24_dialog_content = "너희 앞에 있는 이 구스타프 씨는 유포리아에서 흥신소를 하는 평범한 사람이 아니라...",
  ui_story_5033_50331501_25_dialog_content = "「조직」에서 대단한 지위를 가지고 있었던 사람이야.",
  ui_story_5033_50331501_26_dialog_content = "「조직」? 십몇 년 전에... 「보스」가 관리하던 조직 말하는 건가?",
  ui_story_5033_50331501_27_dialog_content = "그거 킬러를 육성하는 집단 아니었어? 구스타프 씨는 그냥 평범한 정보상인데?",
  ui_story_5033_50331501_28_dialog_content = "12년 전, 암귀의 침입 때문에 조직은 와해됐어.\n하지만 구스타프에게 그건 오히려 절호의 기회였지.",
  ui_story_5033_50331501_29_dialog_content = "구스타프는 유포리아를 자기 손에 넣기 위해, 정보상이라는 신분을 이용해서\n조금씩 클랜들을 포섭하고 질서를 재구축했어.",
  ui_story_5033_50331501_30_dialog_content = "그리고 더 중요한 건, 구스타프는 치명적인 살인 병기를 가지고 있었다는 거야...",
  ui_story_5033_50331501_31_dialog_content = "바로 <color=#FFB400>안타레스</color>라는 병기를.",
  ui_story_5033_50331501_32_dialog_content = "뭐라고? 저 수녀가 구스타프 쪽 사람이라는 거야?",
  ui_story_5033_50331501_33_dialog_content = "수년간, 안타레스는 구스타프에게 수많은 지령을 받고,\n유포리아의 이권을 장악하고 있던 사람들을 제거해 왔어.",
  ui_story_5033_50331501_34_dialog_content = "그리고 움브라톤의 분노를 뒤집어써 줄 사람이 필요했지.\n그래서 그 애한테 이곳으로 돌아와 날 없애라는 마지막 명령을 내린 거야...",
  ui_story_5033_50331501_35_dialog_content = "아니면 우리가 서로 싸우다 함께 죽길 바랐다는 게 더 맞는 말이겠네.",
  ui_story_5033_50331501_36_dialog_content = "뭔가... 엄청 그럴싸한데?",
  ui_story_5033_50331501_37_dialog_content = "아니지, 증거는 하나도 없고 다 말뿐이잖아!",
  ui_story_5033_50331501_38_dialog_content = "근데 그건 구스타프도 마찬가지 아냐?\n구스타프가 정보상이라고 해서 하는 말을 다 믿으면 안 되는 거잖아...",
  ui_story_5033_50331501_39_dialog_content = "망할, 설마 진짜로 우릴 이용한 거야?",
  ui_story_5033_50331501_40_dialog_content = "<size=45>폴룩스! 적당히 해라!</size>",
  ui_story_5033_50331501_41_dialog_content = "여기 사람들은 바보가 아니다. 네 거짓말에 속아 넘어가 줄 사람은 아무도 없다.",
  ui_story_5033_50331501_42_dialog_content = "이렇게 날 몰아가서 배후에서 일을 꾸민 네 죄를 떠넘기려는 수작이겠지.",
  ui_story_5033_50331501_43_dialog_content = "내가 무슨 짓들을 했는지는 네가 더 잘 알 거야.\n증거가 없다고 해도, 넌 대가를 치러야 해!",
  ui_story_5033_50331501_44_dialog_content = "수녀 아가씨, 지금 자기가 무슨 말을 한 건지는 아나? 이거 내가 다 난감하군.",
  ui_story_5033_50331501_45_dialog_content = "궁지에 빠진 쥐는 고양이를 문다지.\n이 늙은이를 죽이는 게 너희 마지막 계획이라면 어디 해 봐라!",
  ui_story_5033_50331501_46_dialog_content = "너희가 정말로 증거를 가지고 있다면, 나도 결코 피하진 않을 테니 말이다!",
  ui_story_5033_50331501_47_dialog_content = "<size=45>증거라면 있다!</size>",
  ui_story_5033_50331501_48_dialog_content = "바로 여기! 내가 가지고 있어!",
  ui_story_5033_50331501_49_dialog_content = "네코야시키?!",
  ui_story_5033_50331501_50_dialog_content = "...?!",
  ui_story_5033_50331501_51_dialog_content = "저리 비켜! 지나가게 좀 비키라고!",
  ui_story_5033_50331501_52_dialog_content = "증거 가져오라며? 구스타프! 여기 증거가 있다고!",
  ui_story_5033_50331501_53_dialog_content = "움브라톤에서 방금 보낸 정보야. 살인 사건에서 살아남은 피해자의 증언이 담겨 있어!",
  ui_story_5033_50331501_54_dialog_content = "살아남은... 피해자라고?!",
  ui_story_5033_50331501_55_dialog_content = "......",
  ui_story_5033_50331501_56_dialog_content = "범인은 바로 저 수녀야! 그리고 이 모든 것을 꾸민 자는 바로──",
  ui_story_5033_50331501_57_dialog_content = "<size=45>구스타프 당신이야!</size>",
  ui_story_5033_50331501_58_dialog_content = "그럴 리가... 그 기술에서 살아남을 수 있는 사람은 없을 텐데!",
  ui_story_5033_50331501_59_dialog_content = "그건 조작된 증거다!",
  ui_story_5033_50331501_60_dialog_content = "가짜 정보다! 너희들끼리 한통속이 돼서 날 상대하겠다는 거냐?!",
  ui_story_5033_50331501_61_dialog_content = "「지미 오덴커크. 47세... 중상을 입고 혼수상태에 빠져 있다 깨어남...」",
  ui_story_5033_50331501_62_dialog_content = "「...설명에 따르면 범인은 수녀로 분장한 킬러로, 회색 머리카락에...」",
  ui_story_5033_50331501_63_dialog_content = "그만...",
  ui_story_5033_50331501_64_dialog_content = "「사건 당일 유포리아의 구스타프에게 초대를 받고 이동하던 중...\n함정에 빠져 참변을 당해...」",
  ui_story_5033_50331501_65_dialog_content = "그만! 그런 헛소리는 집어치워!",
  ui_story_5033_50331501_66_dialog_content = "당신이 아직도 인정을 못 하겠다면, 같이 섀도우마스터한테 가서 대질 신문을 받으면 돼!",
  ui_story_5033_50331501_67_dialog_content = "그때 가서 너희 공범이 뭐라고 둘러댈지 보자고!",
  ui_story_5033_50331501_68_dialog_content = "네 장난 받아 줄 시간 따윈 없다!\n다들 멍하게 서 있지만 말고 네코야시키와 다른 배신자들을 잡아!",
  ui_story_5033_50331501_69_dialog_content = "......",
  ui_story_5033_50331501_70_dialog_content = "다들 내 말 못 들었나?",
  ui_story_5033_50331501_71_dialog_content = "네코야시키, 그게 진짜야?",
  ui_story_5033_50331501_72_dialog_content = "아니면 섣불리 판단하지 말고 다들 좀 더 상황을 지켜보자고...\n사건이 반전의 연속이니 원...",
  ui_story_5033_50331501_73_dialog_content = "구스타프 표정 좀 봐... 완전 썩었잖아.",
  ui_story_5033_50331501_74_dialog_content = "이게 무슨 웃기지도 않는 소리냐...",
  ui_story_5033_50331501_75_dialog_content = "이 쓰레기 녀석들! 너희들의 진짜 주인이 누군지 모르는 거냐!",
  ui_story_5033_50331501_76_dialog_content = "움브라톤 놈들이 이곳을 어떻게 망쳐 왔는지 전부 잊어버렸냔 말이다!",
  ui_story_5033_50331501_77_dialog_content = "저놈이 지금 무슨 소리야? 네가 뭐 우리 주인이라도 된다는 소리냐?!",
  ui_story_5033_50331501_78_dialog_content = "어이, 구스타프! 이게 다 무슨 짓거린지 제대로 설명해!",
  ui_story_5033_50331501_79_dialog_content = "그리고 이 어중이떠중이들도 설마 너랑 한패냐?!",
  ui_story_5033_50331501_80_dialog_content = "나, 난 모르는 일이야... 난 저 사람이랑 아무 상관도 없어!",
  ui_story_5033_50331501_81_dialog_content = "허허... 흐하하하!",
  ui_story_5033_50331501_82_dialog_content = "그래, 이건 다 너희가 자초한 거다.",
  ui_story_5033_50331501_83_dialog_content = "전부 너희가 자초한 거라고!",
  ui_story_5033_50331501_84_dialog_content = "<color=#e8d9bb>철커덩... 철커덩...</color>",
  ui_story_5033_50331501_85_dialog_content = "어? 다크매터가 느껴져...",
  ui_story_5033_50331501_86_dialog_content = "<anim type=Shake><size=45>그어어어!</size></anim>",
  ui_story_5033_50331501_87_dialog_content = "이런! 암귀다!",
  ui_story_5033_50331501_88_dialog_content = "자, 구속을 풀었다... 이제 네 동료들을 불러 실컷 날뛰어 봐라!",
  ui_story_5033_50331501_89_dialog_content = "<anim type=Shake><size=45>크아아──!</size></anim>",
  ui_story_5033_50331501_90_dialog_content = "암귀다! 여기도 저기도 온통 다 암귀야!",
  ui_story_5033_50331501_91_dialog_content = "망할, 다 어디서 기어 나온 거야?! 도망칠 길이 없어!",
  ui_story_5033_50331501_92_dialog_content = "이 망할 자식! 암귀를 풀어?!\n놈들이 더 많은 암귀를 끌어들일 거야!",
  ui_story_5033_50331501_93_dialog_content = "오, 오지 마! 으아아악!",
  ui_story_5033_50331501_94_dialog_content = "구스타프! 우리 좀 살려 줘!",
  ui_story_5033_50331501_95_dialog_content = "미안하게 됐군, 여러분. 이제 난 유포리아를...",
  ui_story_5033_50331501_96_dialog_content = "깨끗히 씻어낼 거다.",
  ui_story_5033_50331502_1_dialog_content = "으아악! 사, 살려 줘!",
  ui_story_5033_50331502_2_dialog_content = "다리가, 다리가 안 움직여!",
  ui_story_5033_50331502_3_dialog_content = "그만 소리 질러. 그냥 겉만 다친 거잖아.",
  ui_story_5033_50331502_4_dialog_content = "이쪽에 있던 암귀들은 다 해치웠으니까, 얼른 네 동료들이 있는 곳으로 꺼져.",
  ui_story_5033_50331502_5_dialog_content = "저, 정말... 고마워...",
  ui_story_5033_50331502_6_dialog_content = "고맙다는 말은 폴룩스한테 해. 너희들이 교회를 폭파시키려고 했는데도,\n저렇게 고생하면서 너흴 구해주려고 하고 있으니까.",
  ui_story_5033_50331502_7_dialog_content = "와타리 씨! 왼쪽!",
  ui_story_5033_50331502_8_dialog_content = "젠장! 왜 또 있는 거냐?!",
  ui_story_5033_50331502_9_dialog_content = "모르겠어. 아마 이 근처에 있던 암귀들이 다 몰려와서 그런 거 아닐까?",
  ui_story_5033_50331502_10_dialog_content = "안타레스는? 안타레스 봤어?",
  ui_story_5033_50331502_11_dialog_content = "사람들이랑 암귀들이 너무 많아서 엉망진창이야! 감응해서 찾아볼게!",
  ui_story_5033_50331502_12_dialog_content = "야! 폴룩스 봤어?",
  ui_story_5033_50331502_13_dialog_content = "못 봤어. 우리도 지금...",
  ui_story_5033_50331502_14_dialog_content = "여기 말고 다른 쪽에 있었어! 저쪽이야!",
  ui_story_5033_50331502_15_dialog_content = "구스타프는? 설마 도망친 건 아니겠지?",
  ui_story_5033_50331502_16_dialog_content = "아! 기다려, 구스타프!",
  ui_story_5033_50331502_17_dialog_content = "비켜, 다 저리 비키라고...",
  ui_story_5033_50331502_18_dialog_content = "<anim type=Shake><size=45>캬아악──</size></anim>",
  ui_story_5033_50331502_19_dialog_content = "으악!",
  ui_story_5033_50331502_20_dialog_content = "안타레스.",
  ui_story_5033_50331502_21_dialog_content = "구스타프, 이 암귀들은 당신이 풀어놓은 거야?",
  ui_story_5033_50331502_22_dialog_content = "사람들을 전부 당신 길동무로 만들고 싶어?",
  ui_story_5033_50331502_23_dialog_content = "뭐냐, 녀석들한테 동정심이라도 드는 거냐?",
  ui_story_5033_50331502_24_dialog_content = "동정심? 미안하지만 난 저 녀석들 목숨엔 관심 없어.",
  ui_story_5033_50331502_25_dialog_content = "넌 정말이지 인정이라곤 없는 녀석이야,\n안테라스. 역시 그 시절 쌍둥이별 중 하나답단 말이지...",
  ui_story_5033_50331502_26_dialog_content = "그런데 네 방금 전 행동은 정말 이해가 가질 않는군.",
  ui_story_5033_50331502_27_dialog_content = "아직도 네가 속죄할 수 있을 거라 생각하나?",
  ui_story_5033_50331502_28_dialog_content = "모두 앞에 서서 날 원흉으로 지목하고, 정의니 뭐니 떠벌리고 나면,\n네가 정말로 용서받을 수 있을 것 같나?",
  ui_story_5033_50331502_29_dialog_content = "...그런 건 바라지도 않아.",
  ui_story_5033_50331502_30_dialog_content = "넌 지옥에 떨어질 거다! 그리고 지옥에 떨어지는 건 너 하나다!",
  ui_story_5033_50331502_31_dialog_content = "내가 해 온 모든 일들은 다 유포리아를 위해서였다...\n넌 아무것도 몰라! 이해조차 하지 못하겠지!",
  ui_story_5033_50331502_32_dialog_content = "네 눈에 들어오는 건 고작 우정과 인연 같은 시시하고 별것도 아닌 것들뿐이지.\n넌 결코 내가 보는 시야를 알 수 없단 말이다!",
  ui_story_5033_50331502_33_dialog_content = "12년 전부터 유포리아는 시궁창이었다! 안타레스!",
  ui_story_5033_50331502_34_dialog_content = "움브라톤 녀석들은 우리가 사는지 죽는지 신경도 쓰지 않는다.\n그리고 이 지역 놈들은 자신들의 터전을 재건하려는 일말의 근성도 없어!",
  ui_story_5033_50331502_35_dialog_content = "유포리아를 위해 나설 수 있는 사람은 오직 나뿐이다! 알겠냔 말이다!",
  ui_story_5033_50331502_36_dialog_content = "병든 육체를 치료하려면 반드시 썩어 버린 살점을 도려내고,\n상처 위의 구더기들을 긁어내야만 하지...",
  ui_story_5033_50331502_37_dialog_content = "넌 내 칼이었다, 안타레스. 아주 잘 드는 칼이었지...",
  ui_story_5033_50331502_38_dialog_content = "오늘이 지나면, 유포리아는 다시 태어날 거야.",
  ui_story_5033_50331502_39_dialog_content = "단지 우리 둘은 그 모습을 볼 수 없겠지만 말이야.",
  ui_story_5033_50331502_40_dialog_content = "......",
  ui_story_5033_50331502_41_dialog_content = "<color=#e8d9bb>치잉──</color>",
  ui_story_5033_50331502_42_dialog_content = "구스타프, 무기 내려놔. 이렇게 된 이상 이제 당신에게 승산은 없어.",
  ui_story_5033_50331502_43_dialog_content = "드디어 왔군, 폴룩스. 오히려... 잘됐다.",
  ui_story_5033_50331502_44_dialog_content = "더 일찍 나섰어야지. 네 그 따뜻한 교회 안에 처박혀 있을 게 아니라,\n시체가 즐비한 거리로 말이다.",
  ui_story_5033_50331502_45_dialog_content = "하고 싶은 말이 뭐야?",
  ui_story_5033_50331502_46_dialog_content = "하하하...",
  ui_story_5033_50331502_47_dialog_content = "유포리아를 팔아넘기지 마라, 폴룩스. 절대 저버리지 마라.",
  ui_story_5033_50331502_48_dialog_content = "만약 기어이 팔아야겠다면...",
  ui_story_5033_50331502_49_dialog_content = "반드시 제값을 받아내라.",
  ui_story_5033_50331502_50_dialog_content = "구스타프, 뭘 어쩌려는 거야?!",
  ui_story_5033_50331502_51_dialog_content = "너희 손을 빌릴 필요도 없다... 내 삶의 결말은 내 손으로 마무리 짓는다!",
  ui_story_5033_50331502_52_dialog_content = "난 「보스」처럼 존엄이 짓밟힌 채로 죽진 않을 거다... 절대...",
  ui_story_5033_50331502_53_dialog_content = "크억!",
  ui_story_5033_50331502_54_dialog_content = "...죽었어.",
  ui_story_5033_50331502_55_dialog_content = "구스타프한테 쓰려고 다른 살인 기술도 준비해 뒀었는데. 너무 편하게 죽게 만들었잖아.",
  ui_story_5033_50331502_56_dialog_content = "그럼 못다 한 기술은 <color=#FFB400>다른 사람</color>한테 쓰는 수밖에 없겠네.",
  ui_story_5033_50331502_57_dialog_content = "다른 사람?",
  ui_story_5033_50331502_58_dialog_content = "폴룩스, 저 아래 횃불과 화염병을 들고 있는 사람들 보여?",
  ui_story_5033_50331502_59_dialog_content = "얼굴들은 잘 안 보이지만, 나한테 저 사람들은 하나같이 추하고 어리석고,\n구제될 수 없는 자들로밖에 안 보여.",
  ui_story_5033_50331502_60_dialog_content = "안, 이제 다 끝났어. 네가 움브라톤에 가서 죗값만 치르고 나면...",
  ui_story_5033_50331502_61_dialog_content = "구스타프가 했던 말 중에, 딱 한 마디는 아주 일리 있었어.",
  ui_story_5033_50331502_62_dialog_content = "우리는 모두 유포리아의 궤양이야.\n더럽고, 치료할 수 없는 상처야.",
  ui_story_5033_50331502_63_dialog_content = "그러니까 진정한 의미로 다시 태어나기 위해선,\n이런 환부들은 모조리 잘라내 버려야 해.",
  ui_story_5033_50331502_64_dialog_content = "너... 뭘 하려는 거야?",
  ui_story_5033_50331502_65_dialog_content = "「사신」의 임무를 완수할 거야.",
  ui_story_5033_50331502_66_dialog_content = "이런... 그럼 우린... 살려줘! 어서 도망쳐!",
  ui_story_5033_50331502_67_dialog_content = "안타레스!",
  ui_story_5033_50331502_68_dialog_content = "폴룩스, 넌 항상 마음이 너무 여려.\n그러니까 내가 너한테 몇 년 동안 하나도 변하지 않았다고 했던 거야.",
  ui_story_5033_50331502_69_dialog_content = "중병에는 독한 약을 쓸 수밖에 없어.",
  ui_story_5033_50331502_70_dialog_content = "<color=#e8d9bb>휙──</color>",
  ui_story_5033_50331502_71_dialog_content = "뭔가 날아오고 있잖아?! 어서 피해!",
  ui_story_5033_50331502_72_dialog_content = "<color=#e8d9bb>탕!</color>",
  ui_story_5033_50331502_73_dialog_content = "완전히 미쳤어. 어떻게 아무 죄 없는 시민들을 공격할 수 있어?!",
  ui_story_5033_50331502_74_dialog_content = "카스타! 살려줘! 얼른 저 수녀 좀 막아 봐!",
  ui_story_5033_50331502_75_dialog_content = "폴룩스! 빨리 어떻게 좀 해 봐!",
  ui_story_5033_50331502_76_dialog_content = "......",
  ui_story_5033_50331502_77_dialog_content = "안, 네가 뭘 하려는 건지 알겠어. 하지만 그러지 마... 그렇게 안 해도 돼.",
  ui_story_5033_50331502_78_dialog_content = "이미 말했잖아.",
  ui_story_5033_50331502_79_dialog_content = "그리고 아까 그 남자는 내가 범죄를 저질렀다는 확실한 증거를 전부 공개해 버렸어...",
  ui_story_5033_50331502_80_dialog_content = "설령 내가 유포리아의 대청소를 할 생각이 없더라도,\n목격자들을 살아서 돌려보낼 순 없어.",
  ui_story_5033_50331502_81_dialog_content = "그만 말해... 안... 제발...",
  ui_story_5033_50331502_82_dialog_content = "그럼 나랑 가장 가까이 있는 사람부터 시작해야겠네.",
  ui_story_5033_50331502_83_dialog_content = "으악! 다, 다들 물러서!",
  ui_story_5033_50331502_84_dialog_content = "그리고 날 막을 수 있는 건 너뿐이야.",
  ui_story_5033_50331502_85_dialog_content = "준비됐어?",
  ui_story_5033_50331502_86_dialog_content = "꼭 이래야겠어?!",
  ui_story_5033_50331502_87_dialog_content = "<size=30>난 끌려갈 수 없어, 폴룩스. 난 유포리아에 남고 싶어.\n그래서 나만의 방식을 쓸 거야.</size>",
  ui_story_5033_50331502_88_dialog_content = "<size=30>내가 저지른 죄를 깨끗이 갚을 수 있는, 내가 마지막으로 할 수 있는 방식 말이야.</size>",
  ui_story_5033_50331502_89_dialog_content = "......",
  ui_story_5033_50331502_90_dialog_content = "이제 됐어.",
  ui_story_5033_50331502_91_dialog_content = "나도 겉만 번지르르한 사람은 아니야, 안.",
  ui_story_5033_50331502_92_dialog_content = "이건 그저 마틸다 수녀님을 위해서일 뿐이야.",
  ui_story_5033_50331502_93_dialog_content = "물론이지, 내가 이러는 것도 마틸다 수녀님을 위해서인걸.",
  ui_story_5033_50331502_94_dialog_content = "그 여자를 쓰러트려, 폴룩스! 유포리아를 위해서!",
  ui_story_5033_50331502_95_dialog_content = "유포리아! 유포리아를 위해!",
  ui_story_5033_50331502_96_dialog_content = "시작하자. 오랜만이라고 네 움직임이 서투르진 않았으면 좋겠네.",
  ui_story_5033_50331502_97_dialog_content = "걱정 마. 아직 요령들은 다 기억하고 있으니까. 단 한 번도 잊어 본 적 없어...",
  ui_story_5033_50331502_98_dialog_content = "마지막으로 하나만 물어볼게, 안.",
  ui_story_5033_50331502_99_dialog_content = "후훗, 그래.",
  ui_story_5033_50331502_100_dialog_content = "만약 두 번째 기회가 주어진다면, 넌 그래도 그렇게 할 거니?",
  ui_story_5033_50331502_101_dialog_content = "구스타프를 위해 했던 일들...?",
  ui_story_5033_50331502_102_dialog_content = "아니, 14년 전 그때 말이야.",
  ui_story_5033_50331502_103_dialog_content = "다시 그때로 돌아가도, 내 칼에 뛰어들 거야?",
  ui_story_5033_50331502_104_dialog_content = "그럴 거야. 두 번째 기회가 주어진다고 해도, 난 여전히 너한테 뛰어들 거야.",
  ui_story_5033_50331502_105_dialog_content = "그리고 널 꼭 끌어안고, 작별 인사를 할 거야.",
  ui_story_5033_50331502_106_dialog_content = "지금처럼...",
  ui_story_5033_50331502_107_dialog_content = "<color=#e8d9bb>푸욱──</color>",
  ui_story_5033_50331502_108_dialog_content = "......",
  ui_story_5033_50331502_109_dialog_content = "그때보다... 눈빛에 흔들림이 많이 없어졌네...",
  ui_story_5033_50331502_110_dialog_content = "변했구나... 폴룩스. 정말 다행이야...",
  ui_story_5033_50331502_111_dialog_content = "그리고... 그 단도, 계속 가지고 있어 줬구나...",
  ui_story_5033_50331502_112_dialog_content = "이제 안 가지고 있을 거야. 오늘 이후론 묻어 버릴 거니까.",
  ui_story_5033_50331502_113_dialog_content = "안녕, 나의 폴룩스.",
  ui_story_5033_50331502_114_dialog_content = "안녕... 죄 많은 안타레스.",
  ui_story_5033_50331502_115_dialog_content = "이제, 드디어 나도 너와 같아졌어.",
  ui_story_5033_50331502_116_dialog_content = "폴룩스──!",
  ui_story_5033_50331502_117_dialog_content = "?!",
  ui_story_5033_50331502_118_dialog_content = "...안타레스? 그리고 구스타프?!",
  ui_story_5033_50331502_119_dialog_content = "......",
  ui_story_5033_50331502_120_dialog_content = "폴룩스, 괜찮아?",
  ui_story_5033_50331502_121_dialog_content = "............",
  ui_story_5033_50331502_122_dialog_content = "와타리 씨, 확인 좀 부탁해도 될까?",
  ui_story_5033_50331502_123_dialog_content = "구스타프는 이미 사망했다. 그럼 안테라스 쪽을...",
  ui_story_5033_50331502_124_dialog_content = "그럴 필요 없어.",
  ui_story_5033_50331502_125_dialog_content = "뭐?",
  ui_story_5033_50331502_126_dialog_content = "그럴 필요 없다고, 의사 선생.",
  ui_story_5033_50331502_127_dialog_content = "당신 임무는... 이미 <color=#FFB400>실패</color>했으니까.",
  ui_story_5033_50331502_128_dialog_content = "<color=#e8d9bb>우르릉──</color>",
  ui_story_5033_50331601_1_dialog_content = "<color=#e8d9bb>몇 시간 뒤</color>",
  ui_story_5033_50331601_2_dialog_content = "...그러니까 정말 구스타프가 배후의 주모자였던 거구나.",
  ui_story_5033_50331601_3_dialog_content = "내가 전부터 그놈이 우릴 이용하고 있다고 했잖아. 그땐 아무도 안 믿더니, 어휴.",
  ui_story_5033_50331601_4_dialog_content = "그 수녀 암살자도 죽었다는 모양이야. 폴룩스가 직접 처리했다던데.",
  ui_story_5033_50331601_5_dialog_content = "역시 폴룩스야... 폴룩스가 있어서 다행이야...",
  ui_story_5033_50331601_6_dialog_content = "그 두 사람은 소꿉친구 사이였다던데, 대의를 위해 친구까지 직접 처치했다는 거야?",
  ui_story_5033_50331601_7_dialog_content = "뒤에서 쓸데없는 소리들 좀 하지 마.",
  ui_story_5033_50331601_8_dialog_content = "그렇게 할 일이 없으면 교회 벽이랑 창문이나 고쳐 놔.\n애들은 계속 교회에서 지내야 하니까.",
  ui_story_5033_50331601_9_dialog_content = "사람이 나잇값을 하라고. 자기가 저지른 건 자기가 수습해.",
  ui_story_5033_50331601_10_dialog_content = "아, 알겠어...",
  ui_story_5033_50331601_11_dialog_content = "네코야시키 오빠, 다들 일단 교회로 돌아왔고, 짐도 다 풀었어.",
  ui_story_5033_50331601_12_dialog_content = "잘했어, 라탄.",
  ui_story_5033_50331601_13_dialog_content = "저기... 폴룩스 언니는? 다들 많이 걱정하는데...",
  ui_story_5033_50331601_14_dialog_content = "폴룩스는... 마무리 지을 일이 있어서 카스타랑 처리하는 중이야.",
  ui_story_5033_50331601_15_dialog_content = "교회 뒤에 있는 언덕에 간 거니까 금방 돌아올 거야.\n아직 밖에 비 오니까, 넌 일단 교회 안에 들어가 있어.",
  ui_story_5033_50331601_16_dialog_content = "네코야시키 오빠, 비는 벌써 다 그쳤어.",
  ui_story_5033_50331601_17_dialog_content = "「...그녀는 지난날의 고단한 여행을 마치고 새로운 여정을 떠났습니다.」",
  ui_story_5033_50331601_18_dialog_content = "「산과 계곡으로 돌아가, 호수로 흘러들어...」",
  ui_story_5033_50331601_19_dialog_content = "「온 하늘을 자유롭게 수놓는 무수한 별이 될 것입니다.」",
  ui_story_5033_50331601_20_dialog_content = "......",
  ui_story_5033_50331601_21_dialog_content = "날이 개었어, 폴룩스.",
  ui_story_5033_50331601_22_dialog_content = "앗, 눈부셔... 햇빛이 이렇게 강했었나...",
  ui_story_5033_50331601_23_dialog_content = "안개도 다 걷혔어. 유포리아의 진짜 모습은 이렇게 생겼던 거구나.",
  ui_story_5033_50331601_24_dialog_content = "PlayerName, 안을 위해 마지막 추도사를 읽어 줘서 고마워.",
  ui_story_5033_50331601_25_dialog_content = "그러고 보면 교회에서 한참을 지냈으면서 이런 것도 할 줄 모르다니, 조금 부끄럽네.",
  ui_story_5033_50331601_26_dialog_content = "그냥 입이 떨어지지 않는 거겠죠.",
  ui_story_5033_50331601_27_dialog_content = "어쩌면 매일 수많은 사람에게 들려주는 평범한 추도사는 안타레스 씨한테\n어울리지 않아서 그런 걸지도 몰라요.",
  ui_story_5033_50331601_28_dialog_content = "너무 슬퍼하진 마세요.",
  ui_story_5033_50331601_29_dialog_content = "슬프진 않아. 오히려 개운해.",
  ui_story_5033_50331601_30_dialog_content = "마치 혼란스러운 꿈속에서 앞으로 다신 못 볼 사람을 만나고 온 것처럼 말이야.",
  ui_story_5033_50331601_31_dialog_content = "이젠 그 꿈에서 깨어났고, 날도 개었으니 계속 내 길을 걸어 나가야겠지.",
  ui_story_5033_50331601_32_dialog_content = "그럼 이제부터 어떻게 할 계획인데요?",
  ui_story_5033_50331601_33_dialog_content = "계속 여기 머물 생각이야.",
  ui_story_5033_50331601_34_dialog_content = "교회 아이들뿐만 아니라, 어렵사리 맑은 하늘을 맞이하게 된 유포리아를 위해서.",
  ui_story_5033_50331601_35_dialog_content = "아마 안타레스 씨도 이런 모습을 보고 싶어 했을 거예요.",
  ui_story_5033_50331601_36_dialog_content = "그럴지도 모르겠네. 아마 그 애는 내 손으로 자신이 저지른 죄를\n씻고 싶어 했던 걸 수도 있겠어.",
  ui_story_5033_50331601_37_dialog_content = "정말 약아빠졌다니까.",
  ui_story_5033_50331601_38_dialog_content = "14년 전에 그 아이가 진짜로 죽어서, 다른 사람에게 이용당하지 않았다면...",
  ui_story_5033_50331601_39_dialog_content = "우리가 서로의 목숨을 노릴 필요 없이, 계속 쌍둥이별로 있을 수 있었다면...",
  ui_story_5033_50331601_40_dialog_content = "차라리 우리가 처음부터 아예 모르는 사이가 돼서...",
  ui_story_5033_50331601_41_dialog_content = "안타레스, 폴룩스라는 남남으로 있을 수 있었다면...",
  ui_story_5033_50331601_42_dialog_content = "우리의 결말도 달라질 수 있었을까?",
  ui_story_5033_50331601_43_dialog_content = "유포리아는 어떤 새로운 운명을 맞이했을까?",
  ui_story_5033_50331601_44_dialog_content = "폴룩스, 과거를 그리워하는 건 너랑 안 어울려.",
  ui_story_5033_50331601_45_dialog_content = "맞아. 과거랑 작별하겠다고 단단히 마음먹었는데...",
  ui_story_5033_50331601_46_dialog_content = "이젠 나 대신 저 단검이랑 수국 브로치가...",
  ui_story_5033_50331601_47_dialog_content = "안타레스의 곁에 있어 줄 거야.",
  ui_story_5033_50331601_48_dialog_content = "그러고 보니까 올해는 아직 마틸다 수녀님한테 안 가 봤네.",
  ui_story_5033_50331601_49_dialog_content = "그러게, 이쪽 일이 마무리되고 나면 시간 내서 움브라톤에 갔다 오자.",
  ui_story_5033_50331601_50_dialog_content = "그럼 전 가 볼게요. 안녕히 계세요, 폴룩스 씨. 안녕, 카스타.",
  ui_story_5033_50331601_51_dialog_content = "혼자서 비공정 셔틀허브까지 가려고?",
  ui_story_5033_50331601_52_dialog_content = "지금 다들 정신없이 이리저리 다니고 있어서,\n거기까지 가는 길이 그리 편하진 않을 거야.",
  ui_story_5033_50331601_53_dialog_content = "근데 와타리 씨가 즉시 보고해야 한다면서 혼자 움브라톤으로 가 버렸는걸요...",
  ui_story_5033_50331601_54_dialog_content = "내가 같이 가 줄게.",
  ui_story_5033_50331601_55_dialog_content = "그래, 카스타랑 같이 가.",
  ui_story_5033_50331601_56_dialog_content = "난 아직... 처리해야 할 일들이 있으니까, 배웅은 여기서 할게.",
  ui_story_5033_50331601_57_dialog_content = "유포리아가 진정한 낙원으로 변하고 나면, 우리도 다시 만날 수 있을 거야, PlayerName.",
  ui_story_5033_50331601_58_dialog_content = "네, 폴룩스 씨. 저도 그날을 기대할게요.",
  ui_story_5033_50331601_59_dialog_content = "<color=#e8d9bb>이틀 뒤, 움브라톤</color>",
  ui_story_5033_50331601_60_dialog_content = "신문 사세요! 움브라톤 연쇄 살인 사건이 해결됐어요!\n범인은 체포 과정 중 사망했대요!",
  ui_story_5033_50331601_61_dialog_content = "와타리 씨? 신문 하나만 사 줘.",
  ui_story_5033_50331601_62_dialog_content = "날 어떻게 알아본 거냐.",
  ui_story_5033_50331601_63_dialog_content = "얼른 저리 가.",
  ui_story_5033_50331601_64_dialog_content = "아, 알겠다고, 뭘 그렇게 사납게 굴고 그래.\n신문 사세요!",
  ui_story_5033_50331601_65_dialog_content = "............",
  ui_story_5033_50331601_66_dialog_content = "늦었군.",
  ui_story_5033_50331601_67_dialog_content = "카스타가 비공정 운전에 서툴러서.",
  ui_story_5033_50331601_67X1_dialog_content = "따라와.",
  ui_story_5033_50331601_68_dialog_content = "<color=#e8d9bb>휘릭──</color>",
  ui_story_5033_50331601_69_dialog_content = "이건...?",
  ui_story_5033_50331601_70_dialog_content = "사건 종결 관련 서류다. 섀도우마스터께서도 확인하셨다.\n대체로 우리가 설명한 내용대로 결론이 났지.",
  ui_story_5033_50331601_71_dialog_content = "그래, 고마워, 와타리 씨.",
  ui_story_5033_50331601_72_dialog_content = "나한테 제대로 고마워해야 할 거야.",
  ui_story_5033_50331601_73_dialog_content = "난 임무를 수행하러 가 놓고 용의자 둘, 아니, 범인 둘 중 아무도 못 데리고 왔다고.",
  ui_story_5033_50331601_74_dialog_content = "하하, 운이 없었네.",
  ui_story_5033_50331601_75_dialog_content = "그걸 말이라고...",
  ui_story_5033_50331601_76_dialog_content = "됐어. 이쯤 하자고. 계속 페이지를 넘겨 봐, 서류 하나가 있을 거니까.",
  ui_story_5033_50331601_77_dialog_content = "섀도우마스터가 당신과 함께 유포리아를 재건하고 싶다는 내용의 제안서다.\n문제가 있는지 한 번 읽어 봐.",
  ui_story_5033_50331601_78_dialog_content = "구스타프가 죽어서 그쪽도 엉망이겠지.",
  ui_story_5033_50331601_79_dialog_content = "움브라톤에 있는 여러 클랜의 생계도 유포리아에 달려 있으니까,\n이제부터 새로운 방법을 생각해 내야만 해.",
  ui_story_5033_50331601_80_dialog_content = "섀도우마스터는 옛 방법을 그대로 따르길 원치 않으신다.\n그렇게 된다면 그 글러먹은 조직 놈들과 다를 게 없을 테니까, 이해하겠지?",
  ui_story_5033_50331601_81_dialog_content = "동의해. 나도 그렇게 생각하거든.",
  ui_story_5033_50331601_82_dialog_content = "이미 오래전에 썩어 버린 살점을 도려내 버리고, 새롭게 시작할 때가 됐어.",
  ui_story_5033_50331601_83_dialog_content = "나쁘지 않은 비유군. 유포리아는 환자 같은 곳이다.\n이제 겨우 괴사해 버린 부분들을 잘라 냈으니...",
  ui_story_5033_50331601_84_dialog_content = "새로운 약을 넣어 건강한 새살이 돋아나게 만들어야겠지.",
  ui_story_5033_50331601_85_dialog_content = "그래, 움브라톤이 가져다준 재건 계획이 바로 그 새로운 약이 돼 줄 거야.",
  ui_story_5033_50331601_86_dialog_content = "그렇게 하면 아이들도 새살처럼 건강하게 성장할 수 있겠지.",
  ui_story_5033_50331601_87_dialog_content = "와타리 씨, 그 계획엔 경제 산업 재건 계획 말고 다른 부분도 있어?",
  ui_story_5033_50331601_88_dialog_content = "사회 복지 같은 거.",
  ui_story_5033_50331601_89_dialog_content = "고아원을 말하고 싶은 거겠지.",
  ui_story_5033_50331601_90_dialog_content = "안심해라. 섀도우마스터에게 제안하고 싶은 게 있다면 뭐든 이야기하도록.\n그런 건의를 거절하진 않으실 테니까.",
  ui_story_5033_50331601_91_dialog_content = "섀도우마스터도 아이들 입양에 열심인 분이시고... 크흠.",
  ui_story_5033_50331601_92_dialog_content = "그럼 섀도우마스터와 나도 최소한 공통점이 하나는 있는 거구나.\n우리 모두 희망에 부푼 비관주의자라는 거.",
  ui_story_5033_50331601_93_dialog_content = "네 말뜻을 어느 정도는 이해할 수 있겠어.",
  ui_story_5033_50331601_94_dialog_content = "이 세상은 이미 손 쓸 도리가 없다고 여기지만,\n다음 세대에 대해선 여전히 희망을 놓지 않은 거겠지.",
  ui_story_5033_50331601_95_dialog_content = "아이들의 눈빛에 거짓은 없어, 와타리 씨. 고아원이나 학교에 가 봐.",
  ui_story_5033_50331601_96_dialog_content = "거긴 아직까지도 순수함과 선함이 남아있는 곳들이거든.",
  ui_story_5033_50331601_97_dialog_content = "난 오직 아이들만이 유포리아의 하늘이 영원히 맑고 화창할 수 있게\n만들어 줄 거라고 생각해.",
  ui_story_5033_50331601_98_dialog_content = "아마 마틸다 수녀님도 그때 우리랑 같은 생각을 하셨을 거야.",
  ui_story_5033_50331601_99_dialog_content = "......",
  ui_story_5033_50331601_100_dialog_content = "자, 그럼 잡담은 여기까지 할까. 우린 가서 이 계획을 읽어 보고 다시 연락할게.",
  ui_story_5033_50331601_101_dialog_content = "다른 볼일이 없다면, 먼저 가볼게.",
  ui_story_5033_50331601_102_dialog_content = "셔틀허브까지 데려다주지.",
  ui_story_5033_50331601_103_dialog_content = "괜찮아. 공동묘지에 들러야 하거든.",
  ui_story_5033_50331601_104_dialog_content = "마틸다 수녀를 추모하러 가는 건가? 나도 동행할까 하는데, 괜찮을까?",
  ui_story_5033_50331601_105_dialog_content = "물론이지. 고마워, 와타리 씨.",
  ui_story_5033_50331601_106_dialog_content = "오늘은 계속 고맙다는 말만 하는 것 같은데.\n갑자기 그렇게 정중하게 나오니까 적응이 안 된다고.",
  ui_story_5033_50331601_107_dialog_content = "<color=#e8d9bb>콜로서스, 함교</color>",
  ui_story_5033_50331601_108_dialog_content = "커튼 사이즈는... 오케이. 몇 미터 남긴 하는데, 치마로 만들지 뭐.",
  ui_story_5033_50331601_109_dialog_content = "휴.",
  ui_story_5033_50331601_110_dialog_content = "테이블... 플로어 스탠드... 카펫... 카펫은 색상이 좀 다른 것 같은데?",
  ui_story_5033_50331601_111_dialog_content = "휴우.",
  ui_story_5033_50331601_112_dialog_content = "캐비닛... 어, 동물 캐릭터 도마는? 아, 여기 있었네.",
  ui_story_5033_50331601_113_dialog_content = "휴우우...",
  ui_story_5033_50331601_114_dialog_content = "PlayerName, 어디 안 좋아? 물건들 옮기느라 힘들었어?",
  ui_story_5033_50331601_115_dialog_content = "마음이 불편해서 그래, 바이스.",
  ui_story_5033_50331601_116_dialog_content = "요 이틀 동안 있었던 일들은 마치 꿈을 꾼 것만 같거든.",
  ui_story_5033_50331601_117_dialog_content = "왜 넌 매번 내가 멀리 가 있을 때마다 그렇게 이상하고 다양한 모험을 하게 되는 걸까?",
  ui_story_5033_50331601_118_dialog_content = "이번엔 또 무슨 일이 있었는데?",
  ui_story_5033_50331601_119_dialog_content = "어디서부터 이야기를 꺼내야 할지 잘 모르겠으니까,\n생각이 좀 정리될 때까지 조금만 기다려 줘.",
  ui_story_5033_50331601_120_dialog_content = "그래. 참, 이 화분... 음, 「웰빙 수국 화분」? 이건 뭐야?",
  ui_story_5033_50331601_121_dialog_content = "갑자기 사고 싶어져서 산 건데, 벌레가 많이 꼬일 것 같아서 사자마자 후회했어.",
  ui_story_5033_50331601_122_dialog_content = "그래도 더 보고 싶긴 하니까, 그냥 여기 두자.",
  ui_story_5033_50331601_123_dialog_content = "휴, 너 왠지 걱정이 많아 보여.",
  ui_story_5033_50331601_124_dialog_content = "안 되겠어. 이번에 대체 무슨 일이 있었는지 나한테 말해줘.",
  ui_story_5033_50331601_125_dialog_content = "그래. 혹시 「유포리아」란 곳에 대해 들어 본 적 있어?",
  ui_story_5033_50331601_126_dialog_content = "으음... 왠지 들어본 것 같아.",
  ui_story_5033_50331601_127_dialog_content = "응, 일단 이야기를 시작하려면 「유포리아」 얘기부터 해야겠는데..."
}
return config
